# Геометрические пороги (EMU).
CONTAINER_MIN_WIDTH = 2_000_000      # контейнер группы — широкий бесфонный прямоугольник
GROUP_TITLE_MAX_GAP = 1_200_000      # заголовок группы лежит не выше этого над контейнером
