# --------------------------------------------------------------------------------------
# Кто какие таблицы решений читает (process-map-9mn.25, вариант (а))
# --------------------------------------------------------------------------------------
#
# DECISION_TABLES — все таблицы решений владельца по имени. Жила внутри
# самопроверки (owner_tables) и нужна была только ей; теперь по имени таблицы
# отбирает записи decisions_for, а сверку «кто что читает» делает
# unread_decisions — обеим нужен один и тот же реестр, и он обязан быть один.
# Самопроверка сверяет, что под каждым именем лежит одноимённая константа, а не
# соседняя таблица.
#
# Строки ниже для разбора tests/helpers/importerSource.ts невидимы: он ищет
# объявление таблицы ВЕРХНЕГО уровня (имя в первой колонке и `= (`), а здесь
# имена стоят с отступом, ключами словаря. Второго объявления таблицы файл не
# получает.
DECISION_TABLES: dict[str, tuple[dict, ...]] = {
    "OWNER_DECISION_EDGES": OWNER_DECISION_EDGES,
    "STAGE_INPUT_ENRICHMENT": STAGE_INPUT_ENRICHMENT,
    "OWNER_DECISION_EXTERNAL_IO": OWNER_DECISION_EXTERNAL_IO,
    "STAGE_GROUP_SPLIT": STAGE_GROUP_SPLIT,
}

# Какие таблицы читает построитель каждого профиля (решение владельца
# process-map-9mn.31: вариант (а) задачи process-map-9mn.25).
#
# ЗАЧЕМ. Ключ map создаёт ожидание, что решение поддержано для любой карты. Но
# build_single_slide_map (профиль MRP) не читает НИ ОДНОЙ таблицы: запись
# {"map": "mrp", …} прошла бы npm run data зелёным, в карту не попала бы, и в
# отчёте не было бы ни строчки. decisions_for сторожила только обратное
# направление — чтобы чужое решение не применилось к карте.
#
# Объявление держат ДВА сторожа, по одному на направление:
#   · decisions_for останавливает импорт, если код читает таблицу, которой его
#     профиль здесь не объявил, — иначе объявление врало бы в сторону «не
#     читает», и следующий сторож ругался бы на записи, которые на деле
#     применяются;
#   · unread_decisions — ДО сборки, в main(), — если запись объявлена для
#     карты, чей профиль таблицу не читает: такое решение не применится никогда.
#
# Чего не держит никто: профиль ОБЪЯВИЛ таблицу, а его код её так и не открыл.
# Тогда unread_decisions промолчит о записи, которая не применяется. Поэтому
# список перечислен явно, а не «все таблицы» через DECISION_TABLES: новая
# таблица не должна считаться прочитанной профилем, чей код её не открывал.
PROFILE_READS: dict[str, frozenset[str]] = {
    "overview+details": frozenset(
        {
            "OWNER_DECISION_EDGES",
            "STAGE_INPUT_ENRICHMENT",
            "OWNER_DECISION_EXTERNAL_IO",
            "STAGE_GROUP_SPLIT",
        }
    ),
    "single-slide": frozenset(),
    # Трёхуровневая карта inplan (process-map-9mn.14): из четырёх таблиц ей
    # нужна только внешняя система этапа, названная владельцем. Читать её
    # начнёт построитель подзадачи 14.6; до тех пор профиль зарегистрирован
    # заглушкой (см. PROFILE_BUILDERS), которая останавливает импорт раньше,
    # чем что-либо прочитает.
    "three-tier": frozenset({"OWNER_DECISION_EXTERNAL_IO"}),
}


def decision_map(entry: dict, maps: Mapping[str, MapSpec] = MAPS) -> str:
    """
    Карта, к которой относится запись таблицы решений, — проверенная по реестру.

    ЗАПИСЬ БЕЗ КЛЮЧА `map` — ОСТАНОВКА, а не тихое «значит, применять везде»:
    забытый ключ обязан упасть на первом же прогоне, а не через полгода чужим
    ребром в чужой карте.

    Ключ проверяется по реестру MAPS: опечатка в имени карты иначе дала бы
    запись, которая не применится никогда и ни к чему, — самый тихий способ
    потерять решение владельца.
    """
    key = entry.get("map")
    if key is None:
        raise SystemExit(
            f"решение владельца ({entry.get('task', 'без задачи')}) объявлено без "
            f"ключа «map» — непонятно, к какой карте оно относится. Добавьте ключ "
            f"первым полем записи в scripts/import-pptx.py."
        )
    if key not in maps:
        raise SystemExit(
            f"решение владельца ({entry.get('task', 'без задачи')}) объявлено для "
            f"неизвестной карты «{key}». Известны: {', '.join(sorted(maps))}."
        )
    return key


def decisions_for(
    spec: MapSpec, name: str, tables: Mapping[str, Sequence[dict]] = DECISION_TABLES
) -> tuple[dict, ...]:
    """
    Записи таблицы решений владельца `name`, относящиеся ИМЕННО К ЭТОЙ карте.

    ЗАЧЕМ. Все четыре таблицы выше собирались, когда карта была одна, и
    применялись безусловно — любая запись накладывалась на любую карту. Пока
    таблицы описывали только SNP, это не проявлялось: вторая карта собирается
    другим профилем, который до них просто не доходит. Третья карта дойдёт, и
    тогда «этапа 3 нет в презентации» из решения по SNP остановило бы сборку
    чужой карты, а совпадение номеров этапов, наоборот, применило бы к ней
    чужое решение молча. Второе хуже первого. Запись без ключа map или с картой
    не из реестра — остановка (decision_map).

    ПОЧЕМУ ИМЯ ТАБЛИЦЫ, А НЕ САМА ТАБЛИЦА (process-map-9mn.14.1). По имени
    сверяется объявление PROFILE_READS: построитель, прочитавший таблицу,
    которой его профиль не объявил, — остановка. Иначе объявление разошлось бы с
    кодом, и unread_decisions ругалась бы на записи, которые на деле применяются.

    `tables` — только для самопроверки: она передаёт фикстуры параметром, а не
    подменой глобали (см. пункт 1d самопроверки). Рабочий путь зовёт функцию
    без него.

    ПОЧЕМУ КЛЮЧ `map` СТОИТ ПЕРВЫМ ПОЛЕМ ЗАПИСИ. Таблицы для тестов разбирает
    tests/helpers/importerSource.ts — python-литерал целиком, а не регуляркой
    на запись (process-map-n6h). Порядок остальных ключей ему безразличен, а
    первым он требует map (toRecord): по первой строке записи видно, к какой
    карте относится решение, и отбор по карте (recordsFor) делается ДО чтения
    остальных полей — у записей другой карты набор ключей может быть другим.
    Самопроверка держит то же правило (next(iter(entry)) == "map").
    """
    if name not in tables:
        raise SystemExit(
            f"таблицы решений «{name}» нет. Известны: {', '.join(sorted(tables))}."
        )
    reads = PROFILE_READS.get(spec.profile)
    if reads is None or name not in reads:
        declared = ", ".join(sorted(reads)) if reads else "ни одной"
        raise SystemExit(
            f"построитель профиля «{spec.profile}» (карта «{spec.key}») читает таблицу "
            f"{name}, которую PROFILE_READS ему не объявляет (объявлены: {declared}). "
            f"Объявите чтение в PROFILE_READS или не читайте таблицу — иначе "
            f"unread_decisions судит о записях по неверному объявлению."
        )
    return tuple(entry for entry in tables[name] if decision_map(entry) == spec.key)


def unread_decisions(
    tables: Mapping[str, Sequence[dict]],
    maps: Mapping[str, MapSpec],
    reads: Mapping[str, AbstractSet[str]],
) -> list[str]:
    """
    Записи таблиц решений, которые не применятся НИКОГДА: они объявлены для
    карты, чей профиль эту таблицу не читает (process-map-9mn.25, вариант (а)).

    Пустой список — норма. Непустой main() превращает в остановку ДО сборки:
    решение владельца, тихо не попавшее в карту, — ровно то, от чего карта
    защищается выносом решений в таблицы (см. шапку OWNER_DECISION_EDGES).

    Проверяются ВСЕ карты реестра, а не только собираемая: сборка snp
    остановится и на записи для mrp. Так ошибка ловится первым же прогоном
    любой карты, а не когда кто-нибудь соберёт именно ту, к которой она
    относится.

    Реестры приходят параметрами: самопроверка подаёт фикстуры, main() —
    настоящие DECISION_TABLES, MAPS и PROFILE_READS.
    """
    unread: list[str] = []
    for name, table in tables.items():
        for entry in table:
            key = decision_map(entry, maps)
            profile = maps[key].profile
            if name not in reads.get(profile, frozenset()):
                unread.append(
                    f"{name} ({entry.get('task', 'без задачи')}): карта «{key}», "
                    f"профиль «{profile}» эту таблицу не читает"
                )
    return unread


A = "{http://schemas.openxmlformats.org/drawingml/2006/main}"
P = "{http://schemas.openxmlformats.org/presentationml/2006/main}"

TRANSLIT = {
    "а": "a", "б": "b", "в": "v", "г": "g", "д": "d", "е": "e", "ё": "e",
    "ж": "zh", "з": "z", "и": "i", "й": "y", "к": "k", "л": "l", "м": "m",
    "н": "n", "о": "o", "п": "p", "р": "r", "с": "s", "т": "t", "у": "u",
    "ф": "f", "х": "h", "ц": "c", "ч": "ch", "ш": "sh", "щ": "sch",
    "ъ": "", "ы": "y", "ь": "", "э": "e", "ю": "yu", "я": "ya",
}


# --------------------------------------------------------------------------------------
# Вспомогательные структуры
# --------------------------------------------------------------------------------------


@dataclass
class Box:
    """Прямоугольник фигуры в EMU."""

    left: int
    top: int
    width: int
    height: int

    @property
    def right(self) -> int:
        return self.left + self.width

    @property
    def bottom(self) -> int:
        return self.top + self.height

    @property
    def cx(self) -> float:
        return self.left + self.width / 2

    @property
    def cy(self) -> float:
        return self.top + self.height / 2

    @property
    def area(self) -> int:
        return self.width * self.height

    def contains_point(self, x: float, y: float) -> bool:
        return self.left <= x <= self.right and self.top <= y <= self.bottom

    def distance_to_point(self, x: float, y: float) -> float:
        dx = max(self.left - x, 0.0, x - self.right)
        dy = max(self.top - y, 0.0, y - self.bottom)
        return math.hypot(dx, dy)


@dataclass
class Shape:
    """Нормализованное представление фигуры слайда."""

    sid: int
    kind: str            # 'auto' | 'line' | 'textbox' | 'placeholder' | 'other'
    box: Box
    paragraphs: list[str]
    fill: str | None     # 'srgb:RRGGBB' | 'scheme:name' | 'noFill' | None
    flip_h: bool
    flip_v: bool
    # Поворот фигуры вокруг центра bbox, в градусах (a:xfrm/@rot делится на 60000).
    # У повёрнутого коннектора left/top/width/height описывают НЕПОВЁРНУТУЮ
    # рамку, поэтому концы линии надо доворачивать (process-map-3wh.18).
    rot: float
    head_arrow: bool
    tail_arrow: bool
    # Явные привязки коннектора к фигурам (a:stCxn/a:endCxn).
    #
    # ВНИМАНИЕ, РАСПРОСТРАНЁННОЕ ЗАБЛУЖДЕНИЕ: считалось, что в презентации SNP
    # привязок нет и потому связи приходится выводить геометрически. Это НЕВЕРНО
    # (проверено перебором, process-map-3wh.8): из 66 линий 47 имеют ОБЕ
    # привязки и только 10 не имеют ни одной. Импортёр их просто никогда не
    # читал. Разбор SNP остаётся геометрическим — менять содержание
    # опубликованной карты эта задача не может, — но см. process-map-3wh.16.
    #
    # Профилю «одиночный слайд» привязки нужны: у линии [112] слайда 8 bbox
    # уходит на 1.28 млн EMU ниже слайда (растянутый коннектор после
    # перемещения фигур), геометрия её теряет, а привязка — нет.
    start_sid: int | None = None
    end_sid: int | None = None
    consumed_by: str | None = None   # для отчёта: кто «съел» текстовую фигуру
    # Заливка ВМЕСТЕ С МОДИФИКАТОРАМИ ЦВЕТА (read_fill_key), например
    # 'scheme:tx2|alpha76000+lumMod65000+lumOff35000'. Отдельное поле рядом с
    # fill, а не вместо него: fill сравнивается на точное равенство в
    # классификаторах обеих опубликованных карт (см. read_fill_key).
    fill_key: str | None = None
    # shape_id группы, внутри которой фигура нашлась (None — лежит прямо на
    # слайде). Для отчёта: заход в группы обязан быть виден, а не молчалив.
    inside_group: int | None = None

    # Оба поля стоят в конце, потому что у них есть умолчания, а dataclass
    # требует, чтобы поля с умолчаниями шли после полей без них. Втиснуть их к
    # родственному по смыслу `fill` не выйдет, не раздав умолчаний половине
    # dataclass'а.

    @property
    def text(self) -> str:
        return " ".join(self.paragraphs).strip()

    @property
    def has_text(self) -> bool:
        return bool(self.paragraphs)

    def sort_key(self) -> tuple[int, int, int]:
        return (self.box.top, self.box.left, self.sid)


@dataclass
class NodeDraft:
    node_id: str
    node_type: str
    label: str
    box: Box
    group: str | None = None
    # Колонка data-узла на экране детализации (SPEC §3/§4.2, задача
    # process-map-24p): 'in' — вход этапа, 'out' — выход.
    #
    # НЕ ЭВРИСТИКА И НЕ ГЕОМЕТРИЯ, а происхождение фигуры: у импортёра ровно
    # два места, где рождается data-узел, и каждое знает направление точно —
    #   · build_stage, шаг 4 «левая колонка входов» слайда детализации → 'in';
    #   · build_process_map, блоки выходов этапа под его контейнером на слайде
    #     обзора (слайд 2)                                             → 'out'.
    # Больше никакой путь data-узел не создаёт: node_type_for() возвращает
    # только step/integration/warning. Поэтому поле проставлено у всех
    # data-узлов, а у остальных типов его нет — там оно бессмысленно.
    #
    # Выводить направление из координат нельзя: блоки выходов этапов 1 и 2
    # презентация рисует под контейнером этапа на слайде обзора, и по абсциссе
    # они оказываются ЛЕВЕЕ середины области шагов — прежнее правило «левее
    # середины = вход» давало у этих этапов ноль выходов.
    direction: str | None = None
    description_parts: list[str] = field(default_factory=list)
    inputs: list[str] = field(default_factory=list)
    outputs: list[str] = field(default_factory=list)
    system: str | None = None

    @property
    def description(self) -> str | None:
        return "\n".join(self.description_parts) if self.description_parts else None


# Роли слайда в отчёте (SlideReport.role). Набор расширяют профили, которым
# нужен свой блок отчёта; неизвестная роль — ошибка программиста, а не данных.
SLIDE_ROLES = ("overview", "detail")


@dataclass
class SlideReport:
    slide_no: int
    # Чем слайд служит карте: 'overview' — обзор этапов, 'detail' — слайд, с
    # которого собираются узлы этапа (process-map-9mn.14.1).
    #
    # ПОЧЕМУ ПОЛЕ, А НЕ `slide_no == 2`. print_report раньше узнавал обзор по
    # номеру слайда — а это свойство ОДНОЙ презентации (SNP: обзор на втором
    # слайде). Профиль single-slide с рабочим слайдом 2 получил бы шапку обзора
    # вместо счётчиков узлов, а в колоде трёхуровневой карты второй слайд — вовсе
    # не обзор этапов. Роль ставит построитель, который знает устройство своей
    # презентации; отчёт по ней только печатает.
    role: str = "detail"
    nodes: int = 0
    data_nodes: int = 0
    groups: int = 0
    edges: int = 0
    lines_total: int = 0
    promoted: list[str] = field(default_factory=list)
    lines_skipped: list[str] = field(default_factory=list)
    text_skipped: list[str] = field(default_factory=list)
    loose_attachments: list[str] = field(default_factory=list)
    questions: list[str] = field(default_factory=list)
    # Артефакты, названные выходом этапа в обзоре, но уже существующие узлом
    # колонки входов на слайде детализации (задача process-map-24p).
    dedup_key_outputs: list[str] = field(default_factory=list)
    # Рёбра, добавленные не из презентации, а по решению владельца процесса
    # (OWNER_DECISION_EDGES, задача process-map-7bz).
    owner_edges: list[str] = field(default_factory=list)
    # Входы, добавленные и переформулированные по слайду обзора
    # (STAGE_INPUT_ENRICHMENT, задача process-map-qjl).
    owner_inputs: list[str] = field(default_factory=list)
    # Внешние системы, названные владельцем, а не выведенные из текста
    # (process-map-vjz.5). Живёт на отчёте слайда 2: таблица привязана к обзору.
    owner_external_io: list[str] = field(default_factory=list)
    # Узлы, повышенные из step в integration по коду системы (process-map-7v1).
    promoted_integrations: list[str] = field(default_factory=list)
    # Узлы, перенесённые в отдельную группу по решению владельца
    # (STAGE_GROUP_SPLIT, задача process-map-028).
    owner_groups: list[str] = field(default_factory=list)
    # Рёбра, у которых хотя бы один конец разрешён явной привязкой коннектора,
    # а не геометрией (process-map-3wh.16).
    cxn_edges: list[str] = field(default_factory=list)
    # Фигуры, найденные ВНУТРИ групп (p:grpSp), а не прямо на слайде
    # (process-map-9mn.13). Пустой список означает «групп на слайде нет», а не
    # «не смотрели»: read_slide заходит в группы всегда.
    from_groups: list[str] = field(default_factory=list)
    # Какой веткой phase_band нашёл полосу фаз: 'containers' | 'top-row'.
    # None — полосу фаз на этом слайде не искали: ни один из двух собранных
    # профилей этого не делает, ярусы нужны третьему (process-map-9mn.13).
    phase_band_rule: str | None = None
    # Реестр модулей с навигационных слайдов (read_module_index,
    # process-map-9mn.14.2): порядок кнопок навигации рядом с порядком колоды
    # и строки реестра. Пусто — навигационных слайдов не читали: у презентаций
    # SNP и MRP их нет, реестр нужен только трёхуровневой карте.
    module_index: list[str] = field(default_factory=list)
    # Слайд 1 трёхуровневой карты (process-map-9mn.14.3). Пусто — слайда модулей
    # не читали: у презентаций SNP и MRP его нет, и блоки отчёта по этим полям
    # печатаются, только если поля заполнены.
    #   · module_columns — ряды автофигур, колонки ряда модулей и правило, по
    #     которому опознана каждая коробка (chevron_columns);
    #   · module_transfers — сторож стрелок и судьба каждой плашки над рядом
    #     (check_transfer_arrows, classify_transfer);
    #   · module_lanes — полосы под рядом (lanes_from_slide1);
    #   · activity_check — сверка списков действий с шагами слайдов детализации
    #     (reconcile_activity_lists). Только отчёт: в данные списки не идут.
    module_columns: list[str] = field(default_factory=list)
    module_transfers: list[str] = field(default_factory=list)
    module_lanes: list[str] = field(default_factory=list)
    activity_check: list[str] = field(default_factory=list)

    def __post_init__(self) -> None:
        if self.role not in SLIDE_ROLES:
            raise ValueError(
                f"SlideReport: неизвестная роль слайда «{self.role}», "
                f"известны: {', '.join(SLIDE_ROLES)}"
            )


# --------------------------------------------------------------------------------------
# Чтение презентации
# --------------------------------------------------------------------------------------


def normalize_text(value: str) -> str:
    """\x0b — мягкий перенос строки внутри абзаца PowerPoint; схлопываем пробелы."""
    value = value.replace("\x0b", " ").replace(" ", " ")
    return re.sub(r"\s+", " ", value).strip()


def read_paragraphs(shape) -> list[str]:
    """
    Абзацы текстовой фигуры.

    PowerPoint иногда разбивает одну фразу на два абзаца («Информация по будущим» /
    «заказам клиентов»). Признак продолжения — следующий абзац начинается со строчной
    буквы или со служебного символа продолжения; такие абзацы склеиваем.
    Списки (каждый пункт с заглавной буквы) при этом не страдают.
    """
    if not shape.has_text_frame:
        return []
    raw = [normalize_text(p.text) for p in shape.text_frame.paragraphs]
    raw = [p for p in raw if p]
    merged: list[str] = []
    for para in raw:
        first = para[0]
        if merged and (first.islower() or first in "/,;)"):
            merged[-1] = f"{merged[-1]} {para}".strip()
        else:
            merged.append(para)
    return merged


def read_fill(element) -> str | None:
    """Явная заливка из spPr (заливка по теме через p:style здесь не учитывается)."""
    sp_pr = element.find(P + "spPr")
    if sp_pr is None:
        return None
    for child in sp_pr:
        tag = etree.QName(child).localname
        if tag == "noFill":
            return "noFill"
        if tag == "solidFill":
            if len(child) == 0:
                return "solid"
            color = child[0]
            local = etree.QName(color).localname
            if local == "srgbClr":
                return "srgb:" + str(color.get("val")).upper()
            return "scheme:" + str(color.get("val"))
        if tag.endswith("Fill"):
            return tag
    return None


def read_fill_key(element) -> str | None:
    """
    Заливка ВМЕСТЕ С МОДИФИКАТОРАМИ ЦВЕТА:
    'scheme:tx2|alpha76000+lumMod65000+lumOff35000'.

    ЗАЧЕМ ОТДЕЛЬНАЯ ФУНКЦИЯ, А НЕ ПРАВКА read_fill. Результат read_fill
    сравнивается на ТОЧНОЕ РАВЕНСТВО в четырёх местах, от которых зависит
    классификация узлов обеих опубликованных карт: is_integration
    (srgb:A6A6A6), is_container (noFill), is_artifact_box (scheme:accent2) и
    подбор боксов в build_overview. Добавь модификаторы в общий ключ — и
    фигура, у которой к той же заливке приписан lumMod, перестанет совпадать
    со строкой-эталоном. Карта пересобралась бы с другой классификацией узлов
    МОЛЧА: ни одна проверка не сверяет типы узлов с презентацией, сверять не с
    чем. Поэтому read_fill остаётся как есть, а модификаторы читает соседняя
    функция, и пользуются ею только новые правила.

    ЗАЧЕМ ВООБЩЕ. На слайде 3 презентации L2 фаза [67] и шаг [124] — это
    schemeClr tx2 С модификаторами (lumMod 65000, lumOff 35000, alpha 76000), а
    подробности [44], [50], [63]…[66], [70] — тот же tx2 БЕЗ модификаторов.
    read_fill отдаёт для всех восьми одно и то же 'scheme:tx2', то есть два
    разных яруса карты становятся неразличимы.

    МОДИФИКАТОРЫ ОТСОРТИРОВАНЫ по имени: их порядок в XML — дело PowerPoint, и
    ключ, зависящий от порядка, развёл бы одинаковые заливки на два яруса.
    Модификатор без val (такие бывают, например a:gamma) сохраняется одним
    именем — потерять его молча нельзя.
    """
    sp_pr = element.find(P + "spPr")
    if sp_pr is None:
        return None
    for child in sp_pr:
        tag = etree.QName(child).localname
        if tag == "noFill":
            return "noFill"
        if tag == "solidFill":
            if len(child) == 0:
                return "solid"
            color = child[0]
            local = etree.QName(color).localname
            if local == "srgbClr":
                base = "srgb:" + str(color.get("val")).upper()
            else:
                base = "scheme:" + str(color.get("val"))
            mods = sorted(
                f"{etree.QName(mod).localname}{mod.get('val') or ''}" for mod in color
            )
            return f"{base}|{'+'.join(mods)}" if mods else base
        if tag.endswith("Fill"):
            return tag
    return None


def read_line_ends(element) -> tuple[bool, bool]:
    """Наличие стрелок на концах линии (a:ln/a:headEnd, a:tailEnd)."""
    sp_pr = element.find(P + "spPr")
    if sp_pr is None:
        return (False, False)
    ln = sp_pr.find(A + "ln")
    if ln is None:
        return (False, False)

    def is_arrow(tag: str) -> bool:
        node = ln.find(A + tag)
        if node is None:
            return False
        return str(node.get("type") or "none") != "none"

    return (is_arrow("headEnd"), is_arrow("tailEnd"))


def read_connection(element) -> tuple[int | None, int | None]:
    """
    Привязки коннектора к фигурам: (id начала, id конца) из a:stCxn / a:endCxn.

    Живут в p:cxnSp/p:nvCxnSpPr/p:cNvCxnSpPr. У обычной фигуры этого узла нет,
    у неприкреплённого коннектора — нет атрибутов; и то и другое даёт None.
    """
    nv = element.find(P + "nvCxnSpPr")
    if nv is None:
        return (None, None)
    props = nv.find(P + "cNvCxnSpPr")
    if props is None:
        return (None, None)

    def sid_of(tag: str) -> int | None:
        node = props.find(A + tag)
        if node is None:
            return None
        raw = node.get("id")
        return int(raw) if raw is not None and raw.isdigit() else None

    return (sid_of("stCxn"), sid_of("endCxn"))


def read_rotation(element) -> float:
    """Поворот фигуры в градусах из a:xfrm/@rot (единица — 1/60000 градуса)."""
    sp_pr = element.find(P + "spPr")
    if sp_pr is None:
        return 0.0
    node = sp_pr.find(A + "xfrm")
    if node is None:
        return 0.0
    raw = node.get("rot")
    if raw is None:
        return 0.0
    try:
        return int(raw) / 60000.0
    except ValueError:
        return 0.0


def read_flips(element) -> tuple[bool, bool]:
    sp_pr = element.find(P + "spPr")
    if sp_pr is None:
        return (False, False)
    node = sp_pr.find(A + "xfrm")
    if node is None:
        return (False, False)
    return (node.get("flipH") == "1", node.get("flipV") == "1")


def classify_shape_kind(shape) -> str:
    st = shape.shape_type
    if st == MSO_SHAPE_TYPE.LINE:
        return "line"
    if st == MSO_SHAPE_TYPE.TEXT_BOX:
        return "textbox"
    if st == MSO_SHAPE_TYPE.PLACEHOLDER:
        return "placeholder"
    if st == MSO_SHAPE_TYPE.AUTO_SHAPE:
        return "auto"
    return "other"


# Преобразование «координаты как есть»: слой прямо на слайде.
IDENTITY_TRANSFORM: tuple[float, float, float, float] = (0.0, 0.0, 1.0, 1.0)


def group_transform(element) -> tuple[float, float, float, float]:
    """
    Аффинное преобразование из системы координат ДЕТЕЙ группы в систему слайда:
    (dx, dy, sx, sy), где x_слайда = dx + sx · x_ребёнка.

    Группа хранит ДВЕ рамки (p:grpSpPr/a:xfrm): a:off + a:ext — где группа
    лежит на слайде, a:chOff + a:chExt — в каких координатах записаны её дети.
    Совпадают они далеко не всегда: у групп слайда 9 презентации L2
    преобразование тождественно (off == chOff, ext == chExt), а у групп слайда
    3 — нет. Поэтому «просто взять left/top ребёнка» неверно, и проверить это
    на одном слайде нельзя.

    ПОВЁРНУТАЯ ГРУППА — ОСТАНОВКА ИМПОРТА. Поворот вокруг центра группы
    превращает прямоугольник ребёнка в прямоугольник, у которого нет
    представления в модели Box (у неё нет угла), а положить фигуру НЕ ТУДА
    можно совершенно незаметно: координаты остаются правдоподобными. Лучше
    громко отказаться, чем собрать карту, где часть шагов стоит не в своих
    этапах. То же и с отражением группы (flipH/flipV): зеркалить содержимое
    этим преобразованием нечем.
    Ни в одной из трёх презентаций репозитория повёрнутых и отражённых групп
    нет (проверено перебором grpSpPr), так что сегодня эта ветка молчит.
    """
    grp_sp_pr = element.find(P + "grpSpPr")
    xfrm = grp_sp_pr.find(A + "xfrm") if grp_sp_pr is not None else None
    if xfrm is None:
        return IDENTITY_TRANSFORM

    raw_rot = xfrm.get("rot")
    if raw_rot is not None and int(raw_rot) % 21_600_000 != 0:
        raise SystemExit(
            f"группа повёрнута на {int(raw_rot) / 60000.0}° — зайти внутрь нельзя: "
            f"повёрнутую рамку ребёнка выразить нечем, а поставить фигуру не туда "
            f"можно молча. Разверните группу в презентации или разгруппируйте её."
        )
    if xfrm.get("flipH") == "1" or xfrm.get("flipV") == "1":
        raise SystemExit(
            "группа отражена (flipH/flipV) — зайти внутрь нельзя по той же причине, "
            "что и в повёрнутую: зеркалить содержимое этим преобразованием нечем."
        )

    off = xfrm.find(A + "off")
    ext = xfrm.find(A + "ext")
    ch_off = xfrm.find(A + "chOff")
    ch_ext = xfrm.find(A + "chExt")
    if off is None or ext is None or ch_off is None or ch_ext is None:
        # Не объявлена хотя бы одна из двух рамок — ни рамку группы, ни рамку
        # детей поодиночке применить не к чему: преобразование задаёт только их
        # ПАРА. По умолчанию они совпадают, то есть дети записаны прямо в
        # координатах слайда.
        return IDENTITY_TRANSFORM

    child_cx, child_cy = int(ch_ext.get("cx")), int(ch_ext.get("cy"))
    if child_cx == 0 or child_cy == 0:
        raise SystemExit(
            "у группы нулевая рамка детей (a:chExt) — масштаб не определён, "
            "зайти внутрь нельзя"
        )
    scale_x = int(ext.get("cx")) / child_cx
    scale_y = int(ext.get("cy")) / child_cy
    return (
        int(off.get("x")) - int(ch_off.get("x")) * scale_x,
        int(off.get("y")) - int(ch_off.get("y")) * scale_y,
        scale_x,
        scale_y,
    )


def compose_transform(
    outer: tuple[float, float, float, float],
    inner: tuple[float, float, float, float],
) -> tuple[float, float, float, float]:
    """Преобразование вложенной группы: сначала внутреннее, затем внешнее."""
    return (
        outer[0] + outer[2] * inner[0],
        outer[1] + outer[3] * inner[1],
        outer[2] * inner[2],
        outer[3] * inner[3],
    )


def transformed_box(
    transform: tuple[float, float, float, float], left: int, top: int, width: int, height: int
) -> Box:
    """
    Рамка фигуры в координатах слайда.

    Отдельной ветки «тождество — вернуть как есть» здесь НЕТ намеренно, хотя
    напрашивается: она была бы неубиваемой. Координаты слайда не выходят за
    12.2 млн EMU, для таких целых round(0.0 + 1.0·x) возвращает ровно x, и
    убрать такую ветку не смогла бы заметить ни одна проверка. Что целые
    координаты доезжают до JSON целыми, сторожит побайтовое совпадение
    пересобранных карт: групп в обеих презентациях нет, значит весь их разбор
    идёт этим самым тождественным преобразованием.
    """
    dx, dy, scale_x, scale_y = transform
    return Box(
        round(dx + scale_x * left),
        round(dy + scale_y * top),
        round(scale_x * width),
        round(scale_y * height),
    )


def read_shapes(
    shapes,
    transform: tuple[float, float, float, float] = IDENTITY_TRANSFORM,
    inside: int | None = None,
) -> list[Shape]:
    """
    Фигуры коллекции, включая лежащие ВНУТРИ групп (p:grpSp).

    ЗАЧЕМ ЗАХОДИТЬ В ГРУППЫ. Раньше импортёр читал только верхний уровень, и
    сгруппированная фигура просто не существовала для него. На слайде 9
    презентации L2 девять подписей шагов из двенадцати лежат в трёх группах:
    без захода карта MRP потеряла бы три четверти шагов МОЛЧА — ни одна
    проверка не знает, сколько шагов должно было получиться.

    БЕЗОПАСНОСТЬ ДЛЯ ДВУХ ОПУБЛИКОВАННЫХ КАРТ ДОКАЗАНА ПЕРЕБОРОМ, а не оценена:
    в презентации «SNP Е2Е процесс.pptx» групп нет ни одной на все шесть
    слайдов, на слайде 8 «In.Plan MRP 17-08-2026.pptx» — тоже ни одной (группы
    в той колоде есть, но на слайдах 2, 3, 7, 26, 31, которых импортёр не
    читает). То есть заход не может ничего в них изменить, и это проверяется
    побайтовым совпадением пересобранных карт.

    Сама группа фигурой НЕ становится: у неё нет ни текста, ни заливки, а её
    рамка — служебная и попала бы в геометрию контейнеров и подписей.
    """
    result: list[Shape] = []
    for shape in shapes:
        if shape.shape_type == MSO_SHAPE_TYPE.GROUP:
            result.extend(
                read_shapes(
                    shape.shapes,
                    compose_transform(transform, group_transform(shape._element)),  # noqa: SLF001
                    int(shape.shape_id),
                )
            )
            continue
        if shape.left is None or shape.top is None:
            continue
        element = shape._element  # noqa: SLF001 — python-pptx не даёт публичного доступа к XML
        flip_h, flip_v = read_flips(element)
        head_arrow, tail_arrow = read_line_ends(element)
        start_sid, end_sid = read_connection(element)
        rot = read_rotation(element)
        result.append(
            Shape(
                sid=int(shape.shape_id),
                kind=classify_shape_kind(shape),
                box=transformed_box(
                    transform,
                    int(shape.left),
                    int(shape.top),
                    int(shape.width),
                    int(shape.height),
                ),
                paragraphs=read_paragraphs(shape),
                fill=read_fill(element),
                flip_h=flip_h,
                flip_v=flip_v,
                rot=rot,
                head_arrow=head_arrow,
                tail_arrow=tail_arrow,
                start_sid=start_sid,
                end_sid=end_sid,
                fill_key=read_fill_key(element),
                inside_group=inside,
            )
        )
    return result


def read_slide(slide, report: SlideReport | None = None) -> list[Shape]:
    """
    Фигуры слайда в едином порядке Shape.sort_key — обёртка над read_shapes.

    Сортировка одна на весь слайд, а не по уровням вложенности: после
    преобразования координат фигура из группы ничем не отличается от лежащей
    прямо на слайде, и разбор обязан видеть их вперемешку — так же, как их
    видит читатель презентации.
    """
    shapes = read_shapes(slide.shapes)
    shapes.sort(key=Shape.sort_key)
    if report is not None:
        for shape in shapes:
            if shape.inside_group is None:
                continue
            label = shape.text[:60] if shape.has_text else f"{shape.kind} без текста"
            report.from_groups.append(
                f"слайд {report.slide_no}: [{shape.sid}] «{label}» — внутри группы "
                f"[{shape.inside_group}]"
            )
    return shapes


# --------------------------------------------------------------------------------------
# Генерация идентификаторов
# --------------------------------------------------------------------------------------


def transliterate(value: str) -> str:
    return "".join(TRANSLIT.get(ch, ch) for ch in value.lower())


def slugify(value: str, max_length: int = MAX_ID_LENGTH) -> str:
    slug = re.sub(r"[^a-z0-9]+", "-", transliterate(value)).strip("-")
    if len(slug) > max_length:
        cut = slug[:max_length]
        if "-" in cut:
            cut = cut[: cut.rindex("-")]
        slug = cut.strip("-")
    return slug or "node"


class IdFactory:
    """
    Стабильные kebab-case id.

    Работает в двух фазах. В первой (collisions=None) фабрика только считает,
    сколько раз встретился каждый базовый slug. Во второй ей передают эту карту:
    уникальный slug становится id как есть, а ВСЕ участники коллизии получают
    суффикс «-<слайд>-<shape_id>». Благодаря этому id не зависит от порядка
    обхода фигур и не меняется, если удалить или переставить соседнюю фигуру.
    """

    def __init__(self, collisions: dict[str, int] | None = None, max_length: int = MAX_ID_LENGTH) -> None:
        self._collisions = collisions
        self._counts: Counter[str] = Counter()
        self._used: set[str] = set()
        self._max_length = max_length

    @property
    def counts(self) -> Counter[str]:
        return self._counts

    def make(self, source: str, slide: int, sid: int, index: int = 0) -> str:
        base = slugify(source, self._max_length)
        self._counts[base] += 1
        if self._collisions is None:
            candidate = f"{base}~{self._counts[base]}"
        else:
            candidate = base if self._collisions.get(base, 0) <= 1 else f"{base}-{slide}-{sid}"
            if candidate in self._used:
                candidate = f"{candidate}-{index}"
            extra = 2
            while candidate in self._used:
                candidate = f"{base}-{slide}-{sid}-{index}-{extra}"
                extra += 1
        self._used.add(candidate)
        return candidate


# --------------------------------------------------------------------------------------
# Правила классификации (SPEC §3: NodeType = step | data | integration | warning)
# --------------------------------------------------------------------------------------

INTEGRATION_FILL = "srgb:A6A6A6"
INTEGRATION_TEXT_RE = re.compile(r"^Передача\b.*\b(из|в)\s+модул", re.IGNORECASE)
WARNING_TEXT_RE = re.compile(r"предупрежден", re.IGNORECASE)
WARNING_ITEM_RE = re.compile(r"^Предупреждени", re.IGNORECASE)
# Как система названа в тексте презентации -> её код в схеме.
#
# ПОЧЕМУ АЛИАСЫ, А НЕ НОВЫЕ КОДЫ. Владелец уже зафиксировал в src/i18n/ru.ts,
# что IO расшифровывается как MEIO (Multi Echelon Inventory Optimization), а
# INPLAN — это SNP (Supply Network Planning). Завести MEIO и SNP отдельными
# кодами значило бы получить два кода на один модуль — против process-map-b67.
# На слайде 8 презентации MRP модули названы полными именами, поэтому без
# алиасов автоматика молчит: у карты не было бы ни одной внешней системы.
#
# Для карты SNP это безопасно и проверено: в её текстах слова «SNP» и «MEIO»
# как отдельные токены не встречаются ни разу, а сторож — побайтовое совпадение
# пересобранного файла (process-map-3wh.10).
SYSTEM_ALIASES = {"MEIO": "IO", "SNP": "INPLAN"}

# Длинные токены раньше коротких: альтернация в регулярке жадна по порядку.
SYSTEM_TOKENS = tuple(sorted(set(SYSTEM_CODES) | set(SYSTEM_ALIASES), key=len, reverse=True))
SYSTEM_RE = re.compile(r"(?<![A-Za-zА-Яа-я])(" + "|".join(SYSTEM_TOKENS) + r")(?![A-Za-zА-Яа-я])")
DIRECTION_IN_RE = re.compile(r"\bиз\s+модул", re.IGNORECASE)
DIRECTION_OUT_RE = re.compile(r"(\bв\s+модул|Выгрузка\s+в\b)", re.IGNORECASE)


def is_integration(shape: Shape) -> bool:
    """
    Интеграция — серый бокс (заливка A6A6A6) либо текст вида
    «Передача … из/в модуль X». Оба признака взяты из презентации напрямую.
    """
    if shape.fill == INTEGRATION_FILL:
        return True
    return bool(INTEGRATION_TEXT_RE.search(shape.text))


def is_warning(shape: Shape) -> bool:
    """
    Предупреждение — узел, предметом которого является формирование/расчёт
    предупреждения (отдельной заливки для предупреждений в презентации нет,
    единственный однозначный признак — текст).
    """
    return bool(WARNING_TEXT_RE.search(shape.text))


def node_type_for(shape: Shape) -> str:
    if is_integration(shape):
        return "integration"
    if is_warning(shape):
        return "warning"
    return "step"


def detect_system(text: str) -> str | None:
    match = SYSTEM_RE.search(text)
    if match is None:
        return None
    return SYSTEM_ALIASES.get(match.group(1), match.group(1))


def detect_systems(text: str) -> list[str]:
    """
    ВСЕ системы, названные в тексте, в порядке появления и без повторов.

    Нужна там, где одна подпись называет несколько модулей сразу: «Плановые
    заказы из SNP, PS» на слайде 8 — это два входа, а не один. detect_system
    отдаёт только первый и для такого случая не годится.
    """
    seen: set[str] = set()
    codes: list[str] = []
    for match in SYSTEM_RE.finditer(text):
        code = SYSTEM_ALIASES.get(match.group(1), match.group(1))
        if code not in seen:
            seen.add(code)
            codes.append(code)
    return codes


def detect_direction(text: str) -> str | None:
    if DIRECTION_IN_RE.search(text):
        return "in"
    if DIRECTION_OUT_RE.search(text):
        return "out"
    return None


def is_container(shape: Shape) -> bool:
    """Контейнер группы — широкий бесфонный прямоугольник без текста."""
    return (
        shape.kind == "auto"
        and not shape.has_text
        and shape.fill == "noFill"
        and shape.box.width >= CONTAINER_MIN_WIDTH
    )


def is_decor_arrow(shape: Shape) -> bool:
    """
    Мелкая стрелка-иконка между узлами: автофигура без текста, узкая.

    ЗАЛИВКА НЕ ПРОВЕРЯЕТСЯ (process-map-3wh.8). Раньше требовалось fill is None,
    и это работало, пока стрелки были только в презентации SNP. На слайде 8
    презентации MRP такие же стрелки залиты scheme:accent1 — предикат не
    срабатывал, и восемь связей «шаг → шаг» терялись целиком: линиями они там не
    нарисованы вовсе.

    Снятие условия для SNP безопасно и проверено перебором: маленьких
    бестекстовых автофигур на всех шести слайдах ровно шесть, все на слайде 2,
    у всех заливки нет. Сторож — побайтовое совпадение пересобранного файла.
    """
    return (
        shape.kind == "auto"
        and not shape.has_text
        and shape.box.width <= DECOR_ARROW_MAX_WIDTH
    )


def is_caption_long_form(paragraphs: Sequence[str]) -> bool:
    """
    Подпись под узлом — либо перечень выходов, либо развёрнутое описание.
    Описание распознаём по двоеточию, маркерам списка «-» или очень длинному абзацу.
    """
    joined = " ".join(paragraphs)
    if ":" in joined:
        return True
    if any(p.startswith("-") for p in paragraphs):
        return True
    return any(len(p) > 90 for p in paragraphs)


# --------------------------------------------------------------------------------------
# Дедупликация ExternalIO
# --------------------------------------------------------------------------------------

IO_STOP_WORDS = {
    "передача", "передать", "из", "в", "во", "на", "и", "с", "до",
    "модуль", "модуля", "модулей", "выгрузка",
}
IO_MATCH_RATIO = 0.75
IO_MATCH_MIN_COMMON = 2


def io_tokens(text: str) -> set[str]:
    """
    Грубые «стемы» содержательных слов подписи интеграции: нижний регистр, ё→е,
    выброшены стоп-слова, остальное обрезано до 4 символов. Коды систем сохраняются
    целиком. Нужны, чтобы одна и та же передача, описанная на слайде обзора и на
    слайде детализации разными словами, не превратилась в две записи ExternalIO.
    """
    words = re.findall(r"[a-zа-я0-9]+", text.lower().replace("ё", "е"))
    tokens: set[str] = set()
    for word in words:
        if word.upper() in SYSTEM_CODES:
            tokens.add(word)
            continue
        if word in IO_STOP_WORDS or len(word) < 3:
            continue
        tokens.add(word[:4])
    return tokens


def same_transfer(first: str, second: str) -> bool:
    a, b = io_tokens(first), io_tokens(second)
    if not a or not b:
        return first == second
    common = len(a & b)
    if common < IO_MATCH_MIN_COMMON:
        return False
    return common / min(len(a), len(b)) >= IO_MATCH_RATIO


def add_external_io(bucket: list[dict], entry: dict) -> bool:
    """Добавляет ExternalIO, если такая же передача ещё не записана."""
    for existing in bucket:
        if existing["system"] == entry["system"] and same_transfer(existing["label"], entry["label"]):
            return False
    bucket.append(entry)
    return True


# --------------------------------------------------------------------------------------
# Геометрия: группы, подписи, рёбра
# --------------------------------------------------------------------------------------


def find_title_for_container(container: Shape, textboxes: Sequence[Shape]) -> Shape | None:
    """
    Заголовок группы — однострочный TEXT_BOX прямо над контейнером
    (горизонтальное пересечение, верх в окне [container.top - GAP, container.top)).
    Берём самый нижний из подходящих.
    """
    best: Shape | None = None
    for tb in textboxes:
        if tb.consumed_by is not None or len(tb.paragraphs) != 1:
            continue
        if not (container.box.top - GROUP_TITLE_MAX_GAP <= tb.box.top < container.box.top):
            continue
        if tb.box.right <= container.box.left or tb.box.left >= container.box.right:
            continue
        if best is None or tb.box.top > best.box.top:
            best = tb
    return best


def innermost_container(containers: Sequence[tuple[Shape, str]], box: Box) -> str | None:
    """Группа узла — самый маленький контейнер, содержащий центр узла."""
    best: tuple[int, str] | None = None
    for shape, group_id in containers:
        if shape.box.contains_point(box.cx, box.cy):
            if best is None or shape.box.area < best[0]:
                best = (shape.box.area, group_id)
    return best[1] if best else None


# --------------------------------------------------------------------------------------
# Ярусы слайда: полоса фаз и разведение шагов с подробностями
# --------------------------------------------------------------------------------------
#
# ЯРУС ОПРЕДЕЛЯЕТСЯ СИГНАТУРОЙ ЗАЛИВКИ, А НЕ КООРДИНАТОЙ Y. Соблазн «верхний
# ряд — фазы, следующий — шаги, нижний — подробности» разбивается о замер: на
# слайдах 5, 7 и 11 презентации L2 есть ШАГИ НИЖЕ яруса подробностей — левая
# колонка входов продолжается под ним ([38] слайда 5, [38] слайда 7, [55]
# слайда 11). Правило «по y» отправило бы эти три шага в подробности.
#
# Координата y при этом нужна — но ОДИН раз и не для классификации: полоса фаз
# ищется как верхний ряд, а дальше ярус каждой фигуры определяет её заливка.
# Поэтому низко лежащий шаг остаётся шагом: у него заливка фазы, под которой
# он стоит.
#
# ЗАЛИВКА БЕРЁТСЯ С МОДИФИКАТОРАМИ (read_fill_key). Без них правило не работает
# вовсе: на слайде 3 фаза [67], шаги [51], [124] и семь коробок подробностей —
# всё это schemeClr tx2, и различаются они ровно модификаторами.

# Разброс верха фигур внутри одного ряда. Замер по всем рядам, которые
# group_rows строит на слайдах 3/5/7/11 колоды L2 (не только по полосам фаз):
#
#   · максимальный разброс ВНУТРИ ряда — 20426 EMU: слайд 7, ряд подробностей
#     [54], [39], [40], [55]. Порог обязан быть НЕ МЕНЬШЕ, иначе ряд распадётся.
#     (У самих полос фаз разброс меньше — 10738 EMU на слайде 5, — но group_rows
#     строит все ряды слайда, и порог обязан годиться для каждого.)
#   · минимальный зазор МЕЖДУ соседними рядами — 210841 EMU: слайд 5, одинокий
#     нижний шаг [38] под рядом подробностей. Порог обязан быть МЕНЬШЕ, иначе
#     два ряда слипнутся в один.
#
# Итого допустимо [20426, 210841) — отношение 10.3, а не порядки. Отдельно для
# ПОЛОСЫ ФАЗ запас больше: ближайший к полосе ряд шагов отстоит на 502322 EMU
# (слайд 11), и до этого значения band не сломается, сломаются лишь ряды ниже.
#
# 120000 СЕРЕДИНОЙ НЕ ЯВЛЯЕТСЯ ни в каком смысле (арифметическая 115633,
# геометрическая 65624) — это просто круглое число внутри отрезка: 5.9 запаса
# снизу и 1.76 сверху. Границы зажаты фикстурой самопроверки ТОЧНО этими двумя
# числами, так что подвинуть порог за пределы отрезка не выйдет молча.
PHASE_ROW_TOLERANCE = 120_000
# Меньше трёх фигур в ряду — это не полоса фаз, а случайное совпадение верхов.
PHASE_ROW_MIN_MEMBERS = 3


@dataclass
class PhaseBand:
    """Полоса фаз слайда: чем на этом слайде поделён процесс."""

    # 'containers' | 'top-row' — какая ветка сработала. В отчёт, потому что
    # ветка выбирается по слайду, и по карте потом не видно, какая именно.
    rule: str
    shapes: tuple[Shape, ...]        # геометрия фазы (контейнер или сама плашка)
    labels: tuple[str, ...]          # подпись фазы
    title_shapes: tuple[Shape, ...]  # подписи-текстбоксы; пусто у ветки 'top-row'


@dataclass
class TierSplit:
    """Фигуры слайда, разложенные по ярусам."""

    phases: tuple[Shape, ...]
    steps: tuple[Shape, ...]
    details: tuple[Shape, ...]
    # Ни один ярус не подошёл. СПИСОК ОБЯЗАН БЫТЬ НА ВИДУ У ВЫЗЫВАЮЩЕГО, и не
    # потому, что сюда попадает мусор, — сюда попадает и то, и другое:
    #   · на слайде 11 это две плашки легенды («Легенда», «Шаги демо»), и
    #     содержанием процесса они действительно не являются;
    #   · на слайде 9, если вызывающий НЕ отсеял плашки-артефакты, сюда уезжают
    #     четыре настоящие подробности — то есть ровно содержание процесса, а их
    #     место в details занимают пять артефактов.
    # Поэтому «непустой others» — это не «немного мусора», а вопрос к разбору.
    others: tuple[Shape, ...]
    step_keys: frozenset[str]
    detail_key: str | None


def tier_key(shape: Shape) -> str:
    """
    Сигнатура яруса: тип фигуры плюс заливка с модификаторами.

    ТИП ФИГУРЫ В СИГНАТУРЕ НЕ ДЛЯ КРАСОТЫ. На слайде 11 подробности нарисованы
    ТЕКСТБОКСАМИ без заливки, а внизу того же слайда лежат две автофигуры тоже
    без заливки — плашки легенды. По одной заливке эти восемь фигур неразличимы,
    и легенда уехала бы в подробности процесса. На слайдах 3, 5 и 7 подробности,
    наоборот, автофигуры, так что закрепить один тип нельзя — только различать.
    """
    return f"{shape.kind}:{shape.fill_key}"


def is_tier_candidate(shape: Shape) -> bool:
    """
    У фигуры есть ярус: она с текстом и у неё есть ЯВНАЯ заливка.

    Отсутствие заливки (fill_key is None) — не ярус «никакой», а «признака
    нет»: так выглядят номер слайда на слайдах 7 и 9 и служебные фигуры. Ярус
    определяется заливкой, поэтому фигура без неё ни в один ярус не попадает.
    """
    return shape.has_text and shape.kind in ("auto", "textbox") and shape.fill_key is not None


def group_rows(shapes: Sequence[Shape], tolerance: int) -> list[list[Shape]]:
    """Фигуры, сгруппированные в ряды по верхней кромке; ряды сверху вниз."""
    rows: list[list[Shape]] = []
    for shape in sorted(shapes, key=lambda s: (s.box.top, s.box.left)):
        if rows and shape.box.top - rows[-1][0].box.top <= tolerance:
            rows[-1].append(shape)
        else:
            rows.append([shape])
    for row in rows:
        row.sort(key=lambda s: s.box.left)
    return rows


def phase_band(shapes: Sequence[Shape], report: SlideReport | None = None) -> PhaseBand | None:
    """
    Полоса фаз слайда. ДВЕ ВЕТКИ, и выбирает между ними сам слайд.

    · есть контейнеры (is_container) — фаза это КОНТЕЙНЕР, а подпись к нему
      лежит отдельным текстбоксом сверху (find_title_for_container). Так устроен
      слайд 9 презентации L2: четыре бесфонных рамки с подписями «Расчет
      потребности», «Обработка ошибок и предупреждений», «Анализ и корректировка
      результатов», «Сценарное планирование».
    · контейнеров нет — фаза это сама плашка с текстом, и полоса фаз это
      ВЕРХНИЙ РЯД таких плашек, где участников не меньше трёх. Так устроены
      слайды 3, 5, 7 и 11: на каждом ровно четыре фазы одним рядом.

    Порог «не меньше трёх» отделяет полосу от случайного совпадения верхов у
    пары фигур; на всех четырёх слайдах полоса набирает четырёх участников, а
    следующий ряд (шаги) — от шести.

    Контейнер без подписи останавливает импорт, а не пропускается: фаза без
    имени — это дыра в карте, и заметить её потом неоткуда.

    None означает «полосы фаз на слайде нет». Что с этим делать, решает профиль
    разбора: сообщение об ошибке зависит от того, какой слайд разбирается.
    """
    containers = sorted(
        [s for s in shapes if is_container(s)],
        key=lambda s: (round(s.box.top / 1_000_000), s.box.left),
    )
    if containers:
        # Список подписей УБЫВАЕТ по мере разбора: один текстбокс не может
        # подписывать две фазы. Раньше здесь стояло `title.consumed_by = …`, но
        # это чужое поле: phase_band по имени и докстроке только ИЩЕТ, а пометка
        # переживает выход из функции и меняет ответ find_title_for_container на
        # следующем проходе по тем же фигурам. Сегодня безвредно (рабочих
        # вызовов нет), в профиле три яруса выстрелило бы.
        available = [s for s in shapes if s.kind == "textbox" and s.has_text]
        band: list[Shape] = []
        labels: list[str] = []
        titles: list[Shape] = []
        for container in containers:
            title = find_title_for_container(container, available)
            if title is None:
                raise SystemExit(
                    f"контейнер-фаза [{container.sid}] без подписи — фазу собрать нельзя"
                )
            available.remove(title)
            band.append(container)
            labels.append(title.text)
            titles.append(title)
        found = PhaseBand("containers", tuple(band), tuple(labels), tuple(titles))
    else:
        found = None
        for row in group_rows([s for s in shapes if is_tier_candidate(s)], PHASE_ROW_TOLERANCE):
            if len(row) >= PHASE_ROW_MIN_MEMBERS:
                found = PhaseBand("top-row", tuple(row), tuple(s.text for s in row), ())
                break
    if report is not None and found is not None:
        report.phase_band_rule = found.rule
    return found


def dominant_key(shapes: Sequence[Shape]) -> str | None:
    """Самая многочисленная сигнатура яруса; при равенстве — меньшая по алфавиту."""
    counts = Counter(tier_key(s) for s in shapes)
    if not counts:
        return None
    return min(counts, key=lambda key: (-counts[key], key))


def split_tiers(shapes: Sequence[Shape], band: PhaseBand) -> TierSplit:
    """
    Раскладывает фигуры слайда по ярусам: фазы, шаги, подробности.

    ШАГИ ОПРЕДЕЛЯЮТСЯ ПО-РАЗНОМУ В ДВУХ ВЕТКАХ, и это не небрежность, а замер:

    · 'top-row' — шаг красится В ЦВЕТ СВОЕЙ ФАЗЫ. На слайде 3 полоса фаз даёт
      четыре сигнатуры (A6A6A6, AD27BA, 9000FF и tx2 с модификаторами), и ровно
      эти же четыре стоят у восьми шагов под ней. Значит шаг — это фигура с
      сигнатурой полосы, где бы она ни лежала: так низко лежащие [38] слайда 5,
      [38] слайда 7 и [55] слайда 11 остаются шагами.
    · 'containers' — фаза это бесфонная рамка, и цвет шага с ней не совпадает
      ни у кого (слайд 9: рамки noFill, шаги scheme:accent1). Здесь шаг — самая
      многочисленная сигнатура: двенадцать шагов против четырёх подробностей.

    ПОДРОБНОСТЬ — самая многочисленная сигнатура среди оставшихся. Проверено на
    четырёх слайдах: 7 + 5 + 4 + 6 = 22 коробки подробностей при 31 шаге,
    ошибок классификации нет.

    ПЛАШКИ-АРТЕФАКТЫ (входы и выходы процесса) ОТСЕИВАЕТ ВЫЗЫВАЮЩИЙ, до вызова.
    split_tiers про них не знает и знать не должен: на слайде 9 их пять штук
    одной заливкой (scheme:accent3), и оставленные в наборе они выигрывают у
    подробностей по численности. Распознаёт их is_artifact_box — отдельный
    признак, а не ярус.
    """
    known = {id(s) for s in band.shapes} | {id(s) for s in band.title_shapes}
    candidates = [s for s in shapes if is_tier_candidate(s) and id(s) not in known]
    if band.rule == "containers":
        step_key = dominant_key(candidates)
        step_keys = frozenset() if step_key is None else frozenset({step_key})
    else:
        step_keys = frozenset(tier_key(s) for s in band.shapes)
    steps = [s for s in candidates if tier_key(s) in step_keys]
    rest = [s for s in candidates if tier_key(s) not in step_keys]
    detail_key = dominant_key(rest)
    return TierSplit(
        phases=tuple(band.shapes),
        steps=tuple(steps),
        details=tuple(s for s in rest if tier_key(s) == detail_key),
        others=tuple(s for s in rest if tier_key(s) != detail_key),
        step_keys=step_keys,
        detail_key=detail_key,
    )


# --------------------------------------------------------------------------------------
# Реестр модулей трёхуровневой карты: навигационные слайды (process-map-9mn.14.2)
# --------------------------------------------------------------------------------------
#
# Колода «In.Plan L2 Обзор и E2E demo» поделена на модули слайдами-разделителями
# (MapSpec.nav_slides). Это ЕДИНСТВЕННОЕ место колоды, где у модуля записаны
# сразу код, русское название и место в ряду модулей. Слайды детализации для
# реестра не годятся: названия там свои и расходятся с навигацией («Процесс
# Планирования спроса», «Планирование производства и Графикование» против кнопки
# «Производственное планирование и графикование»), а кода у части из них нет.
#
# ЗАМЕР ПО КОЛОДЕ (навигационные слайды 2/4/6/8/10):
#   · заголовок — текстбокс, в котором после пропуска пустых абзацев остаются
#     два: русское название и английское с кодом в скобках — «Планирование
#     спроса» / «Demand Planning (DP)». Хвостовые пробелы есть и у заголовков
#     (слайды 2 и 10), и у кнопки DP на всех пяти слайдах — normalize_text их
#     срезает, иначе заголовок не нашёл бы своей кнопки. Переноса a:br (он же
#     \x0b) на навигационных слайдах нет — проверено по XML; хвостовой перенос
#     у названия MEIO стоит в заголовке слайда ДЕТАЛИЗАЦИИ 5, а не здесь;
#   · кнопки — пять автофигур с текстом ОДНИМ РЯДОМ (верх у всех 5.04in), слева
#     направо: 0.55in, 2.66, 4.80, 6.84, 8.99. Текст кнопки — русское название
#     модуля; КОДА НА КНОПКЕ НЕТ, поэтому кнопка связывается с модулем только
#     через русское название его заголовка;
#   · других фигур с текстом на этих слайдах нет.
#
# ЗАЛИВКА НЕ ЧИТАЕТСЯ ВОВСЕ. Кнопка «своего» модуля выделена, но цвет выделения
# у каждого модуля свой (DP — accent1, MEIO — accent2, SNP — accent3, PS —
# accent4, MRP — снова accent1), а у неактивных кнопок — 7F7F7F или bg1 с
# lumMod 50000. Ни кнопку, ни модуль по заливке не опознать.
#
# ПОРЯДОК КОЛОДЫ И ПОРЯДОК КНОПОК РАЗНЫЕ. Колода идёт DP, MEIO, SNP, MRP, PS
# (MRP на слайдах 8/9 раньше PS на 10/11), кнопки — DP, MEIO, SNP, PS, MRP.
# Номер модуля и порядок реестра берутся ПО КНОПКАМ — решение владельца
# process-map-9mn.31, п. 2. Отчёт печатает оба порядка рядом, чтобы
# расхождение было видно, а не угадывалось по номерам.

# Код модуля — латинские заглавные (и цифры) в скобках в конце абзаца:
# «Demand Planning (DP)», «Multi-Echelon Inventory Optimization (MEIO)». Из
# кода получается id модуля (ModuleRef.id), поэтому знаков вне [A-Z0-9] в нём
# быть не может: «(FP&A)» с титульного слайда кодом модуля не считается.
NAV_CODE_RE = re.compile(r"\(([A-Z][A-Z0-9]*)\)$")


@dataclass(frozen=True)
class ModuleRef:
    """
    Модуль трёхуровневой карты — строка реестра, прочитанного с навигационных
    слайдов (read_module_index).

    Номера слайдов 0-based, как в MapSpec.nav_slides: по ним индексируется
    список слайдов. В отчёт и сообщения они идут с единицы, как их видит
    человек в PowerPoint.

    id — ПОЛЕ, но не аргумент конструктора (init=False): его вычисляет
    __post_init__ из кода. Поле, а не @property, потому что реестр пойдёт в
    JSON карты (подзадача 14.6), и dataclasses.asdict/fields/repr обязаны его
    видеть — свойство они молча пропускают, и модуль ушёл бы в данные без id.
    Не аргумент, потому что заданный снаружи id было бы где разойтись с кодом:
    ModuleRef(id=…) — TypeError, а frozen не даёт переписать его потом.
    """

    code: str          # 'DP', 'MEIO', … — из скобок в последнем абзаце заголовка
    id: str = field(init=False)  # код строчными — см. docstring
    title: str         # русское название — ПЕРВЫЙ абзац заголовка (решение владельца 9mn.6)
    number: int        # место кнопки модуля в ряду навигации, с 1 (решение 9mn.31, п. 2)
    nav_slide: int     # навигационный слайд модуля, 0-based
    detail_slide: int  # слайд детализации — следующий за навигационным, 0-based

    def __post_init__(self) -> None:
        # frozen=True закрывает обычное присваивание и для __post_init__ —
        # object.__setattr__ его обходит; это штатный приём dataclasses для
        # вычисляемых полей замороженного класса.
        object.__setattr__(self, "id", self.code.lower())


def nav_title(shapes: Sequence[Shape], slide_no: int) -> tuple[str, str]:
    """
    (код, русское название) модуля по заголовку навигационного слайда.

    Заголовок — ЕДИНСТВЕННЫЙ текстбокс, последний абзац которого кончается
    кодом в скобках (NAV_CODE_RE). Ни одного — остановка: модуль без кода не
    получит id. Больше одного — тоже: какой из них заголовок, решать догадкой
    нельзя.

    Название — ПЕРВЫЙ абзац, а не последний: последний английский и несёт код,
    а кнопки навигации подписаны по-русски, и связать модуль с кнопкой можно
    только русским названием.
    """
    # Абзацы нормализуются и пустые выбрасываются ДО поиска кода — так же, как
    # в read_paragraphs. Для фигур из презентации это уже сделано; здесь — для
    # фигур, собранных не из неё: пустой хвостовой абзац иначе спрятал бы код.
    textboxes = [
        (s, [p for p in (normalize_text(raw) for raw in s.paragraphs) if p])
        for s in shapes
        if s.kind == "textbox"
    ]
    found = [
        (s, paragraphs)
        for s, paragraphs in textboxes
        if paragraphs and NAV_CODE_RE.search(paragraphs[-1])
    ]
    if not found:
        raise SystemExit(
            f"слайд {slide_no}: нет текстбокса, последний абзац которого кончается кодом "
            f"модуля в скобках, например «Demand Planning (DP)». Без кода у модуля нет id — "
            f"навигационный ли это слайд? (MapSpec.nav_slides)"
        )
    if len(found) > 1:
        listed = ", ".join(f"[{s.sid}] «{s.text[:60]}»" for s, _ in found)
        raise SystemExit(
            f"слайд {slide_no}: несколько текстбоксов с кодом модуля в последнем абзаце — "
            f"{listed}. Какой из них заголовок модуля, по слайду не понять."
        )
    title, paragraphs = found[0]
    if len(paragraphs) < 2:
        raise SystemExit(
            f"слайд {slide_no}: у заголовка модуля [{title.sid}] «{title.text}» один абзац — "
            f"код есть, а русского названия над ним нет. Название модуля берётся из первого "
            f"абзаца заголовка (решение владельца process-map-9mn.6)."
        )
    match = NAV_CODE_RE.search(paragraphs[-1])
    assert match is not None  # отобрано по этому же выражению выше
    return match.group(1), paragraphs[0]


def nav_buttons(shapes: Sequence[Shape], slide_no: int) -> tuple[str, ...]:
    """
    Тексты кнопок навигации слева направо.

    Кнопки — ВСЕ автофигуры с текстом на слайде, и лежать они обязаны одним
    рядом: у рядов нет общей горизонтали — остановка. Так лишняя автофигура с
    текстом (заголовок, сноска) не становится шестым модулем молча.

    «Один ряд» — это прямая, пересекающая все кнопки (самый низкий верх выше
    самой высокой нижней кромки), а не допуск по верхам: порога, который
    пришлось бы замерять и защищать, здесь нет.

    Порядок — по левой кромке, а не по Shape.sort_key: сортировка слайда идёт
    сперва по верху, и кнопка, поставленная на пару EMU выше соседей, уехала бы
    в начало ряда.
    """
    buttons = [s for s in shapes if s.kind == "auto" and s.has_text]
    if not buttons:
        raise SystemExit(
            f"слайд {slide_no}: кнопок навигации нет — ни одной автофигуры с текстом. "
            f"Навигационный ли это слайд? (MapSpec.nav_slides)"
        )
    if max(s.box.top for s in buttons) >= min(s.box.bottom for s in buttons):
        listed = ", ".join(f"[{s.sid}] «{s.text[:40]}»" for s in buttons)
        raise SystemExit(
            f"слайд {slide_no}: кнопки навигации не лежат одним рядом — {listed}. "
            f"Автофигуры с текстом на навигационном слайде обязаны быть кнопками, и "
            f"все в один ряд: иначе порядок модулей по слайду не прочитать."
        )
    ordered = sorted(buttons, key=lambda s: (s.box.left, s.sid))
    return tuple(normalize_text(s.text) for s in ordered)


def read_module_index(
    slides: Sequence[Sequence[Shape]], spec: MapSpec, report: SlideReport
) -> tuple[ModuleRef, ...]:
    """
    Реестр модулей карты с навигационных слайдов spec.nav_slides — в порядке
    КНОПОК, с номерами по кнопкам (решение владельца process-map-9mn.31, п. 2).

    `slides` — фигуры каждого слайда колоды по порядку, как их отдаёт
    read_slide (индекс — 0-based номер слайда). Фигуры, а не слайды
    python-pptx, чтобы самопроверка могла подать синтетику без презентации.

    ПОКА НЕ ВЫЗЫВАЕТСЯ НИКАКИМ ПОСТРОИТЕЛЕМ: build_three_tier_map — заглушка,
    подключит реестр подзадача process-map-9mn.14.6. До тех пор его держит
    самопроверка (пункт 14), а на настоящей колоде он проверен разовым зондом.

    ОСТАНОВКИ, а не догадки:
      · кнопки на навигационных слайдах разные (не тот набор или не тот
        порядок) — номер модуля зависел бы от того, с какого слайда его читать;
      · заголовки и кнопки не взаимно однозначны — у модуля нет кнопки (нет
        номера), у кнопки нет навигационного слайда (модуль потерян) или двум
        слайдам досталась одна кнопка;
      · код модуля повторяется — два модуля получили бы один id;
      · за навигационным слайдом нет слайда детализации, или им оказался другой
        навигационный.

    Строки для отчёта — порядок кнопок рядом с порядком колоды и сам реестр —
    кладутся в report.module_index; печатает их print_report.
    """
    nav = sorted(spec.nav_slides)
    if not nav:
        raise SystemExit(
            f"карта «{spec.key}»: MapSpec.nav_slides пуст — реестр модулей читать не с чего"
        )
    if len(set(nav)) != len(nav):
        raise SystemExit(f"карта «{spec.key}»: в MapSpec.nav_slides повторяются слайды: {nav}")
    for index in nav:
        if not 0 <= index < len(slides) - 1:
            raise SystemExit(
                f"карта «{spec.key}»: за навигационным слайдом {index + 1} нет слайда "
                f"детализации — в колоде {len(slides)} слайдов"
            )
        if index + 1 in nav:
            raise SystemExit(
                f"карта «{spec.key}»: слайд детализации {index + 2} модуля со слайда "
                f"{index + 1} сам объявлен навигационным (MapSpec.nav_slides)"
            )

    # Кнопки первого по колоде навигационного слайда — эталон, с которым
    # сверяются остальные. Какой слайд эталонный, неважно: расхождение с любым
    # из них — остановка.
    reference = nav_buttons(slides[nav[0]], nav[0] + 1)
    read: list[tuple[int, str, str]] = []  # (слайд, код, название) — порядок колоды
    for index in nav:
        buttons = nav_buttons(slides[index], index + 1)
        if buttons != reference:
            raise SystemExit(
                f"кнопки навигации на слайде {index + 1} не такие, как на слайде {nav[0] + 1}:\n"
                f"  слайд {nav[0] + 1}: {' | '.join(reference)}\n"
                f"  слайд {index + 1}: {' | '.join(buttons)}\n"
                f"Номер модуля — место его кнопки в ряду (решение владельца "
                f"process-map-9mn.31, п. 2), и при разных рядах он зависел бы от того, "
                f"с какого слайда читать. Выровняйте кнопки в презентации."
            )
        code, title = nav_title(slides[index], index + 1)
        read.append((index, code, title))

    by_code: dict[str, list[int]] = {}
    for index, code, _ in read:
        by_code.setdefault(code, []).append(index + 1)
    repeated = {code: numbers for code, numbers in by_code.items() if len(numbers) > 1}
    if repeated:
        listed = "; ".join(
            f"{code} — слайды {', '.join(map(str, numbers))}" for code, numbers in repeated.items()
        )
        raise SystemExit(
            f"код модуля повторяется: {listed}. Из кода получается id модуля, и два модуля "
            f"с одним кодом слились бы в один."
        )

    titles = Counter(title for _, _, title in read)
    buttons_count = Counter(reference)
    problems = [
        f"заголовок «{title}» (слайд {index + 1}) — кнопки с таким текстом нет"
        for index, _, title in read
        if title not in buttons_count
    ]
    problems += [
        f"кнопка «{button}» — навигационного слайда с таким заголовком нет"
        for button in reference
        if button not in titles
    ]
    problems += [f"заголовок «{title}» на {count} слайдах" for title, count in titles.items() if count > 1]
    problems += [
        f"кнопка «{button}» в ряду {count} раза" for button, count in buttons_count.items() if count > 1
    ]
    if problems:
        raise SystemExit(
            "заголовки навигационных слайдов и кнопки навигации не взаимно однозначны:\n"
            + "\n".join(f"  · {item}" for item in problems)
            + "\nНомер модуля — место его кнопки в ряду, а кнопка находится по русскому "
            "названию из заголовка: без пары один к одному модуль останется без номера или "
            "потеряется."
        )

    modules = tuple(
        sorted(
            (
                ModuleRef(
                    code=code,
                    title=title,
                    number=reference.index(title) + 1,
                    nav_slide=index,
                    detail_slide=index + 1,
                )
                for index, code, title in read
            ),
            key=lambda module: module.number,
        )
    )

    button_order = ", ".join(module.code for module in modules)
    deck_order = ", ".join(code for _, code, _ in read)
    report.module_index.append(f"порядок кнопок навигации: {button_order}")
    report.module_index.append(
        f"порядок колоды:           {deck_order}"
        + (" — совпадает с кнопками" if deck_order == button_order else " — РАСХОДИТСЯ с кнопками")
    )
    for module in modules:
        report.module_index.append(
            f"{module.number}. {module.code} (id {module.id}) «{module.title}» — навигация: "
            f"слайд {module.nav_slide + 1}, детализация: слайд {module.detail_slide + 1}"
        )
    return modules


# --------------------------------------------------------------------------------------
# Слайд 1 трёхуровневой карты: коробки модулей, передачи, полосы (process-map-9mn.14.3)
# --------------------------------------------------------------------------------------
#
# Слайд 1 колоды «In.Plan L2 Обзор и E2E demo» — это уровень 1 карты целиком:
# ряд шевронов-модулей, над ним плашки того, что модули передают друг другу, под
# ним списки действий и полоса FP&A во всю ширину. ЗАМЕР ПО КОЛОДЕ (дюймы,
# 1in = 914400 EMU):
#   · шевроны (prstGeom chevron) с текстом — одним рядом, верх 1.74in, слева
#     направо TPM [41], DP [33], MEIO [23], SNP [24], PS [34], MRP [35]. Коробка
#     MRP маленькая и сидит ниже соседей (верх 1.81in): разброс верхов в ряду
#     66751 EMU. Соседние шевроны заходят друг на друга на 0.09–0.13in — так
#     рисуется «ёлочка», и перекрытие соседей само по себе ничего не значит;
#   · TPM модулем карты не является: владелец его исключил, и в реестре с
#     навигационных слайдов его нет. Но колонкой он остаётся — над ним лежат
#     плашки (см. ModuleColumn);
#   · ещё два шеврона с текстом лежат НЕ в ряду: DRP/TLB [38] прямо под MRP
#     (верх в 520222 EMU от верха ряда) и FP&A [44] внизу во всю ширину;
#   · шесть текстбоксов с заливкой scheme:tx1 над рядом (верх 0.93–1.07in, низ
#     не ниже 1.60in) — плашки-передачи;
#   · пять линий со стрелкой на конце (tailEnd), все горизонтальны
#     (y 1.22–1.24in) и соединяют плашки между собой, а не модули; привязок
#     stCxn/endCxn нет ни у одной;
#   · пять текстбоксов без заливки под рядом (верх 3.07in) — списки действий
#     под TPM, DP, MEIO, SNP и PS; у MRP списка нет;
#   · две автофигуры circularArrow [45]/[46] без текста между TPM и DP — значок
#     цикла. В разборе не участвуют: текста у них нет, и линиями они не являются.
#
# Здесь только ЧТЕНИЕ слайда: колонки, передачи, полосы и строки отчёта. Узлы и
# рёбра документа из них собирает построитель (подзадача process-map-9mn.14.6),
# поэтому результат — простые dataclass'ы, а не куски JSON.

# Для строк отчёта: геометрию слайда человек сверяет в PowerPoint, а тот
# показывает дюймы, а не EMU.
EMU_PER_INCH = 914_400

# Правила опознания коробки модуля — по убыванию строгости (match_module_box).
MODULE_MATCH_RULES = ("exact", "prefix", "code")

# Полоса уровня 1 перекрывает по x не меньше стольких колонок ряда модулей
# (lanes_from_slide1).
LANE_MIN_COLUMNS = 3

# Код полосы — в скобках в конце последнего абзаца: «Financial Planning and
# Analysis (FP&A)». Шире NAV_CODE_RE намеренно: у FP&A в коде амперсанд, и
# NAV_CODE_RE его не берёт — для модуля это правильно (код модуля становится id
# как есть), а id полосы собирается из букв кода отдельно.
LANE_CODE_RE = re.compile(r"\(([^()]+)\)$")

# Русский ли абзац — есть ли в нём хоть одна буква кириллицы (lanes_from_slide1:
# подпись полосы — «код · РУССКИЙ первый абзац», решение 9mn.31, п. 5).
CYRILLIC_RE = re.compile(r"[А-Яа-яЁё]")


@dataclass(frozen=True)
class ModuleColumn:
    """
    Колонка слайда 1 — шеврон из ряда модулей и его полоса по x.

    Колонкой становится КАЖДЫЙ шеврон ряда, а не только опознанный по реестру.
    TPM [41] модулем карты не является, но над ним лежат плашки: без его колонки
    «История продаж и план промо» [37] перекрывала бы одну колонку DP и
    пропала бы как «плашка над одним модулем», а не стала бы входом DP (решение
    владельца process-map-9mn.31, п. 8).
    """

    sid: int
    # Как колонку назвать в отчёте: код модуля, у колонки вне реестра — код в
    # скобках с её коробки (TPM) или первый абзац.
    name: str
    left: int
    right: int
    module: str | None   # id модуля реестра; None — колонка вне реестра (TPM)
    rule: str | None     # каким правилом опознана (MODULE_MATCH_RULES); None — вне реестра


@dataclass(frozen=True)
class ChevronRow:
    """Ряд модулей слайда 1: колонки слева направо и вертикальные границы ряда."""

    columns: tuple[ModuleColumn, ...]
    top: int      # самый высокий верх в ряду: плашки-передачи лежат НАД ним
    bottom: int   # самый низкий низ в ряду: списки действий и полосы — ПОД ним

    def module_ranges(self) -> dict[str, tuple[int, int]]:
        """id модуля → (left, right) его колонки в EMU; колонок вне реестра здесь нет."""
        return {c.module: (c.left, c.right) for c in self.columns if c.module is not None}


@dataclass(frozen=True)
class ModuleTransfer:
    """
    Передача со слайда 1: плашка над двумя соседними колонками, источник — левая.

    Одна из сторон бывает None — колонка вне реестра (TPM). Тогда узел
    создаётся только у модуля в охвате, а ребра между модулями нет: «История
    продаж и план промо» — вход DP, и только (решение владельца
    process-map-9mn.31, п. 8). Обе стороны None не бывает: такая плашка
    пропускается с отчётом (classify_transfer).
    """

    source: str | None   # id модуля-источника (левая колонка)
    target: str | None   # id модуля-приёмника (правая колонка)
    label: str
    # Коробка плашки на слайде 1 — её slidePosition (подзадача 14.6). КОПИЯ
    # коробки фигуры, а не она сама (classify_transfer): правка одной не должна
    # молча менять другую.
    #
    # ИЗ ХЕША ИСКЛЮЧЕНА (hash=False). Box — обычный изменяемый dataclass, а
    # такие не хешируются; с коробкой в хеше hash() передачи — и ModulesSlide,
    # который их держит, — падал бы TypeError'ом, хотя frozen-класс обязан
    # хешироваться: построитель вправе класть передачи в множество или ключом
    # словаря. В сравнении (==) коробка участвует по-прежнему, поэтому равные
    # передачи имеют равный хеш — хеш просто считается по остальным полям.
    box: Box = field(hash=False)
    sid: int


@dataclass(frozen=True)
class ModuleLane:
    """
    Полоса уровня 1 (FP&A): не модуль, в цепочку модулей не входит и не
    кликается (решение владельца process-map-9mn.31, п. 5).
    """

    id: str      # буквы кода строчными: «FP&A» → 'fpa'
    title: str   # «код · первый абзац»: «FP&A · Финансовое планирование и анализ»
    code: str
    # Копия коробки полосы и вне хеша — по той же причине, что у ModuleTransfer.
    box: Box = field(hash=False)
    sid: int


@dataclass(frozen=True)
class ModulesSlide:
    """
    Всё, что построитель берёт со слайда 1.

    СПИСКОВ ДЕЙСТВИЙ ЗДЕСЬ НЕТ НАМЕРЕННО: они только сверяются
    (reconcile_activity_lists) и в данные не идут. У результата нет ни одного
    поля, за которое их можно было бы взять данными по недосмотру.
    """

    row: ChevronRow
    transfers: tuple[ModuleTransfer, ...]
    lanes: tuple[ModuleLane, ...]


def inches(value: float) -> str:
    """Координата EMU в дюймах для отчёта — два знака, как в панели PowerPoint."""
    return f"{value / EMU_PER_INCH:.2f}"


def module_box_matches(rule: str, paragraphs: Sequence[str], module: ModuleRef) -> bool:
    """Подходит ли коробка с (нормализованными, непустыми) абзацами к модулю по правилу."""
    if rule == "exact":
        return paragraphs[0] == module.title
    if rule == "prefix":
        # Граница слова обязательна: без неё «Планирование спроса» узнало бы
        # себя в «Планирование спросами …» — в чужом названии, которое лишь
        # начинается с тех же букв.
        return re.match(re.escape(module.title) + r"(?!\w)", paragraphs[0]) is not None
    if rule == "code":
        for paragraph in paragraphs:
            if paragraph == module.code:
                return True
            code = NAV_CODE_RE.search(paragraph)
            if code is not None and code.group(1) == module.code:
                return True
        return False
    raise ValueError(f"неизвестное правило опознания коробки модуля «{rule}»")


def match_module_box(
    shape: Shape, modules: Sequence[ModuleRef], slide_no: int
) -> tuple[ModuleRef, str] | None:
    """
    Модуль реестра, которому принадлежит коробка слайда 1, и правило, по
    которому она опознана. None — коробка не модуль реестра (TPM, DRP/TLB, FP&A);
    что с ней делать, решает вызывающий (chevron_columns).

    ПО ТЕКСТУ, А НЕ ПО ЗАЛИВКЕ. У DP [33] явной заливки нет вовсе: цвет приходит
    из темы (p:style/a:fillRef idx=1, accent1), и read_fill отдаёт None. Правило,
    которому нужна заливка, потеряло бы DP.

    ТРИ ПРАВИЛА ПО УБЫВАНИЮ СТРОГОСТИ, первое сработавшее побеждает:
      · 'exact'  — первый абзац равен названию модуля с навигационного слайда
                   (так опознаются DP, MEIO и PS);
      · 'prefix' — первый абзац начинается с названия на границе слова: SNP [24]
                   подписан «Планирование сети поставок и производства», а
                   навигация называет его «Планирование сети поставок»;
      · 'code'   — абзац «(КОД)», абзац, кончающийся «(КОД)», или сам код: MRP
                   [35] подписан просто «MRP».
    Сработавшее правило идёт в отчёт: «SNP опознан по префиксу» — это сведение
    о презентации (слайд 1 и навигация называют модуль по-разному), а не деталь
    реализации.

    Несколько модулей по ОДНОМУ правилу — остановка: какой из них, по слайду не
    понять (так бывает, когда название одного модуля — начало названия другого).
    Более слабые правила после этого не пробуются: разрешать ими
    неоднозначность значило бы угадывать.
    """
    # Нормализация — как в nav_title: для фигур из презентации её уже сделал
    # read_paragraphs, здесь — для фигур, собранных не из неё.
    paragraphs = [p for p in (normalize_text(raw) for raw in shape.paragraphs) if p]
    if not paragraphs:
        return None
    for rule in MODULE_MATCH_RULES:
        found = [module for module in modules if module_box_matches(rule, paragraphs, module)]
        if len(found) > 1:
            listed = ", ".join(f"{module.code} «{module.title}»" for module in found)
            raise SystemExit(
                f"слайд {slide_no}: коробка [{shape.sid}] «{shape.text[:60]}» по правилу "
                f"'{rule}' подходит сразу к нескольким модулям — {listed}. Какой из них, по "
                f"слайду не понять."
            )
        if found:
            return found[0], rule
    return None


def column_name(shape: Shape, module: ModuleRef | None) -> str:
    """Имя колонки для отчёта: код модуля; вне реестра — код в скобках или первый абзац."""
    if module is not None:
        return module.code
    paragraphs = [p for p in (normalize_text(raw) for raw in shape.paragraphs) if p]
    for paragraph in reversed(paragraphs):
        code = NAV_CODE_RE.search(paragraph)
        if code is not None:
            return code.group(1)
    # Без текста колонок не бывает (chevron_columns), но имя для сообщения
    # обязано найтись и тогда — иначе сломанный фильтр упал бы IndexError'ом,
    # а не остановкой, называющей фигуру.
    return f"«{paragraphs[0][:40]}»" if paragraphs else f"[{shape.sid}] без текста"


def chevron_columns(
    shapes: Sequence[Shape], modules: Sequence[ModuleRef], report: SlideReport
) -> ChevronRow:
    """
    Ряд модулей слайда 1 и его колонки.

    Ряды строит group_rows по автофигурам С ТЕКСТОМ, с тем же допуском
    PHASE_ROW_TOLERANCE, что у полосы фаз, а рядом модулей считается тот, где
    больше всего коробок опознано по реестру. Не «верхний ряд» и не «все
    автофигуры»: DRP/TLB [38] — шеврон с текстом прямо под MRP, и стань он
    колонкой, плашка «Детальный план операций» [32] перекрыла бы три колонки
    (PS, MRP и DRP/TLB) вместо двух. Допуск на этом слайде: разброс верхов
    внутри ряда — 66751 EMU (MRP [35] ниже соседей), до ряда DRP/TLB — 520222
    EMU. Самопроверка зажимает PHASE_ROW_TOLERANCE и этими двумя числами, а не
    только замерами слайдов 3/5/7/11.

    Колонка — КАЖДАЯ коробка выбранного ряда, опознанная или нет (см.
    ModuleColumn). Автофигура без текста колонкой не бывает: значок цикла
    [45]/[46] лежит между TPM и DP в пределах высоты ряда. В колоде его верх на
    171429 EMU ниже верха ряда, и в ряд он не попал бы и без фильтра, — но
    держаться на этом совпадении фильтр не должен: стань значок колонкой,
    плашка [37] перекрыла бы три колонки.

    ОСТАНОВКИ, а не догадки:
      · ни одна коробка не опознана — ряда модулей на слайде нет;
      · два ряда с равным наибольшим числом опознанных — какой из них ряд
        модулей, по слайду не понять;
      · модуль реестра не нашёлся в ряду — у него не было бы колонки, и
        передачи к нему пропали бы; нашёлся дважды — колонок было бы две.
    """
    slide_no = report.slide_no
    boxes = [s for s in shapes if s.kind == "auto" and s.has_text]
    scored = [
        (row, [match_module_box(s, modules, slide_no) for s in row])
        for row in group_rows(boxes, PHASE_ROW_TOLERANCE)
    ]
    counts = [sum(1 for match in matches if match is not None) for _, matches in scored]
    # Верх ряда — самый высокий верх в нём, а не у первой фигуры: group_rows
    # отдаёт ряд отсортированным по левой кромке.
    tops = [min(s.box.top for s in row) for row, _ in scored]
    best = max(counts, default=0)
    if best == 0:
        raise SystemExit(
            f"слайд {slide_no}: ни одна автофигура с текстом не опознана как модуль реестра "
            f"({', '.join(m.code for m in modules)}) — ряда модулей на слайде нет. Тот ли это "
            f"слайд и тот ли реестр (MapSpec.nav_slides)?"
        )
    leaders = [index for index, count in enumerate(counts) if count == best]
    if len(leaders) > 1:
        listed = "; ".join(
            f"верх {inches(tops[index])}in — "
            + ", ".join(f"[{s.sid}]" for s in scored[index][0])
            for index in leaders
        )
        raise SystemExit(
            f"слайд {slide_no}: рядов с наибольшим числом опознанных модулей ({best}) "
            f"несколько: {listed}. Какой из них ряд модулей, по слайду не понять."
        )
    chosen = leaders[0]
    row, matches = scored[chosen]

    found: dict[str, list[int]] = {}
    for shape, match in zip(row, matches):
        if match is not None:
            found.setdefault(match[0].id, []).append(shape.sid)
    problems = [
        f"модуль {module.code} «{module.title}» — его коробки в ряду нет"
        for module in modules
        if module.id not in found
    ]
    problems += [
        f"модуль {module.code} — коробки {', '.join(f'[{sid}]' for sid in found[module.id])}"
        for module in modules
        if len(found.get(module.id, ())) > 1
    ]
    if problems:
        raise SystemExit(
            f"слайд {slide_no}: ряд модулей (верх {inches(tops[chosen])}in) не сходится с "
            f"реестром один к одному:\n"
            + "\n".join(f"  · {item}" for item in problems)
            + "\nКолонка модуля нужна передачам: без неё передачи к модулю пропали бы, а "
            "с двумя колонками источник и приёмник зависели бы от того, какую взять."
        )

    columns = tuple(
        ModuleColumn(
            sid=shape.sid,
            name=column_name(shape, None if match is None else match[0]),
            left=shape.box.left,
            right=shape.box.right,
            module=None if match is None else match[0].id,
            rule=None if match is None else match[1],
        )
        for shape, match in zip(row, matches)
    )

    for index, ((candidate, _), count) in enumerate(zip(scored, counts)):
        report.module_columns.append(
            f"слайд {slide_no}: ряд автофигур с текстом, верх {inches(tops[index])}in — "
            f"коробок {len(candidate)}, опознано модулей {count}"
            + (" — РЯД МОДУЛЕЙ" if index == chosen else "")
        )
    for column in columns:
        where = f"[{column.sid}] {column.name}, x {inches(column.left)}–{inches(column.right)}in"
        report.module_columns.append(
            f"  {where}: модуль {column.module} по правилу '{column.rule}'"
            if column.module is not None
            else f"  {where}: вне реестра модулей — колонка есть, узлов у неё нет"
        )
    # Порядок колонок — второй, независимый от навигации свидетель порядка
    # модулей (process-map-9mn.14): кнопки навигации и абсциссы шевронов
    # обязаны дать одно и то же. Номер модуля всё равно берётся по кнопкам
    # (решение 9mn.31, п. 2), поэтому расхождение печатается, а не
    # останавливает импорт.
    by_x = [column.name for column in columns if column.module is not None]
    by_number = [module.code for module in sorted(modules, key=lambda module: module.number)]
    report.module_columns.append(
        f"порядок колонок слева направо: {', '.join(column.name for column in columns)}; "
        f"модули в нём — {', '.join(by_x)}"
        + (
            " — совпадает с номерами модулей (кнопками навигации)"
            if by_x == by_number
            else f" — РАСХОДИТСЯ с номерами модулей ({', '.join(by_number)})"
        )
    )
    return ChevronRow(
        columns=columns,
        top=tops[chosen],
        bottom=max(shape.box.bottom for shape in row),
    )


def x_overlap(box: Box, left: int, right: int) -> int:
    """Перекрытие коробки с отрезком [left, right] по x; ноль и меньше — не перекрываются."""
    return min(box.right, right) - max(box.left, left)


def columns_under(box: Box, row: ChevronRow) -> list[int]:
    """
    Номера колонок ряда (слева направо), которые коробка перекрывает по x.

    ПОРОГА НЕТ — хватает любого положительного перекрытия, и это замер, а не
    небрежность: каждая плашка слайда 1 перекрывает свои колонки не меньше чем
    на 437320 EMU ([36] над PS), а до ближайшей чужой колонки ей не меньше
    1026606 EMU ([42] до DP). Касание кромкой (перекрытие ровно 0) перекрытием
    не считается.
    """
    return [
        index
        for index, column in enumerate(row.columns)
        if x_overlap(box, column.left, column.right) > 0
    ]


def check_transfer_arrows(shapes: Sequence[Shape], report: SlideReport) -> None:
    """
    Сторож прочтения «левая колонка — источник»: КАЖДАЯ линия слайда со
    стрелкой обязана вести слева направо, иначе остановка.

    Линии слайда 1 концами передач НЕ служат: они соединяют плашки между собой,
    а не модули, и привязок stCxn/endCxn у них нет ни одной. Источник и
    приёмник передачи задаёт положение плашки над колонками (classify_transfer),
    а линии лишь подтверждают, что поток нарисован слева направо. Поэтому здесь
    сторож, а не разбор: развёрнутая стрелка значит, что прочтение по положению
    разошлось с рисунком, и собирать передачи задом наперёд молча нельзя.

    «Слева направо» — ровно то, что сказано в задаче (process-map-9mn.14.3):
    стрелка указывает в сторону +x, то есть смещение от начала к концу по x
    строго положительно. Наклон НЕ ограничен: диагональ вниз-вправо тоже ведёт
    слева направо, и останавливать из-за неё весь импорт значило бы добавить
    к задаче правило, которого в ней нет. Вертикальная линия (смещение по x
    ноль) и линия справа налево — остановка: в сторону +x они не указывают.
    На колоде все пять линий горизонтальны, так что граница здесь — не замер,
    а формулировка задачи.

    Стрелки на обоих концах — тоже остановка, и это не добавка к задаче, а она
    же: у такой линии одна из двух стрелок указывает в сторону −x, и
    направления, которое подтверждало бы прочтение, у неё нет. Начало и конец —
    line_endpoints, с отражениями и поворотом, как везде в импортёре.
    """
    arrows = [s for s in shapes if s.kind == "line" and (s.head_arrow or s.tail_arrow)]
    wrong: list[str] = []
    for line in arrows:
        start, end = line_endpoints(line)
        where = (
            f"[{line.sid}] из ({inches(start[0])}, {inches(start[1])})in "
            f"в ({inches(end[0])}, {inches(end[1])})in"
        )
        if line.head_arrow and line.tail_arrow:
            wrong.append(f"{where} — стрелки на обоих концах")
        elif end[0] - start[0] <= 0:
            wrong.append(f"{where} — ведёт не слева направо")
    if wrong:
        raise SystemExit(
            f"слайд {report.slide_no}: линии со стрелкой обязаны вести слева направо — "
            f"передача читается как «левая колонка — источник, правая — приёмник», и "
            f"стрелки это прочтение подтверждают:\n"
            + "\n".join(f"  · {item}" for item in wrong)
            + "\nРисунок разошёлся с прочтением по положению плашек; собирать передачи "
            "задом наперёд нельзя. Импорт остановлен."
        )
    if not arrows:
        report.module_transfers.append(
            f"слайд {report.slide_no}: линий со стрелкой нет — направление передач рисунком "
            f"не подтверждено, передачи прочитаны только по положению плашек"
        )
        return
    bound = sum(1 for s in arrows if s.start_sid is not None or s.end_sid is not None)
    report.module_transfers.append(
        f"слайд {report.slide_no}: линий со стрелкой {len(arrows)}, все ведут слева направо "
        f"(с привязками stCxn/endCxn — {bound}). Концами передач линии не служат: "
        f"источник и приёмник задаёт положение плашки над колонками, линии только "
        f"подтверждают направление"
    )


def classify_transfer(shape: Shape, row: ChevronRow, report: SlideReport) -> ModuleTransfer | None:
    """
    Плашка над рядом модулей → передача между двумя СОСЕДНИМИ колонками:
    источник — левая колонка, приёмник — правая.

    ПОЧЕМУ «ЛЕВАЯ — ИСТОЧНИК». Так нарисовано: каждая плашка-передача сидит на
    стыке двух шевронов, а все стрелки между плашками ведут слева направо. Это
    прочтение держит сторож check_transfer_arrows: развернись хоть одна стрелка —
    импорт остановится, а не прочитает передачу задом наперёд.

    ИСХОДЫ:
      · две соседние колонки, обе в реестре — передача модуль → модуль;
      · две соседние, одна вне реестра (TPM) — передача с None на месте внешней
        стороны: узел только у модуля в охвате, ребра модулей нет ([37]
        «История продаж и план промо» → вход DP, решение 9mn.31, п. 8);
      · обе вне реестра, одна колонка или ни одной — плашка не импортируется,
        строка отчёта: [42] «История промо» лежит над одним TPM (решение 9mn.31,
        п. 8: не импортируется);
      · три колонки и больше или две несоседние — остановка: передача между
        кем и кем, по слайду не понять. Несоседние — это когда между двумя
        задетыми колонками стоит третья, которую плашка не задела (узкая
        коробка ряда); на колоде такого нет, но молча выбрать «крайние» нельзя.
    """
    slide_no = report.slide_no
    label = shape.text
    where = f"слайд {slide_no}: [{shape.sid}] «{label}»"
    hit = columns_under(shape.box, row)
    names = ", ".join(row.columns[index].name for index in hit)
    if len(hit) > 2:
        raise SystemExit(
            f"{where}: плашка над рядом модулей перекрывает колонок: {len(hit)} ({names}). "
            f"Передача идёт между ДВУМЯ соседними модулями — между кем и кем эта, по слайду "
            f"не понять."
        )
    if len(hit) == 2 and hit[1] - hit[0] != 1:
        skipped = ", ".join(row.columns[index].name for index in range(hit[0] + 1, hit[1]))
        raise SystemExit(
            f"{where}: плашка перекрывает несоседние колонки {names} — между ними {skipped}, "
            f"которую она не задевает. Передача идёт между соседними модулями; какую пару "
            f"имел в виду рисунок, по слайду не понять."
        )
    if len(hit) < 2:
        over = f"над одной колонкой {names}" if hit else "ни над одной колонкой"
        report.module_transfers.append(
            f"{where} — {over}: передачи между двумя модулями нет, не импортируется"
        )
        return None
    left, right = row.columns[hit[0]], row.columns[hit[1]]
    if left.module is None and right.module is None:
        report.module_transfers.append(
            f"{where} — над {left.name} и {right.name}, обе колонки вне реестра модулей: "
            f"не импортируется"
        )
        return None
    if left.module is not None and right.module is not None:
        effect = "ребро модулей и два узла-передачи"
    elif left.module is None:
        effect = f"{left.name} вне реестра: только вход {right.name}, ребра модулей нет"
    else:
        effect = f"{right.name} вне реестра: только выход {left.name}, ребра модулей нет"
    report.module_transfers.append(f"{where}: {left.name} → {right.name} — {effect}")
    # replace() без полей — копия коробки: передача не делит Box с фигурой.
    return ModuleTransfer(
        source=left.module,
        target=right.module,
        label=label,
        box=replace(shape.box),
        sid=shape.sid,
    )


def lanes_from_slide1(
    shapes: Sequence[Shape], row: ChevronRow, report: SlideReport
) -> tuple[ModuleLane, ...]:
    """
    Полосы уровня 1: автофигура с текстом ПОД рядом модулей, перекрывающая по x
    не меньше LANE_MIN_COLUMNS колонок. На колоде такая одна — FP&A [44]
    (srgb 00B050, 1.14–12.65in по x, задевает все шесть колонок).

    Порог «три колонки» отделяет полосу от коробки под одним модулем и от
    плашки на стыке двух. Текстбоксы полосами не бывают: список действий SNP
    [28] под рядом тоже задевает три колонки (MEIO, SNP, PS), но это список, а
    не полоса.

    id — буквы кода строчными («FP&A» → 'fpa'): амперсанд в id не годится, а
    выбросить только его, оставив прочие знаки, значило бы выдумывать правило
    по одному примеру. title — «код · первый абзац» (решение владельца
    process-map-9mn.31, п. 5): «FP&A · Финансовое планирование и анализ».

    ОСТАНОВКИ:
      · в конце последнего абзаца нет кода в скобках — полосу не назвать;
      · абзац один (код есть, а названия над ним нет) — так же, как у заголовка
        модуля в nav_title;
      · в первом абзаце нет ни одной кириллической буквы — он не русский.
        Подпись полосы — «код · РУССКИЙ первый абзац» (решение 9mn.31, п. 5), и
        английское название, поставленное первым, молча стало бы подписью
        («FP&A · Financial Planning»). «Русский» здесь — «есть хоть одна буква
        кириллицы», а не «нет латиницы»: в русских названиях латиница бывает
        (коды систем, аббревиатуры), и запрещать её значило бы выдумывать
        правило;
      · в коде нет латинских букв — не из чего собрать id;
      · id повторяется или совпадает с id модуля — два узла уровня 1 с одним id.
    """
    slide_no = report.slide_no
    modules = row.module_ranges()
    lanes: list[ModuleLane] = []
    below = [s for s in shapes if s.kind == "auto" and s.has_text and s.box.top >= row.bottom]
    for shape in sorted(below, key=lambda s: (s.box.top, s.box.left, s.sid)):
        hit = columns_under(shape.box, row)
        if len(hit) < LANE_MIN_COLUMNS:
            continue
        where = f"слайд {slide_no}: полоса [{shape.sid}] «{shape.text[:60]}»"
        paragraphs = [p for p in (normalize_text(raw) for raw in shape.paragraphs) if p]
        code = LANE_CODE_RE.search(paragraphs[-1]) if paragraphs else None
        if code is None:
            problem = "в конце последнего абзаца нет кода в скобках"
        elif len(paragraphs) < 2:
            problem = "абзац один — код есть, а названия над ним нет"
        elif not CYRILLIC_RE.search(paragraphs[0]):
            problem = f"первый абзац «{paragraphs[0][:40]}» не русский — кириллицы в нём нет"
        else:
            problem = None
        if problem is not None:
            raise SystemExit(
                f"{where}: {problem}. Нужны русское название первым абзацем и код в скобках "
                f"в конце последнего, например «Financial Planning and Analysis (FP&A)». "
                f"Подпись полосы — «код · русское название» (решение владельца "
                f"process-map-9mn.31, п. 5)."
            )
        assert code is not None  # problem is None только при найденном коде
        lane_id = re.sub(r"[^A-Za-z]", "", code.group(1)).lower()
        if not lane_id:
            raise SystemExit(
                f"{where}: в коде «{code.group(1)}» нет латинских букв — не из чего собрать id"
            )
        taken = {lane.id for lane in lanes} | set(modules)
        if lane_id in taken:
            raise SystemExit(
                f"{where}: id «{lane_id}» уже занят "
                + ("модулем" if lane_id in modules else "другой полосой")
                + " — на уровне 1 было бы два узла с одним id"
            )
        lane = ModuleLane(
            id=lane_id,
            title=f"{code.group(1)} · {paragraphs[0]}",
            code=code.group(1),
            box=replace(shape.box),
            sid=shape.sid,
        )
        lanes.append(lane)
        report.module_lanes.append(
            f"слайд {slide_no}: [{shape.sid}] → полоса {lane.id} «{lane.title}», "
            f"x {inches(shape.box.left)}–{inches(shape.box.right)}in, задевает колонки: "
            + ", ".join(row.columns[index].name for index in hit)
        )
    return tuple(lanes)


def activity_lists(
    shapes: Sequence[Shape], row: ChevronRow
) -> list[tuple[Shape, ModuleColumn | None]]:
    """
    Списки действий слайда 1 — текстбоксы с текстом без заливки под рядом
    модулей — и колонка, под которой лежит каждый.

    Колонка — с НАИБОЛЬШИМ перекрытием по x, а не любая задетая: списки шире
    шевронов и задевают соседей (SNP [28] — MEIO и PS на 0.30 и 0.09in при
    2.42in под своим SNP). None — список не лежит ни под одной колонкой.
    """
    found: list[tuple[Shape, ModuleColumn | None]] = []
    for shape in shapes:
        if not (
            shape.kind == "textbox"
            and shape.has_text
            and shape.fill in (None, "noFill")
            and shape.box.top >= row.bottom
        ):
            continue
        overlap, column = max(
            ((x_overlap(shape.box, c.left, c.right), c) for c in row.columns),
            key=lambda pair: pair[0],
        )
        found.append((shape, column if overlap > 0 else None))
    return sorted(found, key=lambda pair: (pair[0].box.left, pair[0].sid))


def activity_key(text: str) -> str:
    """Ключ сверки строк: без регистра, ё = е («Расчёт» и «Расчет» в колоде вперемешку)."""
    return normalize_text(text).casefold().replace("ё", "е")


def reconcile_activity_lists(
    shapes: Sequence[Shape],
    row: ChevronRow,
    steps: Mapping[str, Sequence[str]],
    report: SlideReport,
) -> None:
    """
    Сверка списков действий слайда 1 с подписями шагов слайдов детализации —
    ТОЛЬКО В ОТЧЁТ. В данные не идёт ничего, и потому функция ничего не
    возвращает.

    Списки — третье описание того же содержания, и со слайдами детализации они
    расходятся. Разовый зонд по колоде (шаги — split_tiers слайдов 3/5/7/11):
    у MEIO нашлось 5 строк из 6, у SNP — 2 из 7, у DP — 1 из 7, у PS — ни
    одной из 6. Взять списки данными значило бы молча выбрать одно из двух
    расходящихся описаний. Строка, которой нет среди шагов своего модуля,
    печатается — и только (process-map-9mn.14).

    `steps` — id модуля → подписи шагов его слайда детализации. Их даёт разбор
    слайдов детализации (подзадача 14.4), здесь они параметр. Модуль, которого
    в `steps` нет, не сверяется, и это тоже строка отчёта, а не молчание.

    Сравнение — activity_key: регистр и ё/е различиями не считаются, иначе
    отчёт засорили бы ложные расхождения.
    """
    slide_no = report.slide_no
    listed: set[str] = set()
    for shape, column in activity_lists(shapes, row):
        items = [p for p in (normalize_text(raw) for raw in shape.paragraphs) if p]
        if column is None:
            report.activity_check.append(
                f"слайд {slide_no}: список [{shape.sid}] «{items[0][:40]}» не лежит ни под одной "
                f"колонкой — не сверяется"
            )
            continue
        head = f"слайд {slide_no}: список [{shape.sid}] под колонкой {column.name}"
        if column.module is None:
            report.activity_check.append(
                f"{head} — колонка вне реестра модулей, не сверяется (строк: {len(items)})"
            )
            continue
        listed.add(column.module)
        labels = steps.get(column.module)
        if labels is None:
            report.activity_check.append(
                f"{head} — шаги слайда детализации модуля не переданы, не сверяется"
            )
            continue
        known = {activity_key(label) for label in labels}
        found = sum(1 for item in items if activity_key(item) in known)
        report.activity_check.append(
            f"{head}: среди шагов слайда детализации нашлось строк {found} из {len(items)}"
        )
        for item in items:
            report.activity_check.append(
                f"  = {item}" if activity_key(item) in known else f"  ≠ {item} — среди шагов нет"
            )
        mentioned = {activity_key(item) for item in items}
        unlisted = sum(1 for label in labels if activity_key(label) not in mentioned)
        report.activity_check.append(
            f"  шагов слайда детализации, которых в списке нет: {unlisted}"
        )
    for column in row.columns:
        if column.module is not None and column.module not in listed:
            report.activity_check.append(
                f"слайд {slide_no}: {column.name} — списка действий под колонкой нет, "
                f"сверять нечего"
            )


def read_modules_slide(
    shapes: Sequence[Shape], modules: Sequence[ModuleRef], report: SlideReport
) -> ModulesSlide:
    """
    Слайд 1 целиком: ряд модулей, сторож стрелок, передачи, полосы — и строка
    отчёта о каждой фигуре с текстом, которая ни во что из этого не попала.

    ПОКА НЕ ВЫЗЫВАЕТСЯ НИКАКИМ ПОСТРОИТЕЛЕМ, как и read_module_index: подключит
    подзадача process-map-9mn.14.6. До тех пор её держит самопроверка (пункт
    15), а на настоящей колоде она проверена разовым зондом.

    Порядок шагов не произволен: колонки нужны всем остальным, а сторож стрелок
    идёт ДО передач — прочтение «левая — источник» проверяется раньше, чем по
    нему что-то собрано.

    ПЛАШКА-ПЕРЕДАЧА — текстбокс с текстом и ЯВНОЙ заливкой, целиком выше ряда
    (низ не ниже верха ряда). Заливка — признак плашки: текстбокс без неё над
    рядом был бы подписью, а не артефактом. Цвет не сравнивается (на колоде у
    всех шести scheme:tx1): перекрась презентация плашки — передачи не должны
    пропасть молча. Плашки обходятся слева направо, чтобы отчёт шёл по цепочке.

    Неопознанное (на колоде — DRP/TLB [38]) идёт в report.text_skipped: блок
    «пропущенные фигуры с текстом» есть у каждого слайда в отчёте. Плейсхолдеры
    (заголовок слайда, номер страницы) — служебный текст и пропуском не
    считаются, как и на обзоре SNP (build_overview). Списки действий тоже не
    пропуск: их сверяет reconcile_activity_lists, отдельно — ей нужны шаги
    слайдов детализации.
    """
    row = chevron_columns(shapes, modules, report)
    check_transfer_arrows(shapes, report)
    plates = sorted(
        (
            s
            for s in shapes
            if s.kind == "textbox"
            and s.has_text
            and s.fill not in (None, "noFill")
            and s.box.bottom <= row.top
        ),
        key=lambda s: (s.box.left, s.sid),
    )
    transfers = tuple(
        transfer
        for transfer in (classify_transfer(plate, row, report) for plate in plates)
        if transfer is not None
    )
    lanes = lanes_from_slide1(shapes, row, report)

    # Учёт — по sid: shape_id уникален в пределах слайда (cNvPr/@id), а колонки
    # и полосы хранят именно его, а не сами фигуры.
    accounted = (
        {column.sid for column in row.columns}
        | {plate.sid for plate in plates}
        | {lane.sid for lane in lanes}
        | {shape.sid for shape, _ in activity_lists(shapes, row)}
    )
    for shape in shapes:
        if shape.kind != "placeholder" and shape.has_text and shape.sid not in accounted:
            report.text_skipped.append(
                f"слайд {report.slide_no}: [{shape.sid}] «{shape.text[:80]}» — не колонка ряда "
                f"модулей, не передача, не полоса и не список действий"
            )
    return ModulesSlide(row=row, transfers=transfers, lanes=lanes)


def rotate_point(point: tuple[float, float], cx: float, cy: float, degrees: float) -> tuple[float, float]:
    """Поворот точки вокруг центра. Ось Y экранная (вниз), поэтому знак как в DrawingML."""
    if not degrees:
        return point
    angle = math.radians(degrees)
    cos_a, sin_a = math.cos(angle), math.sin(angle)
    dx, dy = point[0] - cx, point[1] - cy
    return (cx + dx * cos_a - dy * sin_a, cy + dx * sin_a + dy * cos_a)


def line_endpoints(shape: Shape) -> tuple[tuple[float, float], tuple[float, float]]:
    """
    Начало и конец линии из left/top/width/height + флагов отражения и ПОВОРОТА.
    Стрелка на конце (a:tailEnd) означает направление начало→конец; стрелка
    на начале (a:headEnd) — обратное.

    ПОВОРОТ (process-map-3wh.18). У повёрнутого коннектора left/top/width/height
    описывают НЕПОВЁРНУТУЮ рамку, а рисуется он повёрнутым вокруг её центра.
    Без доворота концы вычислялись по чужим координатам: у линии [112] слайда 8
    карты MRP геометрия давала начало на «Анализе предупреждений» с расстоянием 0
    — то есть выдуманное ребро, а не потерянную связь. Повёрнутых коннекторов
    хватает и в презентации SNP (11 штук на слайдах 2-5), просто там их
    промахи гасились привязками и вторым проходом.
    """
    x1 = shape.box.right if shape.flip_h else shape.box.left
    x2 = shape.box.left if shape.flip_h else shape.box.right
    y1 = shape.box.bottom if shape.flip_v else shape.box.top
    y2 = shape.box.top if shape.flip_v else shape.box.bottom
    start = (float(x1), float(y1))
    end = (float(x2), float(y2))
    if shape.rot:
        cx, cy = float(shape.box.cx), float(shape.box.cy)
        start = rotate_point(start, cx, cy, shape.rot)
        end = rotate_point(end, cx, cy, shape.rot)
    if shape.head_arrow and not shape.tail_arrow:
        return end, start
    return start, end


def rank_candidates(
    candidates: Sequence[tuple[Box, str]], point: tuple[float, float]
) -> list[tuple[float, str]]:
    best: dict[str, float] = {}
    for box, key in candidates:
        distance = box.distance_to_point(point[0], point[1])
        if key not in best or distance < best[key]:
            best[key] = distance
    # Узел и поглощённая им надпись дают один и тот же key, поэтому конкурентами
    # в проверке однозначности они быть не должны.
    ranked = sorted((distance, key) for key, distance in best.items())
    return ranked


def nearest_target(
    candidates: Sequence[tuple[Box, str]], point: tuple[float, float], snap: float
) -> str | None:
    ranked = rank_candidates(candidates, point)
    if ranked and ranked[0][0] <= snap:
        return ranked[0][1]
    return None


def arrow_edges(
    arrows: Sequence[Shape],
    endpoints: Sequence[tuple[Box, str]],
    snap: float,
) -> list[tuple[str, str]]:
    """
    Декоративные стрелки-иконки как рёбра: левая середина — источник, правая — цель.

    ЗАЧЕМ ОБЩАЯ ФУНКЦИЯ (process-map-3wh.8). Приём был у обзора, но нужен и
    профилю «одиночный слайд»: на слайде 8 презентации MRP связи «шаг → шаг»
    линиями НЕ НАРИСОВАНЫ вовсе — их рисуют восемь таких стрелок. Правило
    проекта «ребро есть, потому что на слайде есть стрелка» соблюдается
    буквально; восстанавливать порядок по абсциссе значило бы догадываться.

    flip_h разворачивает стрелку: с ним источником становится правый край.
    В обеих презентациях отражённых стрелок нет, но правило выражено явно, а не
    оставлено на удачу данных.
    """
    edges: list[tuple[str, str]] = []
    for arrow in arrows:
        left = (float(arrow.box.left), arrow.box.cy)
        right = (float(arrow.box.right), arrow.box.cy)
        start, end = (right, left) if arrow.flip_h else (left, right)
        source = nearest_target(endpoints, start, snap)
        target = nearest_target(endpoints, end, snap)
        if source is None or target is None or source == target:
            # Стрелка между группами внутри одного этапа — не обзорное ребро.
            continue
        edges.append((source, target))
    return edges


def resolve_second_pass(ranked: Sequence[tuple[float, str]], exclude: str) -> str | None:
    """
    Второй проход для линии, у которой разрешён ровно один конец: берём ближайший
    узел в пределах EDGE_SNAP_SECOND, но только если следующий кандидат заметно
    дальше — иначе конец считается неоднозначным и связь не выдумывается.
    """
    filtered = [item for item in ranked if item[1] != exclude]
    if not filtered:
        return None
    distance, key = filtered[0]
    if distance > EDGE_SNAP_SECOND:
        return None
    if len(filtered) > 1 and filtered[1][0] < distance * EDGE_SECOND_RATIO:
        return None
    return key


# --------------------------------------------------------------------------------------
# Обработка слайда детализации
# --------------------------------------------------------------------------------------


def apply_input_enrichment(
    enrichment: dict,
    slide_no: int,
    drafts: list[NodeDraft],
    expanded: set[str],
    ids: IdFactory,
    report: SlideReport,
) -> None:
    """
    Досыпает в колонку входов этапа строки со слайда обзора и проверяет, что
    переформулировки нашли свои узлы (STAGE_INPUT_ENRICHMENT, process-map-qjl).

    Расхождение с презентацией — не предупреждение, а остановка импорта, ровно
    как в apply_owner_decision_edges: если слайд поправят и строка перестанет
    находиться, решение владельца обязано упасть громко, а не рассосаться молча.
    """
    stage_number = enrichment["stage"]
    missed = [short for short, _ in enrichment["expand"] if short not in expanded]
    if missed:
        raise SystemExit(
            f"STAGE_INPUT_ENRICHMENT ({enrichment['task']}): среди входов этапа "
            f"{stage_number} нет строк {', '.join(missed)} — презентация изменилась. "
            f"Импорт остановлен, чтобы решение владельца не потерялось молча: "
            f"обновите список в scripts/import-pptx.py."
        )

    column = [d for d in drafts if d.node_type == "data" and d.direction == "in"]
    if not column:
        raise SystemExit(
            f"STAGE_INPUT_ENRICHMENT ({enrichment['task']}): у этапа {stage_number} нет "
            f"колонки входов — добавлять строки некуда"
        )

    known = {normalize_text(draft.label).casefold() for draft in column}
    # Новые строки встают сразу под колонкой: слайдовая геометрия узла нужна
    # раскладке (layout.ts сидируется slidePosition), а колонка входов — её
    # законное место на слайде детализации.
    anchor = max(column, key=lambda draft: draft.box.bottom)

    for offset, extra in enumerate(enrichment["add"]):
        if normalize_text(extra).casefold() in known:
            raise SystemExit(
                f"STAGE_INPUT_ENRICHMENT ({enrichment['task']}): «{extra}» уже есть среди "
                f"входов этапа {stage_number} — презентация изменилась и строку больше "
                f"добавлять не нужно. Обновите список в scripts/import-pptx.py."
            )
        drafts.append(
            NodeDraft(
                node_id=ids.make(extra, slide_no, enrichment["sid"], offset),
                node_type="data",
                label=extra,
                box=Box(
                    anchor.box.left,
                    anchor.box.bottom + offset * anchor.box.height,
                    anchor.box.width,
                    anchor.box.height,
                ),
                direction="in",
            )
        )
        report.data_nodes += 1
        report.owner_inputs.append(
            f"этап {stage_number}: «{extra}» — ДОБАВЛЕНО со слайда обзора "
            f"({enrichment['task']}), на слайде детализации строки нет"
        )


def build_stage(
    slide_no: int,
    stage_number: int,
    shapes: Sequence[Shape],
    overview_title: str | None,
    ids: IdFactory,
    report: SlideReport,
    seen_signatures: set[tuple],
    spec: MapSpec,
) -> dict:
    title_shape = next((s for s in shapes if s.kind == "placeholder" and s.has_text), None)
    title = normalize_text(title_shape.text) if title_shape else f"Этап {stage_number}"
    if title_shape:
        title_shape.consumed_by = "заголовок этапа"
    for s in shapes:
        if s.kind == "placeholder" and s.consumed_by is None:
            s.consumed_by = "номер слайда"

    textboxes = [s for s in shapes if s.kind == "textbox" and s.has_text]
    lines = [s for s in shapes if s.kind == "line"]

    # 0. Забытые при копировании слайда фигуры: полностью совпадают с фигурой
    #    предыдущего слайда (тот же shape_id, те же координаты, тот же текст).
    for tb in textboxes:
        signature = (tb.sid, tb.box.left, tb.box.top, tb.box.width, tb.box.height, tb.text)
        if signature in seen_signatures:
            tb.consumed_by = "дубликат фигуры предыдущего слайда"
            report.text_skipped.append(
                f"слайд {slide_no}: [{tb.sid}] «{tb.text[:70]}» — точная копия фигуры "
                f"предыдущего слайда (остаток вёрстки), пропущена"
            )
        else:
            seen_signatures.add(signature)

    # 1. Группы: контейнеры + заголовок над ними.
    containers: list[tuple[Shape, str]] = []
    groups: list[dict] = []
    group_ids: set[str] = set()
    for container in [s for s in shapes if is_container(s)]:
        title_tb = find_title_for_container(container, textboxes)
        if title_tb is None:
            report.questions.append(
                f"слайд {slide_no}: контейнер [{container.sid}] без заголовка — группа не создана"
            )
            continue
        title_tb.consumed_by = "заголовок группы"
        label = title_tb.text
        group_id = slugify(label)
        if group_id in group_ids:
            group_id = f"{group_id}-{container.sid}"
        group_ids.add(group_id)
        containers.append((container, group_id))
        groups.append({"id": group_id, "label": label})
    report.groups = len(groups)

    # 2. Узлы-фигуры: AUTO_SHAPE с текстом (кроме контейнеров и декоративных стрелок).
    node_shapes = [
        s
        for s in shapes
        if s.kind == "auto" and s.has_text and not is_container(s) and not is_decor_arrow(s)
    ]
    drafts: list[NodeDraft] = []
    # Фигура -> узел: по этой карте разрешаются привязки коннекторов stCxn/endCxn.
    node_of_sid: dict[int, str] = {}
    for shape in node_shapes:
        draft = NodeDraft(
            node_id=ids.make(shape.text, slide_no, shape.sid),
            node_type=node_type_for(shape),
            label=shape.text,
            box=shape.box,
            group=innermost_container(containers, shape.box),
        )
        drafts.append(draft)
        node_of_sid[shape.sid] = draft.node_id

    # 2.5. Промоушен текстбокса в узел: в презентации часть вершин графа нарисована
    #      не автофигурой, а надписью. Признак — однострочный текст, в bbox которого
    #      упираются минимум два конца линий (то есть он реально используется как
    #      вершина, а не как подпись).
    endpoint_points: list[tuple[float, float]] = []
    for line in lines:
        start, end = line_endpoints(line)
        endpoint_points.extend((start, end))
    for tb in sorted([t for t in textboxes if t.consumed_by is None], key=Shape.sort_key):
        if len(tb.paragraphs) != 1:
            continue
        hits = sum(
            1 for point in endpoint_points if tb.box.distance_to_point(*point) <= PROMOTE_SNAP
        )
        if hits < PROMOTE_MIN_ENDPOINTS:
            continue
        tb.consumed_by = "узел (промоушен из текстбокса)"
        promoted = NodeDraft(
            node_id=ids.make(tb.text, slide_no, tb.sid),
            node_type=node_type_for(tb),
            label=tb.text,
            box=tb.box,
            group=innermost_container(containers, tb.box),
        )
        drafts.append(promoted)
        node_of_sid[tb.sid] = promoted.node_id
        report.promoted.append(
            f"слайд {slide_no}: [{tb.sid}] «{tb.text[:60]}» — узел (концов линий: {hits})"
        )

    # Текстовые фигуры, поглощённые узлом (подпись-выход или описание), работают
    # как «продолжение» узла: стрелка, упирающаяся в такую надпись, упирается в узел.
    proxies: list[tuple[Box, str]] = []

    # 3. Подписи под узлами → outputs (или description для развёрнутого текста).
    for tb in textboxes:
        if tb.consumed_by is not None:
            continue
        # Текст, дословно повторяющий подпись другого узла этого же слайда, —
        # ссылка на узел, а не новый артефакт: привязка неоднозначна.
        if any(d.label == tb.text for d in drafts):
            report.questions.append(
                f"слайд {slide_no}: [{tb.sid}] «{tb.text[:60]}» дословно повторяет подпись узла "
                f"— как подпись-выход не привязан"
            )
            continue
        best: tuple[float, NodeDraft] | None = None
        for draft in drafts:
            # Тонкие полосы (слайд 5) подписываются сверху, а не снизу.
            if draft.node_type == "data" or draft.box.height < CAPTION_MIN_NODE_HEIGHT:
                continue
            gap = tb.box.top - draft.box.bottom
            if not (CAPTION_MIN_GAP <= gap <= CAPTION_MAX_GAP):
                continue
            overlap = min(tb.box.right, draft.box.right) - max(tb.box.left, draft.box.left)
            if overlap <= 0:
                continue
            covers_node = tb.box.left <= draft.box.left and tb.box.right >= draft.box.right
            coverage = overlap / draft.box.width if covers_node else overlap / tb.box.width
            if coverage < CAPTION_MIN_OVERLAP:
                continue
            score = (gap, abs(tb.box.left - draft.box.left))
            if best is None or score < (best[0], abs(tb.box.left - best[1].box.left)):
                best = (gap, draft)
        if best is None:
            continue
        draft = best[1]
        tb.consumed_by = f"подпись узла {draft.node_id}"
        proxies.append((tb.box, draft.node_id))
        if is_caption_long_form(tb.paragraphs):
            draft.description_parts.extend(tb.paragraphs)
        else:
            draft.outputs.extend(tb.paragraphs)

    # 4. Левая колонка входов → узлы типа data (SPEC §4.2: DataNode входов слева).
    #    Подписи-выходы к этому моменту уже разобраны шагом 3, поэтому здесь
    #    достаточно признака «текстбокс стоит в левом поле слайда».
    #    group у data-узлов не проставляется: входы стоят вне групп (SPEC §4.2).
    #    direction='in' — по происхождению, а не по координате: это и есть
    #    колонка входов слайда (см. NodeDraft.direction, задача process-map-24p).
    #    Часть формулировок берётся со слайда обзора, а не отсюда, — см.
    #    STAGE_INPUT_ENRICHMENT. Замена делается ДО ids.make: иначе id остался бы
    #    слагом старой строки и разошёлся бы с подписью узла.
    #    Решения владельца отбираются по карте (decisions_for): таблица общая на
    #    весь импортёр, а решение принято про одну конкретную презентацию.
    enrichment = next(
        (
            e
            for e in decisions_for(spec, "STAGE_INPUT_ENRICHMENT")
            if e["stage"] == stage_number
        ),
        None,
    )
    expand = dict(enrichment["expand"]) if enrichment is not None else {}
    expanded: set[str] = set()

    for tb in sorted([t for t in textboxes if t.consumed_by is None], key=Shape.sort_key):
        if tb.box.left > LEFT_MARGIN_LIMIT:
            continue
        tb.consumed_by = "колонка входов"
        unique: list[str] = []
        for para in tb.paragraphs:
            if para not in unique:
                unique.append(para)
        if len(unique) != len(tb.paragraphs):
            report.questions.append(
                f"слайд {slide_no}: в списке входов [{tb.sid}] "
                f"{len(tb.paragraphs) - len(unique)} повторяющихся строк — оставлены уникальные"
            )
        step = tb.box.height / max(len(unique), 1)
        for index, para in enumerate(unique):
            label = expand.get(para, para)
            if label != para:
                expanded.add(para)
                report.owner_inputs.append(
                    f"этап {stage_number}: «{para}» → «{label}» — формулировка взята "
                    f"со слайда обзора ({enrichment['task'] if enrichment else '?'})"
                )
            drafts.append(
                NodeDraft(
                    node_id=ids.make(label, slide_no, tb.sid, index),
                    node_type="data",
                    label=label,
                    box=Box(tb.box.left, int(tb.box.top + index * step), tb.box.width, int(step)),
                    direction="in",
                )
            )
            report.data_nodes += 1

    if enrichment is not None:
        apply_input_enrichment(enrichment, slide_no, drafts, expanded, ids, report)

    # 5. Оставшиеся подписи внутри контейнера → description ближайшего узла группы.
    #    Привязка нестрогая, поэтому каждая попадает в отчёт.
    for tb in sorted([t for t in textboxes if t.consumed_by is None], key=Shape.sort_key):
        group_id = innermost_container(containers, tb.box)
        if group_id is None:
            continue
        siblings = [d for d in drafts if d.group == group_id and d.node_type != "data"]
        if not siblings:
            continue

        def distance(draft: NodeDraft, anchor: Shape = tb) -> tuple[float, str]:
            return (
                math.hypot(draft.box.cx - anchor.box.cx, draft.box.cy - anchor.box.cy),
                draft.node_id,
            )

        # В презентации такие подписи стоят НАД своим узлом (ряды «повод — действие»
        # на слайде 5), поэтому сначала ищем ближайший узел ниже подписи.
        below = [d for d in siblings if d.box.cy > tb.box.cy]
        best_draft = min(below or siblings, key=distance)
        dist = distance(best_draft)[0]
        if len(siblings) > 1 and dist > LOOSE_DESC_MAX_DIST:
            continue
        tb.consumed_by = f"описание узла {best_draft.node_id}"
        proxies.append((tb.box, best_draft.node_id))
        best_draft.description_parts.extend(tb.paragraphs)
        report.loose_attachments.append(
            f"слайд {slide_no}: [{tb.sid}] «{tb.text[:70]}» → description узла «{best_draft.node_id}»"
        )

    # 6. Рёбра: сначала явные привязки коннектора, затем геометрия (два прохода).
    #
    #    ПОЧЕМУ ПРИВЯЗКИ ПЕРВЫМИ (process-map-3wh.16). Считалось, что в этой
    #    презентации привязок нет и связи приходится выводить геометрически. Это
    #    неверно: из 66 линий 47 имеют ОБЕ привязки и лишь 10 не имеют ни одной —
    #    импортёр их просто не читал. Привязка точнее геометрии: она указывает на
    #    фигуру, а не на точку, и не врёт у растянутых коннекторов.
    #
    #    Привязка к КОНТЕЙНЕРУ группы разрешается в ближайший шаг этой группы:
    #    ребро в модели соединяет узлы, а контейнер узлом не является. Веерную
    #    связь «в группу целиком» один коннектор выразить не может — для неё
    #    остаётся OWNER_DECISION_EDGES (проверено: линия [146] слайда 5 даёт одно
    #    ребро из четырёх, объявленных владельцем).
    by_id = {d.node_id: d for d in drafts}
    node_boxes = [(d.box, d.node_id) for d in drafts if d.node_type != "data"]
    node_boxes.extend(proxies)
    members_of = {
        container.sid: [
            (d.box, d.node_id)
            for d in drafts
            if d.group == group_id and d.node_type != "data"
        ]
        for container, group_id in containers
    }

    def by_binding(sid: int | None, point: tuple[float, float]) -> str | None:
        """Привязка коннектора -> узел; привязка к контейнеру -> ближайший шаг в нём."""
        if sid is None:
            return None
        if sid in node_of_sid:
            return node_of_sid[sid]
        return nearest_target(members_of.get(sid, []), point, EDGE_SNAP_DETAIL)

    edges: list[dict] = []
    seen_pairs: set[tuple[str, str]] = set()
    report.lines_total = len(lines)
    for line in lines:
        start, end = line_endpoints(line)
        source = by_binding(line.start_sid, start)
        target = by_binding(line.end_sid, end)
        bound = source is not None or target is not None
        ranked_start = rank_candidates(node_boxes, start)
        ranked_end = rank_candidates(node_boxes, end)
        if source is None and ranked_start and ranked_start[0][0] <= EDGE_SNAP_DETAIL:
            source = ranked_start[0][1]
        if target is None and ranked_end and ranked_end[0][0] <= EDGE_SNAP_DETAIL:
            target = ranked_end[0][1]
        if source is not None and target is None:
            target = resolve_second_pass(ranked_end, source)
        elif target is not None and source is None:
            source = resolve_second_pass(ranked_start, target)
        if source is None or target is None or source == target:
            reason = "петля" if source is not None and source == target else "конец не определён"
            report.lines_skipped.append(f"слайд {slide_no}: линия [{line.sid}] — {reason}")
            continue
        if (source, target) in seen_pairs:
            continue
        seen_pairs.add((source, target))
        if bound:
            report.cxn_edges.append(f"слайд {slide_no}: [{line.sid}] {source} → {target}")
        endpoint_types = {by_id[source].node_type, by_id[target].node_type}
        edges.append(
            {
                "id": f"e-{source}--{target}",
                "source": source,
                "target": target,
                "kind": "integration" if "integration" in endpoint_types else "process",
            }
        )
    report.edges = len(edges)

    # 7. Внешние системы этапа (ExternalIO): из текста интеграций и узлов публикации.
    inputs: list[dict] = []
    outputs: list[dict] = []
    for draft in drafts:
        if draft.node_type == "integration" and detect_system(draft.label) is None:
            report.questions.append(
                f"слайд {slide_no}: интеграция «{draft.label[:60]}» — система в тексте не названа"
            )
        for text in [draft.label] + draft.outputs:
            system = detect_system(text)
            direction = detect_direction(text)
            if system is None or direction is None:
                continue
            entry = {"system": system, "label": text, "stage": stage_number, "direction": direction}
            bucket = inputs if direction == "in" else outputs
            if add_external_io(bucket, entry) and draft.system is None:
                draft.system = system

    # 7b. Узел с проставленным кодом системы — интеграция, даже если заливка
    #     обычная (решение владельца, process-map-7v1).
    #
    #     ПОЧЕМУ ПРАВИЛО, А НЕ СПИСОК. Признак «серая заливка A6A6A6» есть ровно
    #     у четырёх фигур на всю презентацию, и все четыре — входящие интеграции
    #     слайдов 3-4. Исходящие интеграции слайда 5 нарисованы штатной заливкой
    #     шага, а слово «модуль» из их текста убрано («Передача ограниченного
    #     прогноза в DP»), хотя на слайде обзора тот же шаг записан «в модуль DP».
    #     То есть оба признака is_integration промахиваются по вине вёрстки.
    #
    #     Код системы при этом проставляется от подписи-выгрузки и служит честным
    #     признаком: узел назвал внешнюю систему и направление — значит он на
    #     границе с ней. На текущих данных правило даёт ровно те четыре узла,
    #     которые назвал владелец, и ни одного лишнего: код системы несут восемь
    #     узлов, четыре из них уже были интеграциями.
    for draft in drafts:
        if draft.system is not None and draft.node_type == "step":
            draft.node_type = "integration"
            report.promoted_integrations.append(
                f"слайд {slide_no}: «{draft.label[:60]}» — step → integration "
                f"(код системы {draft.system}, заливка обычная)"
            )

    # 8. Отчёт по потерянным текстовым фигурам.
    for tb in textboxes:
        if tb.consumed_by is None:
            report.text_skipped.append(f"слайд {slide_no}: [{tb.sid}] «{tb.text[:80]}»")

    report.nodes = len(drafts)

    short_title = re.split(r"\s/|/\s|\s\+\s", title)[0].strip()
    return {
        "id": slugify(f"stage-{stage_number}-{overview_title or short_title}"),
        "number": stage_number,
        "title": title,
        "shortTitle": short_title,
        "keyOutputs": [],
        "warningsCount": 0,
        "groups": groups,
        "nodes": [serialize_node(d) for d in sorted(drafts, key=lambda d: (d.box.top, d.box.left, d.node_id))],
        "edges": edges,
        "inputs": inputs,
        "outputs": outputs,
    }


def serialize_node(draft: NodeDraft) -> dict:
    node: dict = {"id": draft.node_id, "type": draft.node_type, "label": draft.label}
    if draft.description:
        node["description"] = draft.description
    if draft.group:
        node["group"] = draft.group
    if draft.direction:
        node["direction"] = draft.direction
    if draft.inputs:
        node["inputs"] = draft.inputs
    if draft.outputs:
        node["outputs"] = draft.outputs
    if draft.system:
        node["system"] = draft.system
    slide_position = {
        "x": round(draft.box.left / EMU_PER_PX),
        "y": round(draft.box.top / EMU_PER_PX),
    }
    # position — то, что покажет приложение; его перезапишет `npm run layout`.
    # slidePosition — та же геометрия слайда, но НАВСЕГДА: раскладка сидируется
    # ею, а не собственным прошлым результатом (SPEC §3, задача process-map-cxn).
    # Два разных словаря, а не один и тот же объект: иначе правка одного поля
    # молча меняла бы второе.
    node["position"] = dict(slide_position)
    node["slidePosition"] = slide_position
    return node


# --------------------------------------------------------------------------------------
# Обработка слайда обзора
# --------------------------------------------------------------------------------------


@dataclass
class OverviewData:
    titles: list[str]
    output_blocks: list[list[tuple[list[str], Box, int]]]
    group_labels: list[list[str]]
    systems: list[dict]
    edges: list[dict]
    report: SlideReport


def build_overview(shapes: Sequence[Shape], report: SlideReport) -> OverviewData:
    textboxes = [s for s in shapes if s.kind == "textbox" and s.has_text]
    for s in shapes:
        if s.kind == "placeholder":
            s.consumed_by = "служебный текст слайда"

    containers = [s for s in shapes if is_container(s)]
    # Порядок этапов: верхний ряд, затем нижний слева направо.
    containers.sort(key=lambda s: (round(s.box.top / 1_000_000), s.box.left))

    titles: list[str] = []
    output_blocks: list[list[tuple[list[str], Box, int]]] = []
    group_labels: list[list[str]] = []

    boxed = [s for s in shapes if s.kind == "auto" and s.has_text]
    group_boxes = [s for s in boxed if s.fill == "scheme:accent1"]
    system_boxes = [s for s in boxed if s.fill in ("scheme:accent2", "scheme:bg1")]

    for container in containers:
        title_tb = find_title_for_container(container, textboxes)
        if title_tb is not None:
            title_tb.consumed_by = "заголовок этапа обзора"
            titles.append(title_tb.text)
        else:
            titles.append("")
            report.questions.append(
                f"слайд 2: контейнер этапа [{container.sid}] без подписи-заголовка "
                f"— заголовок берётся со слайда детализации"
            )

        group_labels.append(
            [
                b.text
                for b in sorted(group_boxes, key=Shape.sort_key)
                if container.box.contains_point(b.box.cx, b.box.cy)
            ]
        )

        lo = container.box.top + KEY_OUTPUT_TOP_OFFSET
        hi = container.box.bottom + KEY_OUTPUT_BOTTOM_OFFSET
        blocks: list[tuple[list[str], Box, int]] = []
        for tb in sorted(
            [t for t in textboxes if t.consumed_by is None], key=lambda s: (s.box.left, s.box.top)
        ):
            if not (lo <= tb.box.top <= hi):
                continue
            if tb.box.right <= container.box.left or tb.box.left >= container.box.right:
                continue
            tb.consumed_by = "блок выходов этапа"
            blocks.append((list(tb.paragraphs), tb.box, tb.sid))
        output_blocks.append(blocks)

    for b in group_boxes:
        if b.consumed_by is None:
            b.consumed_by = "бокс группы обзора"

    systems: list[dict] = []
    for shape in sorted(system_boxes, key=Shape.sort_key):
        code = detect_system(shape.text)
        if code is None:
            report.questions.append(
                f"слайд 2: бокс [{shape.sid}] «{shape.text[:60]}» — система не распознана"
            )
            continue
        systems.append(
            {
                "code": code,
                "label": shape.text,
                "direction": detect_direction(shape.text),
                "box": shape.box,
                "sid": shape.sid,
            }
        )
        shape.consumed_by = "внешняя система обзора"

    endpoints: list[tuple[Box, str]] = []
    for index, container in enumerate(containers, start=1):
        endpoints.append((container.box, f"@stage{index}"))
    for system in systems:
        endpoints.append((system["box"], f"@sys:{system['code']}:{system['sid']}"))

    connectors = [s for s in shapes if s.kind == "line"]
    arrows = [s for s in shapes if is_decor_arrow(s)]
    report.lines_total = len(connectors) + len(arrows)

    raw_edges: list[tuple[str, str]] = []
    for line in connectors:
        start, end = line_endpoints(line)
        source = nearest_target(endpoints, start, EDGE_SNAP_OVERVIEW)
        target = nearest_target(endpoints, end, EDGE_SNAP_OVERVIEW)
        if source is None or target is None or source == target:
            report.lines_skipped.append(
                f"слайд 2: линия [{line.sid}] — концы не привязались к этапу/системе"
            )
            continue
        raw_edges.append((source, target))

    raw_edges.extend(arrow_edges(arrows, endpoints, EDGE_SNAP_OVERVIEW))

    for tb in textboxes:
        if tb.consumed_by is None:
            report.text_skipped.append(f"слайд 2: [{tb.sid}] «{tb.text[:80]}»")

    return OverviewData(
        titles=titles,
        output_blocks=output_blocks,
        group_labels=group_labels,
        systems=systems,
        edges=[{"source": s, "target": t} for s, t in raw_edges],
        report=report,
    )


def block_items_start(paragraphs: Sequence[str]) -> int:
    """
    С какого абзаца в блоке выходов начинаются сами пункты.

    Блок может открываться заголовком — на слайде 2 это «Опубликованные планы:».
    Признак один: первый абзац оканчивается двоеточием. Разметка его
    подтверждает (единственный во всей презентации абзац без буллита и с нулевым
    отступом на фоне буллитованных соседей), но опираться на неё нельзя —
    двоеточие надёжнее и не зависит от того, как редактор записал отступы.

    Функция одна на ОБА применения — выбор keyOutputs и создание узлов-выходов.
    Раньше правило жило только в первом, и заголовок уезжал в данные отдельной
    карточкой «Опубликованные планы:» — единственным узлом документа, чья
    подпись оканчивалась двоеточием (process-map-t9j).
    """
    return 1 if paragraphs and paragraphs[0].endswith(":") else 0


def choose_key_outputs(
    blocks: Sequence[tuple[list[str], Box, int]],
    inbound_labels: AbstractSet[str],
) -> list[str]:
    """
    Ключевые выходы этапа. Если среди блоков есть перечень с заголовком-двоеточием
    («Опубликованные планы:»), берём его пункты — это и есть выходы этапа.
    Иначе — первые MAX_KEY_OUTPUTS абзацев в порядке чтения.

    ЧТО ОТБРАСЫВАЕТСЯ (process-map-tze). Пункт, который на слайде детализации
    этого же этапа нарисован ВХОДОМ, ключевым выходом не считается: иначе
    карточка обзора называет выходом то, что на экране этапа стоит в левой
    колонке, и карта противоречит сама себе на двух соседних экранах.

    Так вышло из презентации, и это не её ошибка: блоки выходов слайда 2 стоят
    под боксами ГРУПП, а не под этапом (process-map-2of). «Прогноз продаж в
    требуемой гранулярности» — выход группы «Преобразование прогноза к
    требуемой гранулярности» и одновременно вход следующей группы. Для этапа
    целиком это вход, для группы внутри него — выход.

    Отбор идёт ДО среза по MAX_KEY_OUTPUTS: иначе отброшенный пункт занимал бы
    место, и на карточке оказалось бы меньше выходов, чем мест.
    """

    def keep(paragraphs: Iterable[str]) -> list[str]:
        return [p for p in paragraphs if p.casefold() not in inbound_labels]

    for paragraphs, _box, _sid in blocks:
        start = block_items_start(paragraphs)
        if start:
            return keep(paragraphs[start:])[:MAX_KEY_OUTPUTS]
    flat = [p for paragraphs, _box, _sid in blocks for p in paragraphs]
    return keep(flat)[:MAX_KEY_OUTPUTS]


# --------------------------------------------------------------------------------------
# Сборка документа
# --------------------------------------------------------------------------------------


def count_warnings(stage: dict) -> int:
    """
    Число предупреждений этапа — по содержанию слайда (перечень типов
    предупреждений), а не по числу узлов типа warning.
    """
    distinct: set[str] = set()
    for node in stage["nodes"]:
        candidates = [node["label"], *node.get("outputs", [])]
        candidates.extend((node.get("description") or "").split("\n"))
        for text in candidates:
            text = text.strip()
            if text and WARNING_ITEM_RE.match(text):
                distinct.add(text)
    node_warnings = sum(1 for node in stage["nodes"] if node["type"] == "warning")
    return max(len(distinct), node_warnings)


def is_artifact_box(shape: Shape) -> bool:
    """
    Плашка-артефакт: вход или выход процесса, нарисованный автофигурой.

    ЗАЧЕМ ОТДЕЛЬНЫЙ ПРЕДИКАТ. На слайдах детализации SNP колонка входов — это
    надписи (textbox), и разбор ищет их по признаку «текстбокс в левом поле».
    На слайде 8 презентации MRP те же входы и выход нарисованы АВТОФИГУРАМИ с
    заливкой scheme:accent2. Без этого предиката они стали бы обычными шагами:
    прогон существующего build_stage давал 17 узлов и НОЛЬ data-узлов.
    """
    return shape.kind == "auto" and shape.has_text and shape.fill == ARTIFACT_FILL


def build_single_slide_map(
    collisions: dict[str, int] | None,
    spec: MapSpec,
) -> tuple[dict, list[SlideReport], list[str], Counter[str]]:
    """
    Профиль «одиночный слайд»: вся карта собирается с ОДНОГО слайда.

    ЧЕМ ОТЛИЧАЕТСЯ ОТ build_process_map. Там два уровня слайдов: обзор со
    стадиями и четыре слайда детализации. Здесь уровня «обзор» нет вовсе, и
    четыре КОНТЕЙНЕРА слайда становятся четырьмя этапами карты (решение
    владельца). Группы внутри этапа не заводятся: группа СТАЛА этапом, и
    рисовать внутри него рамку с тем же заголовком значило бы дублировать.

    Общего с build_stage — почти вся геометрия: is_container, поиск заголовка,
    innermost_container, классификация узлов, разбор подписей, двухпроходное
    сопоставление концов линий. Своё — только «где брать этапы» и «где брать
    входы и выходы».
    """
    if not spec.pptx.exists():
        raise SystemExit(f"Не найдена презентация: {spec.pptx}")
    presentation = Presentation(str(spec.pptx))
    if int(presentation.slide_width) != SLIDE_WIDTH_EMU:
        raise SystemExit(
            f"Неожиданная ширина слайда {presentation.slide_width} EMU (ожидалось {SLIDE_WIDTH_EMU})"
        )
    slides = list(presentation.slides)
    if len(slides) != spec.slides:
        raise SystemExit(f"Ожидалось {spec.slides} слайдов, найдено {len(slides)}")
    if spec.slide_index is None:
        raise SystemExit(f"У карты «{spec.key}» профиль single-slide, но slide_index не задан")

    slide_no = spec.slide_index + 1
    report = SlideReport(slide_no=slide_no)
    shapes = read_slide(slides[spec.slide_index], report)
    questions: list[str] = []

    textboxes = [s for s in shapes if s.kind == "textbox" and s.has_text]
    lines = [s for s in shapes if s.kind == "line"]
    arrows = [s for s in shapes if is_decor_arrow(s)]
    for s in shapes:
        if s.kind == "placeholder":
            s.consumed_by = "заголовок слайда"

    # 1. Контейнеры -> этапы. Порядок «верхний ряд, затем нижний слева направо» —
    #    тот же, которым build_overview упорядочивает стадии обзора.
    containers = sorted(
        [s for s in shapes if is_container(s)],
        key=lambda s: (round(s.box.top / 1_000_000), s.box.left),
    )
    if len(containers) != spec.stage_count:
        raise SystemExit(
            f"слайд {slide_no}: ожидалось {spec.stage_count} контейнеров-этапов, "
            f"найдено {len(containers)}"
        )

    stage_containers: list[tuple[Shape, str]] = []
    stage_meta: list[dict] = []
    for index, container in enumerate(containers):
        title_tb = find_title_for_container(container, textboxes)
        if title_tb is None:
            # Не вопрос в отчёт, а остановка: в этом профиле контейнер ЭТО этап,
            # и безымянный этап собирать нельзя.
            raise SystemExit(
                f"слайд {slide_no}: контейнер [{container.sid}] без заголовка — "
                f"этап собрать нельзя"
            )
        title_tb.consumed_by = "заголовок этапа"
        title = title_tb.text
        short_title = re.split(r"\s/|/\s|\s\+\s", title)[0].strip()
        number = index + 1
        stage_id = slugify(f"stage-{number}-{short_title}")
        stage_containers.append((container, stage_id))
        stage_meta.append(
            {"id": stage_id, "number": number, "title": title, "shortTitle": short_title}
        )
    report.groups = len(stage_meta)

    # 2. Узлы-шаги. Плашки-артефакты исключены: они станут data-узлами шагом 3.
    ids = IdFactory(collisions)
    drafts: list[NodeDraft] = []
    stage_of_node: dict[str, str] = {}
    sid_of_node: dict[int, str] = {}
    node_shapes = [
        s
        for s in shapes
        if s.kind == "auto"
        and s.has_text
        and not is_container(s)
        and not is_decor_arrow(s)
        and not is_artifact_box(s)
    ]
    for shape in node_shapes:
        stage_id = innermost_container(stage_containers, shape.box)
        if stage_id is None:
            raise SystemExit(
                f"слайд {slide_no}: узел «{shape.text[:60]}» не попал ни в один контейнер-этап"
            )
        draft = NodeDraft(
            node_id=ids.make(shape.text, slide_no, shape.sid),
            node_type=node_type_for(shape),
            label=shape.text,
            box=shape.box,
        )
        drafts.append(draft)
        stage_of_node[draft.node_id] = stage_id
        sid_of_node[shape.sid] = draft.node_id
    report.nodes = len(drafts)

    # 3. Плашки-артефакты -> data-узлы.
    #    НАПРАВЛЕНИЕ ПО ПРОИСХОЖДЕНИЮ, а не по координате (process-map-24p):
    #    левое поле слайда — это колонка входов. Для плашки вне левого поля
    #    правило «значит выход» было бы геометрией, поэтому шагом 6 оно
    #    подкрепляется вторым независимым признаком: такая плашка обязана быть
    #    целью хотя бы одной связи.
    artifacts: list[tuple[Shape, NodeDraft]] = []
    for shape in [s for s in shapes if is_artifact_box(s)]:
        direction = "in" if shape.box.left <= LEFT_MARGIN_LIMIT else "out"
        draft = NodeDraft(
            node_id=ids.make(shape.text, slide_no, shape.sid),
            node_type="data",
            label=shape.text,
            box=shape.box,
            direction=direction,
        )
        drafts.append(draft)
        artifacts.append((shape, draft))
        sid_of_node[shape.sid] = draft.node_id
        report.data_nodes += 1
    if not artifacts:
        raise SystemExit(
            f"слайд {slide_no}: не найдено ни одной плашки-артефакта (заливка {ARTIFACT_FILL})"
        )

    # 4. Подписи под шагами -> inputs узла (решение владельца, process-map-3wh.1).
    #    На слайде 8 это перечни ИСХОДНЫХ ДАННЫХ («Спецификации (BOM) с уровнями
    #    и нормами расхода», «Остатки и страховые запасы»). Правило SNP отправило
    #    бы два из трёх в outputs, где перечень входов был бы враньём.
    proxies: list[tuple[Box, str]] = []
    step_drafts = [d for d in drafts if d.node_type != "data"]
    for tb in sorted([t for t in textboxes if t.consumed_by is None], key=Shape.sort_key):
        best: tuple[float, NodeDraft] | None = None
        for draft in step_drafts:
            if draft.box.height < CAPTION_MIN_NODE_HEIGHT:
                continue
            gap = tb.box.top - draft.box.bottom
            if not (CAPTION_MIN_GAP <= gap <= CAPTION_MAX_GAP):
                continue
            overlap = min(tb.box.right, draft.box.right) - max(tb.box.left, draft.box.left)
            if overlap <= 0:
                continue
            covers_node = tb.box.left <= draft.box.left and tb.box.right >= draft.box.right
            coverage = overlap / draft.box.width if covers_node else overlap / tb.box.width
            if coverage < CAPTION_MIN_OVERLAP:
                continue
            score = (gap, abs(tb.box.left - draft.box.left))
            if best is None or score < (best[0], abs(tb.box.left - best[1].box.left)):
                best = (gap, draft)
        if best is None:
            continue
        draft = best[1]
        tb.consumed_by = f"входы узла {draft.node_id}"
        proxies.append((tb.box, draft.node_id))
        # Заголовок перечня («Параметры закупки:») — не исходные данные, а
        # подпись над ними. Та же функция и тот же дефект, что в process-map-t9j:
        # там заголовок уезжал в данные отдельной карточкой, здесь — отдельным
        # входом. Срез не применяется, если после него ничего не осталось:
        # подпись из одного заголовка лучше сохранить целиком, чем потерять.
        items = tb.paragraphs[block_items_start(tb.paragraphs) :]
        draft.inputs.extend(items or tb.paragraphs)

    # 5. Рёбра — три источника в жёстком порядке.
    node_boxes: list[tuple[Box, str]] = [(d.box, d.node_id) for d in drafts]
    node_boxes.extend(proxies)
    step_boxes = [(d.box, d.node_id) for d in step_drafts]
    members_of: dict[int, list[tuple[Box, str]]] = {}
    for container, stage_id in stage_containers:
        members_of[container.sid] = [
            (d.box, d.node_id) for d in step_drafts if stage_of_node.get(d.node_id) == stage_id
        ]

    raw_edges: list[tuple[str, str]] = []
    seen_pairs: set[tuple[str, str]] = set()

    def remember(source: str | None, target: str | None, sid: int) -> None:
        if source is None or target is None or source == target:
            reason = "петля" if source is not None and source == target else "конец не определён"
            report.lines_skipped.append(f"слайд {slide_no}: линия [{sid}] — {reason}")
            return
        if (source, target) in seen_pairs:
            return
        seen_pairs.add((source, target))
        raw_edges.append((source, target))

    # 5a. Декоративные стрелки -> связи «шаг -> шаг». Линиями они на слайде НЕ
    #     нарисованы вовсе: порядок шагов внутри этапа держится только на них.
    #     Восстанавливать его по абсциссе значило бы догадываться.
    for source, target in arrow_edges(arrows, step_boxes, EDGE_SNAP_DETAIL):
        if (source, target) not in seen_pairs:
            seen_pairs.add((source, target))
            raw_edges.append((source, target))
    report.lines_total = len(lines) + len(arrows)

    def by_binding(sid: int | None, point: tuple[float, float]) -> str | None:
        """Привязка коннектора -> узел. Привязка к КОНТЕЙНЕРУ — ближайший шаг в нём."""
        if sid is None:
            return None
        if sid in sid_of_node:
            return sid_of_node[sid]
        return nearest_target(members_of.get(sid, []), point, EDGE_SNAP_DETAIL)

    for line in lines:
        start, end = line_endpoints(line)
        # 5b. Привязки читаются ПЕРВЫМИ: у линии обратной связи слайда 8 bbox
        #     уходит ниже кромки слайда (растянутый коннектор), и геометрия её
        #     теряет, а привязка — нет.
        source = by_binding(line.start_sid, start)
        target = by_binding(line.end_sid, end)
        # 5c. Чего привязки не дали — добирается геометрией, двумя проходами.
        ranked_start = rank_candidates(node_boxes, start)
        ranked_end = rank_candidates(node_boxes, end)
        if source is None and ranked_start and ranked_start[0][0] <= EDGE_SNAP_DETAIL:
            source = ranked_start[0][1]
        if target is None and ranked_end and ranked_end[0][0] <= EDGE_SNAP_DETAIL:
            target = ranked_end[0][1]
        if source is not None and target is None:
            target = resolve_second_pass(ranked_end, source)
        elif target is not None and source is None:
            source = resolve_second_pass(ranked_start, target)
        remember(source, target, line.sid)

    # 6. Этап data-узла — этап шага, с которым он связан.
    by_id = {d.node_id: d for d in drafts}
    for shape, draft in artifacts:
        partners = [t for s, t in raw_edges if s == draft.node_id]
        partners += [s for s, t in raw_edges if t == draft.node_id]
        steps = [p for p in partners if by_id[p].node_type != "data"]
        if not steps:
            raise SystemExit(
                f"слайд {slide_no}: плашка-артефакт [{shape.sid}] «{draft.label[:50]}» "
                f"не связана ни с одним шагом — направление «{draft.direction}» недоказуемо"
            )
        if draft.direction == "out" and not any(t == draft.node_id for _, t in raw_edges):
            raise SystemExit(
                f"слайд {slide_no}: плашка [{shape.sid}] «{draft.label[:50]}» признана выходом "
                f"по положению, но не является целью ни одной связи"
            )
        stage_of_node[draft.node_id] = stage_of_node[steps[0]]

    # 6b. Внешние системы этапа. Направление берётся ИЗ ПРОИСХОЖДЕНИЯ ФИГУРЫ
    #     (draft.direction), а не из слова в тексте: detect_direction ищет
    #     «из модул…»/«в модул…», а на слайде 8 написано «…из SNP, PS» — то есть
    #     без правила «плашка левой колонки это вход» у карты не было бы ни одной
    #     внешней системы, ни одного свимлейна и ни одной записи в stage.inputs.
    #
    #     Система выходной плашки в тексте не названа («…в систему исполнения
    #     закупок»), и угадывать её запрещено (CLAUDE.md). Такая плашка остаётся
    #     обычным data-узлом без ExternalIO — это отказ выдумывать, а не заглушка.
    stage_io: dict[str, tuple[list[dict], list[dict]]] = {
        meta["id"]: ([], []) for meta in stage_meta
    }
    number_of = {meta["id"]: meta["number"] for meta in stage_meta}
    for shape, draft in artifacts:
        stage_id = stage_of_node[draft.node_id]
        codes = detect_systems(draft.label)
        if not codes:
            questions.append(
                f"слайд {slide_no}: артефакт «{draft.label[:60]}» — система в тексте не названа, "
                f"внешняя система для него не заведена"
            )
            continue
        inputs_bucket, outputs_bucket = stage_io[stage_id]
        bucket = inputs_bucket if draft.direction == "in" else outputs_bucket
        for code in codes:
            add_external_io(
                bucket,
                {
                    "system": code,
                    "label": draft.label,
                    "stage": number_of[stage_id],
                    "direction": draft.direction,
                },
            )
        if draft.system is None:
            draft.system = codes[0]

    # 7. Рёбра внутри этапа -> stage.edges, между этапами -> overviewEdges.
    stage_edges: dict[str, list[dict]] = {meta["id"]: [] for meta in stage_meta}
    overview_edges: list[dict] = []
    seen_overview: set[tuple[str, str]] = set()
    for source, target in raw_edges:
        source_stage = stage_of_node[source]
        target_stage = stage_of_node[target]
        kind = (
            "integration"
            if "integration" in {by_id[source].node_type, by_id[target].node_type}
            else "process"
        )
        if source_stage == target_stage:
            stage_edges[source_stage].append(
                {"id": f"e-{source}--{target}", "source": source, "target": target, "kind": kind}
            )
            continue
        pair = (source_stage, target_stage)
        if pair in seen_overview:
            continue
        seen_overview.add(pair)
        overview_edges.append(
            {
                "id": f"ov-{source_stage}--{target_stage}",
                "source": source_stage,
                "target": target_stage,
                "kind": "process",
            }
        )
    # 7b. Связи «система -> этап» на обзоре. Выводятся прямо из ExternalIO, а не
    #     из линий: на слайде нет уровня обзора, но принадлежность известна точно
    #     — артефакт лежит в своём этапе и называет свою систему. Формат концов
    #     тот же, что у карты SNP: код системы как идентификатор.
    for meta in stage_meta:
        stage_id = meta["id"]
        inputs_bucket, outputs_bucket = stage_io[stage_id]
        for entry in inputs_bucket:
            overview_edges.append(
                {
                    "id": f"ov-{entry['system']}--{stage_id}",
                    "source": entry["system"],
                    "target": stage_id,
                    "kind": "integration",
                }
            )
        for entry in outputs_bucket:
            overview_edges.append(
                {
                    "id": f"ov-{stage_id}--{entry['system']}",
                    "source": stage_id,
                    "target": entry["system"],
                    "kind": "integration",
                }
            )

    report.edges = sum(len(items) for items in stage_edges.values())

    # 8. Сборка этапов.
    stages: list[dict] = []
    for meta in stage_meta:
        stage_id = meta["id"]
        members = [d for d in drafts if stage_of_node.get(d.node_id) == stage_id]
        key_outputs = [d.label for d in members if d.direction == "out"][:MAX_KEY_OUTPUTS]
        stages.append(
            {
                "id": stage_id,
                "number": meta["number"],
                "title": meta["title"],
                "shortTitle": meta["shortTitle"],
                "keyOutputs": key_outputs,
                # warningsCount НЕ ПРОСТАВЛЯЕТСЯ. У SNP счётчик означает «сколько
                # типов предупреждений формирует этап»; переносить эту семантику
                # на шаг «Анализ предупреждений», который планировщик выполняет
                # сам, значило бы соврать. Поле необязательное (SPEC §3).
                "groups": [],
                "nodes": [
                    serialize_node(d)
                    for d in sorted(members, key=lambda d: (d.box.top, d.box.left, d.node_id))
                ],
                "edges": stage_edges[stage_id],
                "inputs": stage_io[stage_id][0],
                "outputs": stage_io[stage_id][1],
            }
        )

    for tb in textboxes:
        if tb.consumed_by is None:
            report.text_skipped.append(f"слайд {slide_no}: [{tb.sid}] «{tb.text[:80]}»")

    process_map = {
        "version": MAP_VERSION,
        "id": spec.map_id,
        "updatedAt": spec.updated_at,
        "title": spec.title,
        "moduleLabel": spec.module_label,
        "stages": stages,
        "overviewEdges": overview_edges,
    }
    return process_map, [report], questions, ids.counts


def build_process_map(
    collisions: dict[str, int] | None,
    spec: MapSpec,
) -> tuple[dict, list[SlideReport], list[str], Counter[str]]:
    if not spec.pptx.exists():
        raise SystemExit(f"Не найдена презентация: {spec.pptx}")

    presentation = Presentation(str(spec.pptx))
    if int(presentation.slide_width) != SLIDE_WIDTH_EMU:
        raise SystemExit(
            f"Неожиданная ширина слайда {presentation.slide_width} EMU (ожидалось {SLIDE_WIDTH_EMU})"
        )
    slides = list(presentation.slides)
    if len(slides) != spec.slides:
        raise SystemExit(f"Ожидалось {spec.slides} слайдов, найдено {len(slides)}")

    reports: list[SlideReport] = []
    questions: list[str] = []

    overview_report = SlideReport(slide_no=2, role="overview")
    overview_shapes = read_slide(slides[1], overview_report)
    overview = build_overview(overview_shapes, overview_report)

    ids = IdFactory(collisions)
    seen_signatures: set[tuple] = set()
    stages: list[dict] = []
    for index in range(spec.stage_count):
        slide_no = index + 3
        report = SlideReport(slide_no=slide_no)
        stage = build_stage(
            slide_no=slide_no,
            stage_number=index + 1,
            shapes=read_slide(slides[index + 2], report),
            overview_title=overview.titles[index] if index < len(overview.titles) else None,
            ids=ids,
            report=report,
            seen_signatures=seen_signatures,
            spec=spec,
        )
        stages.append(stage)
        reports.append(report)

    # Рёбра, которых в презентации нет (OWNER_DECISION_EDGES) — досыпаются сразу
    # после разбора слайдов детализации, до сверок и отчётов: изолированные узлы
    # и целостность считаются уже по итоговому набору рёбер. reports здесь ещё
    # содержит ровно 4 отчёта этапов, отчёт обзора вставляется в начало ниже.
    #
    # Только во ВТОРОЙ фазе: в первой (collisions=None) IdFactory выдаёт
    # временные id вида «base~N» ради подсчёта коллизий, и сверять с ними id,
    # названные в решении владельца, бессмысленно — не нашлось бы ни одного.
    # Результат первой фазы всё равно выбрасывается, кроме карты коллизий, а
    # рёбра решения новых id не создают, так что пропуск ни на что не влияет.
    if collisions is not None:
        apply_owner_decision_edges(stages, reports, decisions_for(spec, "OWNER_DECISION_EDGES"))
        # Деление группы сверяется по подписям узлов, а не по id, поэтому
        # временные id первой фазы ему не мешают — но держим рядом с рёбрами:
        # обе таблицы описывают решения владельца поверх презентации.
        apply_stage_group_split(stages, reports, decisions_for(spec, "STAGE_GROUP_SPLIT"))

    # Внешние системы этапа, названные владельцем (process-map-vjz.5). Идёт
    # ПОСЛЕ сборки этапов: таблица дописывает в stage["inputs"], которые к этому
    # моменту уже собраны автоматикой, и проверяет, что запись не задвоилась.
    overview_texts = {
        normalize_text(shape.text).casefold()
        for shape in overview_shapes
        if shape.has_text
    }
    external_io = decisions_for(spec, "OWNER_DECISION_EXTERNAL_IO")
    apply_owner_decision_external_io(stages, overview_texts, overview_report, external_io)

    # Правая колонка выходов этапа (SPEC §4.2) — блоки выходов слайда 2.
    #
    # Стоят они под боксами ГРУПП, а не под контейнером этапа (process-map-2of):
    # у этапа 1 это [182] под «Преобразование прогноза…» и [184] под «Обогащение
    # прогноза клиентскими заказами», у этапа 3 — [152], [153] и [163] под тремя
    # своими группами. Все лежат в одной горизонтальной полосе T≈4.61–4.67 млн
    # EMU и относятся к этапу целиком, поэтому на выборку это не влияет — но
    # искать их под контейнером этапа бесполезно.
    # direction='out' — по происхождению: это блок выходов этапа в обзоре
    # (см. NodeDraft.direction, задача process-map-24p). Абсцисса такого блока
    # к колонке отношения не имеет: у этапов 1 и 2 она левее середины области
    # шагов, и прежнее геометрическое правило зачисляло эти узлы во входы.
    #
    # Артефакт, который уже есть среди узлов этапа, вторым узлом не заводится
    # (проверка по casefold ниже) и направления НЕ меняет: на слайде
    # детализации он нарисован в левой колонке входов, и переписать ему
    # direction на 'out' значило бы решить за владельца процесса, что
    # презентация в одном из двух мест ошибается. Такие узлы перечислены в
    # отчёте (report.dedup_key_outputs).
    for index, stage in enumerate(stages):
        blocks = overview.output_blocks[index] if index < len(overview.output_blocks) else []
        inbound = {
            node["label"].casefold()
            for node in stage["nodes"]
            if node.get("direction") == "in"
        }
        stage["keyOutputs"] = choose_key_outputs(blocks, inbound)
        existing = {node["label"].casefold() for node in stage["nodes"]}
        added: list[dict] = []
        for paragraphs, box, sid in blocks:
            # step считается по ВСЕМ абзацам, включая заголовок: высота блока на
            # слайде поделена между ними, и пропуск заголовка не должен сдвигать
            # остальные пункты с их настоящих слайдовых координат.
            step = box.height / max(len(paragraphs), 1)
            items_start = block_items_start(paragraphs)
            for para_index, para in enumerate(paragraphs):
                if para_index < items_start:
                    # Заголовок перечня — не артефакт процесса (process-map-t9j).
                    continue
                if para.casefold() in existing:
                    twin = next(
                        (n for n in stage["nodes"] if n["label"].casefold() == para.casefold()),
                        None,
                    )
                    if twin is not None and twin.get("direction") == "in":
                        overview_report.dedup_key_outputs.append(
                            f"этап {stage['number']}: «{para}» назван выходом этапа в обзоре "
                            f"(слайд 2), но на слайде детализации это узел «{twin['id']}» из "
                            f"колонки входов — оставлен входом, отдельный узел-выход не создан"
                        )
                    continue
                existing.add(para.casefold())
                added.append(
                    serialize_node(
                        NodeDraft(
                            node_id=ids.make(para, 2, sid, para_index),
                            node_type="data",
                            label=para,
                            box=Box(
                                box.left, int(box.top + para_index * step), box.width, int(step)
                            ),
                            direction="out",
                        )
                    )
                )
        stage["nodes"].extend(added)
        overview_report.data_nodes += len(added)
        stage["warningsCount"] = count_warnings(stage)

    # Сверка списка групп: обзор (слайд 2) против слайдов детализации.
    for index, stage in enumerate(stages):
        overview_groups = overview.group_labels[index] if index < len(overview.group_labels) else []
        detail_groups = [g["label"] for g in stage["groups"]]
        for label in [g for g in overview_groups if g not in detail_groups]:
            questions.append(
                f"этап {stage['number']}: группа «{label}» есть в обзоре (слайд 2), "
                f"но не найдена на слайде детализации"
            )
        for label in [g for g in detail_groups if g not in overview_groups]:
            questions.append(
                f"этап {stage['number']}: группа «{label}» есть на слайде детализации, "
                f"но не найдена в обзоре (слайд 2)"
            )

    # Обзорные рёбра: перевод внутренних ключей в id этапов и коды систем.
    stage_key_to_id = {f"@stage{stage['number']}": stage["id"] for stage in stages}
    system_by_sid = {f"@sys:{s['code']}:{s['sid']}": s for s in overview.systems}

    resolved: list[tuple[str, str, str]] = []
    for edge in overview.edges:
        source, target = edge["source"], edge["target"]
        s_key, t_key = stage_key_to_id.get(source), stage_key_to_id.get(target)
        s_sys, t_sys = system_by_sid.get(source), system_by_sid.get(target)
        if s_key and t_key:
            resolved.append((s_key, t_key, "process"))
        elif s_key and t_sys:
            direction = register_system(stages, t_sys, source, "out")
            resolved.append(
                (s_key, t_sys["code"], "integration")
                if direction == "out"
                else (t_sys["code"], s_key, "integration")
            )
        elif s_sys and t_key:
            direction = register_system(stages, s_sys, target, "in")
            resolved.append(
                (s_sys["code"], t_key, "integration")
                if direction == "in"
                else (t_key, s_sys["code"], "integration")
            )
        else:
            overview_report.lines_skipped.append(
                f"слайд 2: ребро {source} → {target} — не пара «этап/система»"
            )

    overview_edges: list[dict] = []
    seen: set[tuple[str, str]] = set()
    for source, target, kind in resolved:
        if (source, target) in seen:
            continue
        seen.add((source, target))
        overview_edges.append(
            {"id": f"ov-{source}--{target}", "source": source, "target": target, "kind": kind}
        )
    # Ребро для внешней системы, названной владельцем (process-map-vjz.5).
    #
    # Линии на слайде для неё нет — и не может быть: её отсутствие и есть причина,
    # по которой автоматика систему не нашла. Но без ребра карточка встала бы в
    # свимлейн с подписью входа этапа 1 и стрелкой в этап 2: свимлейн держит одну
    # карточку на систему (collectSystems в overviewGraph.ts), и ERP этапов 1 и 2
    # делят её. Подпись при этом от одного этапа, а пунктир — к другому.
    #
    # Точка применения той же таблицы, что и выше, — и отбор по карте здесь
    # такой же обязательный: иначе чужое решение добавило бы ребро в обзор.
    for entry in external_io:
        stage = next(s for s in stages if s["number"] == entry["stage"])
        pair = (
            (entry["system"], stage["id"])
            if entry["direction"] == "in"
            else (stage["id"], entry["system"])
        )
        if pair in seen:
            raise SystemExit(
                f"OWNER_DECISION_EXTERNAL_IO ({entry['task']}): ребро {pair[0]} → {pair[1]} "
                f"уже нашлось на слайде — презентация изменилась, и решение владельца "
                f"больше не нужно. Обновите таблицу в scripts/import-pptx.py."
            )
        seen.add(pair)
        overview_edges.append(
            {"id": f"ov-{pair[0]}--{pair[1]}", "source": pair[0], "target": pair[1], "kind": "integration"}
        )

    overview_report.edges = len(overview_edges)

    reports.insert(0, overview_report)
    for report in reports:
        questions.extend(report.questions)

    process_map = {
        "version": MAP_VERSION,
        "id": spec.map_id,
        "updatedAt": spec.updated_at,
        "title": spec.title,
        "moduleLabel": spec.module_label,
        "stages": stages,
        "overviewEdges": overview_edges,
    }
    return process_map, reports, questions, ids.counts


def build_three_tier_map(
    collisions: dict[str, int] | None,
    spec: MapSpec,
) -> tuple[dict, list[SlideReport], list[str], Counter[str]]:
    """
    Профиль «три уровня» (карта inplan, process-map-9mn.14) — ПОКА ЗАГЛУШКА.

    Сам построитель пишет подзадача process-map-9mn.14.6 (подзадачи 14.2–14.5
    готовят для него разбор слайдов); эта функция только останавливает импорт с
    понятным сообщением. Почему профиль всё же зарегистрирован, а не оставлен
    неизвестным, — см. PROFILE_BUILDERS.

    Готово для него:
      · реестр модулей с навигационных слайдов — read_module_index
        (process-map-9mn.14.2);
      · слайд 1 — read_modules_slide: колонки ряда модулей, передачи между
        модулями, полосы (FP&A); reconcile_activity_lists — сверка списков
        действий слайда 1 с шагами детализации, только в отчёт
        (process-map-9mn.14.3).
    Отсюда они пока НЕ вызываются: заглушка останавливает импорт раньше первого
    чтения презентации.
    """
    raise SystemExit(
        f"Профиль «three-tier» (карта «{spec.key}») объявлен, но его построитель ещё "
        f"не написан — это подзадача process-map-9mn.14.6. Ничего не записано."
    )


# Сигнатура построителя карты: (коллизии slug'ов или None для первой фазы,
# карта) → (документ, отчёты слайдов, открытые вопросы, счётчик базовых slug'ов).
Builder = Callable[
    [dict[str, int] | None, MapSpec],
    tuple[dict, list[SlideReport], list[str], Counter[str]],
]

# Профиль разбора → построитель карты (process-map-9mn.14.1).
#
# ЗАЧЕМ СЛОВАРЬ. Раньше в main() стояла тернарка «single-slide — свой
# построитель, иначе build_process_map»: любой профиль, кроме single-slide, —
# опечатка или третий профиль, которого импортёр ещё не умеет, — молча уходил
# в разбор презентации SNP. Здесь неизвестный профиль — остановка со списком
# известных (builder_for), а добавить профиль можно только строкой в этом
# словаре, на виду.
#
# ПОЧЕМУ 'three-tier' ЗАРЕГИСТРИРОВАН ЗАГЛУШКОЙ, А НЕ ОСТАВЛЕН НЕИЗВЕСТНЫМ.
# PROFILE_READS уже объявляет, что читает этот профиль, — и ключи двух реестров
# обязаны совпадать (это проверяет самопроверка): профиль с построителем, но
# без объявления, уронил бы decisions_for, а объявление без построителя —
# мёртвая запись, по которой unread_decisions судит о чтении, которого нет.
# Заглушка к тому же честнее «неизвестного профиля»: запись карты inplan в MAPS,
# появись она раньше 14.6, остановит импорт словами «построитель ещё не написан,
# 14.6», а не ложным «такого профиля нет». Разобрать ею не получится ничего —
# она останавливает импорт до первого чтения презентации.
PROFILE_BUILDERS: dict[str, Builder] = {
    "overview+details": build_process_map,
    "single-slide": build_single_slide_map,
    "three-tier": build_three_tier_map,
}


def builder_for(spec: MapSpec, builders: Mapping[str, Builder] = PROFILE_BUILDERS) -> Builder:
    """
    Построитель карты по её профилю. Неизвестный профиль — остановка со списком
    известных, а не разбор чужим построителем.

    `builders` — только для самопроверки (подставные построители); рабочий путь
    зовёт функцию без него.
    """
    build = builders.get(spec.profile)
    if build is None:
        raise SystemExit(
            f"У карты «{spec.key}» неизвестный профиль разбора «{spec.profile}». "
            f"Известны: {', '.join(sorted(builders))}."
        )
    return build


def apply_owner_decision_external_io(
    stages: list[dict],
    overview_texts: AbstractSet[str],
    report: SlideReport,
    entries: Sequence[dict],
) -> None:
    """
    Добавляет внешние системы этапа, названные владельцем, а не выведенные из текста.

    ЗАЧЕМ ОТДЕЛЬНАЯ ТАБЛИЦА. ExternalIO собирается автоматически только когда в
    тексте фигуры нашлись И код системы, И направление. Для «Управление
    транзакционными данными» нет ни того, ни другого: код ERP владелец назвал
    отдельно, а слова «из модуля» в презентации нет. Дописать распознавание
    нельзя — оно начало бы срабатывать на чужих текстах.

    Расхождение с презентацией — остановка импорта, как в
    apply_owner_decision_edges и apply_stage_input_enrichment: если слайд
    поправят, решение владельца обязано упасть громко, а не рассосаться молча.

    `entries` — уже отобранные по карте записи (decisions_for), и параметр
    ОБЯЗАТЕЛЬНЫЙ. Умолчания «вся таблица целиком» здесь быть не может: до
    появления ключа `map` оно означало «правильно», а теперь означало бы
    «применить решения всех карт сразу» — то самое, ради чего задача и
    затевалась. То же у apply_stage_group_split и apply_owner_decision_edges.
    """
    for entry in entries:
        label = entry["label"]
        if normalize_text(label).casefold() not in overview_texts:
            raise SystemExit(
                f"OWNER_DECISION_EXTERNAL_IO ({entry['task']}): на слайде обзора больше "
                f"нет текста «{label}» — презентация изменилась. Импорт остановлен, "
                f"чтобы решение владельца не потерялось молча: обновите таблицу в "
                f"scripts/import-pptx.py."
            )
        stage = next((s for s in stages if s["number"] == entry["stage"]), None)
        if stage is None:
            raise SystemExit(
                f"OWNER_DECISION_EXTERNAL_IO ({entry['task']}): этапа {entry['stage']} нет"
            )
        bucket = stage["inputs"] if entry["direction"] == "in" else stage["outputs"]
        if any(normalize_text(io["label"]).casefold() == normalize_text(label).casefold() for io in bucket):
            raise SystemExit(
                f"OWNER_DECISION_EXTERNAL_IO ({entry['task']}): «{label}» уже есть среди "
                f"внешних систем этапа {entry['stage']} — презентация изменилась и "
                f"запись больше не нужна. Обновите таблицу в scripts/import-pptx.py."
            )
        bucket.append(
            {
                "system": entry["system"],
                "label": label,
                "stage": entry["stage"],
                "direction": entry["direction"],
            }
        )
        report.owner_external_io.append(
            f"этап {entry['stage']}: {entry['system']} — «{label}» ({entry['source']})"
        )


def apply_stage_group_split(
    stages: list[dict],
    stage_reports: Sequence[SlideReport],
    splits: Sequence[dict],
) -> None:
    """
    Выделяет часть узлов этапа в отдельную группу (STAGE_GROUP_SPLIT, process-map-028).

    Нужно там, где обзорный слайд показывает у этапа две группы, а слайд
    детализации рисует один контейнер: геометрии для деления нет, и вывести его
    нельзя — только записать решение владельца.

    Расхождение с презентацией останавливает импорт, как и в остальных таблицах
    решений: если шаг переименовали, молча потерять деление нельзя.
    """
    by_number = {stage["number"]: stage for stage in stages}
    for split in splits:
        report = stage_reports[split["stage"] - 1]
        stage = by_number.get(split["stage"])
        if stage is None:
            raise SystemExit(
                f"STAGE_GROUP_SPLIT ({split['task']}): этапа {split['stage']} нет "
                f"в презентации — решение владельца применить не к чему"
            )

        by_label = {node["label"]: node for node in stage["nodes"]}
        missing = [label for label in split["nodes"] if label not in by_label]
        if missing:
            raise SystemExit(
                f"STAGE_GROUP_SPLIT ({split['task']}): на этапе {split['stage']} нет "
                f"узлов {', '.join(repr(m) for m in missing)} — презентация изменилась. "
                f"Импорт остановлен, чтобы решение владельца не потерялось молча: "
                f"обновите список в scripts/import-pptx.py."
            )

        group_id = slugify(split["label"])
        if any(group["id"] == group_id for group in stage["groups"]):
            raise SystemExit(
                f"STAGE_GROUP_SPLIT ({split['task']}): группа «{split['label']}» уже есть "
                f"на этапе {split['stage']} — презентация изменилась и делить больше "
                f"не нужно. Обновите список в scripts/import-pptx.py."
            )
        stage["groups"].append({"id": group_id, "label": split["label"]})

        for label in split["nodes"]:
            node = by_label[label]
            was = node.get("group")
            node["group"] = group_id
            report.owner_groups.append(
                f"этап {split['stage']}: «{label[:60]}» — группа «{was}» → «{group_id}» "
                f"({split['task']}), на слайде детализации деления нет"
            )


def apply_owner_decision_edges(
    stages: list[dict],
    stage_reports: Sequence[SlideReport],
    decisions: Sequence[dict],
) -> None:
    """
    Досыпает в этапы рёбра из OWNER_DECISION_EDGES — единственные рёбра
    документа, которых нет в презентации (см. комментарий у самой константы).

    Инварианты те же, что у прочитанных со слайда рёбер, и проверяются здесь,
    а не только в src/data/schema.ts::validateIntegrity: оба конца — узлы ТОГО
    ЖЕ этапа, id ребра уникален (формат `e-{source}--{target}` общий с
    построенными по линиям, поэтому «уже есть такое ребро» и «дубль id» — одно
    и то же условие и разбирается одинаково).

    Узел, названный в решении, но исчезнувший из презентации, — ОСТАНОВКА
    импорта, а не пропуск: пропустить значило бы тихо потерять решение
    владельца, а именно ради того, чтобы оно не терялось, список и заведён.
    """
    by_number = {stage["number"]: stage for stage in stages}
    for decision in decisions:
        report = stage_reports[decision["stage"] - 1]
        stage = by_number.get(decision["stage"])
        if stage is None:
            raise SystemExit(
                f"OWNER_DECISION_EDGES ({decision['task']}): этапа {decision['stage']} нет "
                f"в презентации — решение владельца применить не к чему"
            )
        node_ids = {node["id"] for node in stage["nodes"]}
        existing = {edge["id"] for edge in stage["edges"]}
        endpoints = (decision["source"], *decision["targets"])
        missing = [node_id for node_id in endpoints if node_id not in node_ids]
        if missing:
            raise SystemExit(
                f"OWNER_DECISION_EDGES ({decision['task']}): на этапе {decision['stage']} нет "
                f"узлов {', '.join(missing)} — презентация изменилась. Импорт остановлен, чтобы "
                f"решение владельца не потерялось молча: обновите список в scripts/import-pptx.py."
            )
        for target in decision["targets"]:
            edge_id = f"e-{decision['source']}--{target}"
            if edge_id in existing:
                report.owner_edges.append(
                    f"этап {decision['stage']}: {decision['source']} → {target} — уже есть "
                    f"в презентации (стрелка нарисована), решение владельца её подтверждает"
                )
                continue
            existing.add(edge_id)
            stage["edges"].append(
                {
                    "id": edge_id,
                    "source": decision["source"],
                    "target": target,
                    "kind": decision["kind"],
                }
            )
            report.owner_edges.append(
                f"этап {decision['stage']}: {decision['source']} → {target} — ДОБАВЛЕНО "
                f"по решению владельца ({decision['task']}), в презентации стрелки нет"
            )


def register_system(stages: list[dict], system: dict, stage_key: str, direction_hint: str) -> str:
    """
    Внешняя система обзора попадает в ExternalIO этапа, к которому её ведёт стрелка.
    Направление берём из текста бокса («из модуля X» / «в модуль X»); если текст
    направления не содержит (бокс «ERP»), используем направление самой стрелки.
    """
    direction = system["direction"] or direction_hint
    stage = next((s for s in stages if f"@stage{s['number']}" == stage_key), None)
    if stage is None:
        return direction
    bucket = stage["inputs"] if direction == "in" else stage["outputs"]
    add_external_io(
        bucket,
        {
            "system": system["code"],
            "label": system["label"],
            "stage": stage["number"],
            "direction": direction,
        },
    )
    return direction


# --------------------------------------------------------------------------------------
# Отчёт-сверка
# --------------------------------------------------------------------------------------


def isolated_nodes(stage: dict) -> list[dict]:
    """
    Не-data узлы этапа без единого ребра.

    Это НЕ дефект импорта: изолированный узел означает, что соответствующей
    связи нет и в самой презентации. Связи не достраиваются (CLAUDE.md запрещает
    изобретать процесс), поэтому список печатается поимённо — по нему владелец
    процесса видит, где связь нужно проставить вручную.
    """
    connected: set[str] = set()
    for edge in stage["edges"]:
        connected.add(edge["source"])
        connected.add(edge["target"])
    return [n for n in stage["nodes"] if n["type"] != "data" and n["id"] not in connected]


def print_report_block(title: str, intro: Sequence[str], items: Sequence[str]) -> None:
    """
    Блок отчёта, который печатается, ТОЛЬКО если есть что печатать
    (process-map-9mn.14.3). Пустой список — блока нет вовсе, а не «пусто»:
    блоки слайда модулей заполняет лишь трёхуровневая карта, и строка «не
    читали» в отчётах SNP и MRP была бы шумом — к тому же меняющим их
    побайтово.

    Строка, начатая пробелом, — продолжение предыдущей (колонка ряда, строка
    списка действий) и печатается с отступом без маркера; остальные — с «·».
    """
    if not items:
        return
    print("\n" + "=" * 78)
    print(title)
    print("=" * 78)
    for line in intro:
        print(f"  {line}")
    for item in items:
        print(f"      {item.lstrip()}" if item.startswith(" ") else f"    · {item}")


def print_report(
    process_map: dict, reports: Sequence[SlideReport], questions: Sequence[str], spec: MapSpec
) -> None:
    print("=" * 78)
    print("ОТЧЁТ-СВЕРКА  scripts/import-pptx.py")
    print(f"источник: {spec.pptx.name}")
    print("=" * 78)

    for report in reports:
        print(f"\n--- слайд {report.slide_no} " + "-" * 55)
        if report.role == "overview":
            print(f"  этапов (контейнеров): {len(process_map['stages'])}")
            print(f"  обзорных рёбер:       {report.edges}")
            print(f"  узлов-выходов (data): {report.data_nodes}")
        else:
            print(f"  узлов:                {report.nodes} (из них data: {report.data_nodes})")
            print(f"  групп:                {report.groups}")
            print(f"  рёбер:                {report.edges} из {report.lines_total} линий/стрелок")
        if report.promoted:
            print(f"  узлы из текстбоксов ({len(report.promoted)}):")
            for item in report.promoted:
                print(f"    + {item}")
        if report.lines_skipped:
            print(f"  линии без однозначных концов ({len(report.lines_skipped)}):")
            for item in report.lines_skipped:
                print(f"    · {item}")
        if report.loose_attachments:
            print(f"  нестрогие привязки текста ({len(report.loose_attachments)}):")
            for item in report.loose_attachments:
                print(f"    · {item}")
        if report.text_skipped:
            print(f"  ПРОПУЩЕННЫЕ ФИГУРЫ С ТЕКСТОМ ({len(report.text_skipped)}):")
            for item in report.text_skipped:
                print(f"    ! {item}")
        elif report.role != "overview":
            print("  пропущенных фигур с текстом: нет")

    print("\n" + "=" * 78)
    print("ИТОГО ПО ДОКУМЕНТУ")
    print("=" * 78)
    total_nodes = sum(len(s["nodes"]) for s in process_map["stages"])
    by_type: Counter[str] = Counter()
    for stage in process_map["stages"]:
        for node in stage["nodes"]:
            by_type[node["type"]] += 1
    print(f"  узлов всего: {total_nodes}")
    for key in ("step", "data", "integration", "warning"):
        print(f"    {key:<12} {by_type.get(key, 0)}")
    print(f"  рёбер в этапах: {sum(len(s['edges']) for s in process_map['stages'])}")
    print(f"  обзорных рёбер: {len(process_map['overviewEdges'])}")
    print(f"  групп:          {sum(len(s['groups']) for s in process_map['stages'])}")
    for stage in process_map["stages"]:
        print(
            f"  этап {stage['number']} «{stage['shortTitle']}»: "
            f"{len(stage['nodes'])} узлов, {len(stage['edges'])} рёбер, "
            f"{len(stage['groups'])} групп, {len(stage['inputs'])} входов, "
            f"{len(stage['outputs'])} выходов, warningsCount={stage.get('warningsCount', '—')}"
        )
    # Направление data-узлов (SPEC §3, задача process-map-24p). Печатается
    # отдельным блоком, потому что это ответ на вопрос «почему на экране этапа
    # столько-то входов и столько-то выходов», а прежний ответ («так легли
    # координаты») больше не действует.
    print("\n" + "=" * 78)
    print("НАПРАВЛЕНИЕ data-УЗЛОВ (node.direction) — КОЛОНКИ ВХОДОВ И ВЫХОДОВ")
    print("=" * 78)
    print("  Ставится по происхождению фигуры, не по координатам:")
    print("    'in'  — левая колонка входов слайда детализации;")
    print("    'out' — блок выходов этапа под его контейнером на слайде обзора.")
    unset = 0
    for stage in process_map["stages"]:
        data_nodes = [n for n in stage["nodes"] if n["type"] == "data"]
        ins = sum(1 for n in data_nodes if n.get("direction") == "in")
        outs = sum(1 for n in data_nodes if n.get("direction") == "out")
        unset += len(data_nodes) - ins - outs
        flow = len(stage["nodes"]) - len(data_nodes)
        print(
            f"  этап {stage['number']} «{stage['shortTitle']}»: поток {flow}, "
            f"входов {ins}, выходов {outs}"
        )
    if unset:
        print(f"  ВНИМАНИЕ: data-узлов без direction: {unset} — это ошибка импортёра:")
        print("  все data-узлы рождаются в одном из двух мест, и оба знают направление.")
    else:
        print("  data-узлов без direction: нет")
    dedup = [item for report in reports for item in report.dedup_key_outputs]
    if dedup:
        print(f"  артефакт назван выходом в обзоре, но существует входом ({len(dedup)}):")
        for item in dedup:
            print(f"    · {item}")

    # Рёбра, которых в презентации НЕТ. Отдельный блок и есть то место, по
    # которому через полгода видно, что источник этих связей — решение
    # владельца процесса, а не стрелка на слайде (задача process-map-7bz).
    owner_edges = [item for report in reports for item in report.owner_edges]
    print("\n" + "=" * 78)
    print("РЁБРА ПО РЕШЕНИЮ ВЛАДЕЛЬЦА ПРОЦЕССА — В ПРЕЗЕНТАЦИИ ИХ НЕТ")
    print("=" * 78)
    if owner_edges:
        print("  Источник этих связей — OWNER_DECISION_EDGES в scripts/import-pptx.py,")
        print("  а НЕ линия на слайде. Всё остальное в документе прочитано из презентации.")
        for item in owner_edges:
            print(f"    · {item}")
    else:
        print("  список OWNER_DECISION_EDGES пуст — все рёбра прочитаны из презентации")

    # Входы, взятые со слайда ОБЗОРА вместо слайда детализации. Текст всё равно
    # из презентации, но выбор источника сделал владелец — блок и есть то место,
    # по которому это видно через полгода (задача process-map-qjl).
    owner_inputs = [item for report in reports for item in report.owner_inputs]
    print("\n" + "=" * 78)
    print("ВХОДЫ ПО СЛАЙДУ ОБЗОРА — НА СЛАЙДЕ ДЕТАЛИЗАЦИИ ИХ НЕТ ИЛИ ОНИ КОРОЧЕ")
    print("=" * 78)
    if owner_inputs:
        print("  Источник — STAGE_INPUT_ENRICHMENT в scripts/import-pptx.py: текст взят")
        print("  из презентации, но с другого слайда, чем остальная колонка входов.")
        for item in owner_inputs:
            print(f"    · {item}")
    else:
        print("  список STAGE_INPUT_ENRICHMENT пуст — все входы прочитаны со слайдов детализации")

    # Внешние системы, названные владельцем (process-map-vjz.5): кода системы
    # или направления в тексте презентации нет, автоматика их взять не могла.
    print("\n" + "=" * 78)
    print("ВНЕШНИЕ СИСТЕМЫ ПО РЕШЕНИЮ ВЛАДЕЛЬЦА — В ТЕКСТЕ НЕТ КОДА ИЛИ НАПРАВЛЕНИЯ")
    print("=" * 78)
    owner_external_io = [item for report in reports for item in report.owner_external_io]
    if owner_external_io:
        print("  Источник — OWNER_DECISION_EXTERNAL_IO в scripts/import-pptx.py.")
        for item in owner_external_io:
            print(f"    · {item}")
    else:
        print("  список OWNER_DECISION_EXTERNAL_IO пуст")

    # Деление группы, которого на слайде детализации нет (process-map-028).
    owner_groups = [item for report in reports for item in report.owner_groups]
    print("\n" + "=" * 78)
    print("ГРУППЫ ПО РЕШЕНИЮ ВЛАДЕЛЬЦА — НА СЛАЙДЕ ДЕТАЛИЗАЦИИ ДЕЛЕНИЯ НЕТ")
    print("=" * 78)
    if owner_groups:
        print("  Источник — STAGE_GROUP_SPLIT в scripts/import-pptx.py: обзорный слайд")
        print("  показывает две группы, слайд детализации — один контейнер.")
        for item in owner_groups:
            print(f"    · {item}")
    else:
        print("  список STAGE_GROUP_SPLIT пуст — все группы прочитаны со слайдов детализации")

    # Рёбра, разрешённые явной привязкой коннектора (process-map-3wh.16).
    cxn = [item for report in reports for item in report.cxn_edges]
    print("\n" + "=" * 78)
    print("РЁБРА ПО ПРИВЯЗКАМ КОННЕКТОРОВ — НЕ ПО ГЕОМЕТРИИ")
    print("=" * 78)
    if cxn:
        print(f"  {len(cxn)} рёбер, у которых хотя бы один конец взят из stCxn/endCxn.")
        print("  Привязка точнее геометрии: указывает на фигуру, а не на точку.")
        print("  Привязка к контейнеру группы разрешается в ближайший шаг этой группы;")
        print("  веерную связь «в группу целиком» коннектор выразить не может — для неё")
        print("  остаётся OWNER_DECISION_EDGES.")
        for item in cxn:
            print(f"    · {item}")
    else:
        print("  привязок в презентации нет — все связи выведены геометрически")

    # Фигуры, найденные внутри групп (process-map-9mn.13). Блок нужен по той же
    # причине, что и соседние: заход в группу — это место, где координаты
    # ПЕРЕСЧИТАНЫ, а не взяты как есть, и увидеть это больше негде.
    from_groups = [item for report in reports for item in report.from_groups]
    print("\n" + "=" * 78)
    print("ФИГУРЫ, ПРОЧИТАННЫЕ ВНУТРИ ГРУПП — ИХ КООРДИНАТЫ ПЕРЕСЧИТАНЫ")
    print("=" * 78)
    if from_groups:
        print(f"  {len(from_groups)} фигур лежат в группах (p:grpSp), а не прямо на слайде.")
        print("  Рамка группы задаёт систему координат детей (a:chOff/a:chExt против")
        print("  a:off/a:ext), поэтому left/top таких фигур приведены к координатам слайда.")
        print("  Повёрнутая или отражённая группа импорт останавливает: положить фигуру")
        print("  не туда можно молча, а увидеть это по карте — нельзя.")
        for item in from_groups:
            print(f"    · {item}")
    else:
        print("  групп на разобранных слайдах нет — все фигуры лежат прямо на слайде")

    # Каким правилом найдена полоса фаз. Блок печатается, ТОЛЬКО если полосу
    # вообще искали: два собранных профиля ярусами не пользуются, и постоянная
    # строка «не искали» в их отчётах была бы шумом, а не сведением.
    band_rules = [
        (report.slide_no, report.phase_band_rule)
        for report in reports
        if report.phase_band_rule is not None
    ]
    if band_rules:
        print("\n" + "=" * 78)
        print("ПОЛОСА ФАЗ — КАКИМ ПРАВИЛОМ НАЙДЕНА")
        print("=" * 78)
        print("  'containers' — фаза это бесфонная рамка с подписью сверху;")
        print("  'top-row' — фаза это плашка с текстом из верхнего ряда слайда.")
        print("  Ветку выбирает сам слайд, и по готовой карте её уже не видно.")
        for slide_no, rule in band_rules:
            print(f"    · слайд {slide_no}: {rule}")

    # Реестр модулей (process-map-9mn.14.2). Печатается, только если его
    # читали, — по той же причине, что и блок полосы фаз выше. Порядок колоды
    # стоит рядом с порядком кнопок потому, что они расходятся (MRP в колоде
    # раньше PS), а номер модуля берётся по кнопкам: без обоих порядков на виду
    # «модуль 4 — PS» выглядело бы ошибкой нумерации.
    modules = [item for report in reports for item in report.module_index]
    if modules:
        print("\n" + "=" * 78)
        print("МОДУЛИ КАРТЫ — НОМЕР ПО КНОПКАМ НАВИГАЦИИ, А НЕ ПО ПОРЯДКУ КОЛОДЫ")
        print("=" * 78)
        print("  Номер модуля — место его кнопки в ряду навигационного слайда (решение")
        print("  владельца process-map-9mn.31, п. 2); название — первый абзац заголовка")
        print("  навигационного слайда (решение владельца process-map-9mn.6).")
        for item in modules:
            print(f"    · {item}")

    # Слайд 1 трёхуровневой карты (process-map-9mn.14.3): четыре блока, и каждый
    # печатается, только если его заполняли, — как два блока выше. У карт SNP и
    # MRP слайда модулей нет, и их отчёты обязаны остаться побайтово прежними.
    print_report_block(
        "КОРОБКИ МОДУЛЕЙ НА СЛАЙДЕ 1 — КОЛОНКИ РЯДА ШЕВРОНОВ",
        (
            "Ряд модулей — ряд автофигур с текстом, где больше всего коробок опознано по",
            "реестру. Правило опознания: 'exact' — первый абзац равен названию модуля с",
            "навигационного слайда; 'prefix' — начинается с него на границе слова;",
            "'code' — абзац «(КОД)», абзац, кончающийся «(КОД)», или сам код. Колонка",
            "вне реестра (TPM) остаётся колонкой: над ней лежат плашки, но узлов она",
            "не даёт.",
        ),
        [item for report in reports for item in report.module_columns],
    )
    print_report_block(
        "ПЕРЕДАЧИ МЕЖДУ МОДУЛЯМИ — ПЛАШКИ НАД РЯДОМ, ЛЕВАЯ КОЛОНКА → ПРАВАЯ",
        (
            "Передача — плашка над двумя соседними колонками; источник — левая.",
            "Сторона вне реестра не даёт ни узла, ни ребра модулей (решение",
            "process-map-9mn.31, п. 8); плашка над одной колонкой не импортируется.",
        ),
        [item for report in reports for item in report.module_transfers],
    )
    print_report_block(
        "ПОЛОСЫ УРОВНЯ 1 — ПОД РЯДОМ МОДУЛЕЙ, НЕ МОДУЛИ",
        (
            f"Полоса — автофигура с текстом под рядом, задевающая {LANE_MIN_COLUMNS} колонки и",
            "больше. Подпись — «код · название» (решение process-map-9mn.31, п. 5).",
        ),
        [item for report in reports for item in report.module_lanes],
    )
    print_report_block(
        "СПИСКИ ДЕЙСТВИЙ СЛАЙДА 1 ПРОТИВ ШАГОВ СЛАЙДОВ ДЕТАЛИЗАЦИИ — ТОЛЬКО СВЕРКА",
        (
            "В карту списки не идут: это третье описание того же содержания, и оно",
            "расходится со слайдами детализации. '=' — строка нашлась среди шагов",
            "своего модуля, '≠' — не нашлась (регистр и ё/е не различаются).",
        ),
        [item for report in reports for item in report.activity_check],
    )

    # Узлы, ставшие интеграциями не по заливке, а по коду системы (7v1).
    promoted = [item for report in reports for item in report.promoted_integrations]
    print("\n" + "=" * 78)
    print("ИНТЕГРАЦИИ ПО КОДУ СИСТЕМЫ — ЗАЛИВКА В ПРЕЗЕНТАЦИИ ОБЫЧНАЯ")
    print("=" * 78)
    if promoted:
        print("  Серая заливка A6A6A6 есть только у входящих интеграций слайдов 3-4.")
        print("  Исходящие нарисованы как обычные шаги, поэтому тип выведен из кода системы.")
        for item in promoted:
            print(f"    · {item}")
    else:
        print("  повышений не было — все интеграции распознаны по заливке или тексту")

    print("\n" + "=" * 78)
    print("ИЗОЛИРОВАННЫЕ не-data УЗЛЫ — где в презентации связи нет")
    print("=" * 78)
    print("  Связи для них не достраиваются: в исходнике их действительно нет.")
    print("  Эти узлы нужно связать вручную или подтвердить, что связи быть не должно.")
    total_orphans = 0
    for stage in process_map["stages"]:
        orphans = isolated_nodes(stage)
        total_orphans += len(orphans)
        print(f"\n  этап {stage['number']} «{stage['shortTitle']}»: {len(orphans)}")
        for node in orphans:
            group = node.get("group")
            print(f"    · {node['id']}")
            print(
                f"        {node['type']:<11} «{node['label']}»"
                + (f"   [группа: {group}]" if group else "")
            )
    print(f"\n  всего изолированных не-data узлов: {total_orphans}")

    if questions:
        print("\n" + "=" * 78)
        print("ОТКРЫТЫЕ ВОПРОСЫ (нужны задачи -t question)")
        print("=" * 78)
        for item in questions:
            print(f"  ? {item}")


# --------------------------------------------------------------------------------------
# Перенос ручных полей из предыдущего process.json
# --------------------------------------------------------------------------------------


@dataclass
class CarryOverReport:
    """Что произошло с полями, которых в презентации нет."""

    had_previous: bool = False
    previous_nodes: int = 0
    transferred: list[str] = field(default_factory=list)
    cleared: list[str] = field(default_factory=list)
    invalid: list[str] = field(default_factory=list)
    lost: list[str] = field(default_factory=list)
    screens_transferred: int = 0
    screens_lost: int = 0


def is_screen_link(value: object) -> bool:
    """ScreenLink из schema.ts: ровно { title: string, url: string }."""
    return (
        isinstance(value, dict)
        and set(value) == {"title", "url"}
        and isinstance(value.get("title"), str)
        and isinstance(value.get("url"), str)
    )


def is_owner(value: object) -> bool:
    return isinstance(value, str)


FIELD_VALIDATORS = {"screen": is_screen_link, "owner": is_owner}


def reorder_keys(payload: dict, order: Sequence[str]) -> dict:
    """
    Пересобирает словарь в порядке ключей zod-схемы. Нужен, потому что перенос
    добавляет `owner`/`screen` уже после `position`, а порядок ключей влияет на
    байты файла (см. NODE_KEY_ORDER).
    """
    result = {key: payload[key] for key in order if key in payload}
    # Ключей вне схемы быть не должно; если появились — не теряем их молча.
    result.update({key: value for key, value in payload.items() if key not in result})
    return result


def load_previous_map(path: Path) -> dict | None:
    """
    Предыдущий process.json. Отсутствие файла — норма (первый запуск на чистом
    репозитории). А вот битый файл — НЕ норма: перезаписать его молча значит
    ровно то, ради чего эта функция написана, поэтому импорт останавливается.
    """
    if not path.exists():
        return None
    try:
        previous = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError) as error:
        raise SystemExit(
            f"Предыдущий {path} не читается ({error}). Импорт остановлен, чтобы не "
            f"затереть ручные ссылки на экраны: почините или удалите файл вручную."
        ) from error
    if not isinstance(previous, dict):
        raise SystemExit(f"Предыдущий {path} — не объект карты процесса. Импорт остановлен.")
    return previous


def index_previous(previous: dict) -> tuple[dict[str, dict], dict[str, dict]]:
    """id → узел и id → этап предыдущего документа."""
    nodes: dict[str, dict] = {}
    stages: dict[str, dict] = {}
    for stage in previous.get("stages") or []:
        if not isinstance(stage, dict):
            continue
        if isinstance(stage.get("id"), str):
            stages[stage["id"]] = stage
        for node in stage.get("nodes") or []:
            if isinstance(node, dict) and isinstance(node.get("id"), str):
                nodes[node["id"]] = node
    return nodes, stages


def carry_field(target: dict, source: dict, name: str, where: str, report: CarryOverReport) -> None:
    """
    Переносит одно поле. Три РАЗЛИЧИМЫХ состояния источника:

      · ключа нет           — поля никогда не было, переносить нечего, молчим;
      · значение null       — человек СОЗНАТЕЛЬНО удалил ссылку (SPEC §4.4,
                              кнопка «Удалить ссылку» пишет screen: null).
                              В сам JSON null не попадает: ProcessNodeSchema
                              объявляет screen как .optional(), а не .nullable(),
                              и «ссылки нет» кодируется отсутствием ключа.
                              Поэтому поле не переносим, но и не считаем потерей —
                              печатаем отдельной строкой, чтобы отличать от
                              «ссылки не было»;
      · значение есть       — переносим, если оно валидно по schema.ts.
    """
    if name not in source:
        return
    value = source[name]
    if value is None:
        report.cleared.append(f"{where}: {name} — было явно удалено (null), оставлено пустым")
        return
    if not FIELD_VALIDATORS[name](value):
        report.invalid.append(f"{where}: {name} = {value!r} — не проходит schema.ts, НЕ перенесено")
        return
    target[name] = value
    if name == "screen":
        report.screens_transferred += 1
        report.transferred.append(f"{where}: screen → «{value['title']}» {value['url']}")
    else:
        report.transferred.append(f"{where}: {name} → «{value}»")


def describe_lost(node: dict, field_name: str) -> str:
    value = node.get(field_name)
    if field_name == "screen" and isinstance(value, dict):
        return f"screen «{value.get('title')}» {value.get('url')}"
    return f"{field_name} «{value}»"


def carry_over_manual_fields(fresh: dict, previous: dict | None) -> CarryOverReport:
    """
    Переносит PRESERVED_* поля из предыдущего документа в свежесобранный.
    Сопоставление строго по `id` (узлы — глобально по документу, этапы — по
    stage.id): id стабильны по построению, а привязка по порядку обхода или по
    подписи развалилась бы при первой же правке презентации.

    Возвращает отчёт: что перенесено, что было явно очищено, что невалидно и
    что потеряно вместе с исчезнувшим узлом.
    """
    report = CarryOverReport()
    if previous is None:
        return report
    report.had_previous = True

    prev_nodes, prev_stages = index_previous(previous)
    report.previous_nodes = len(prev_nodes)

    fresh_node_ids: set[str] = set()
    fresh_labels: dict[str, list[str]] = {}
    for stage in fresh["stages"]:
        prev_stage = prev_stages.get(stage["id"])
        if prev_stage is not None:
            for name in PRESERVED_STAGE_FIELDS:
                carry_field(stage, prev_stage, name, f"этап «{stage['id']}»", report)
        for node in stage["nodes"]:
            fresh_node_ids.add(node["id"])
            fresh_labels.setdefault(node["label"], []).append(node["id"])
            prev_node = prev_nodes.get(node["id"])
            if prev_node is None:
                continue
            for name in PRESERVED_NODE_FIELDS:
                carry_field(node, prev_node, name, f"узел «{node['id']}»", report)

    # Узлы, которых в презентации больше нет. Молча потерять ссылку нельзя —
    # печатаем id, подпись и сам url, чтобы её можно было проставить заново,
    # и подсказываем узел с такой же подписью, если он появился под новым id.
    for node_id, prev_node in sorted(prev_nodes.items()):
        if node_id in fresh_node_ids:
            continue
        for name in PRESERVED_NODE_FIELDS:
            if prev_node.get(name) is None:
                continue
            if name == "screen":
                report.screens_lost += 1
            hint = ""
            twins = [i for i in fresh_labels.get(prev_node.get("label", ""), []) if i != node_id]
            if twins:
                hint = f"; возможно, это теперь {', '.join(twins)}"
            report.lost.append(
                f"узла «{node_id}» больше нет в презентации — потеряно "
                f"{describe_lost(prev_node, name)} (подпись: «{prev_node.get('label', '')}»){hint}"
            )

    for stage in fresh["stages"]:
        stage["nodes"] = [reorder_keys(node, NODE_KEY_ORDER) for node in stage["nodes"]]
    fresh["stages"] = [reorder_keys(stage, STAGE_KEY_ORDER) for stage in fresh["stages"]]
    return report


def print_carry_over(report: CarryOverReport, spec: MapSpec) -> None:
    print("\n" + "=" * 78)
    print("РУЧНЫЕ ПОЛЯ (ссылки на экраны, ответственные) — ПЕРЕНОС ИЗ ПРЕДЫДУЩЕГО JSON")
    print("=" * 78)
    if not report.had_previous:
        print(f"  предыдущего {spec.json.name} нет — первый запуск, переносить нечего")
        return
    print(f"  узлов в предыдущем файле: {report.previous_nodes}")
    print(f"  перенесено ссылок (screen): {report.screens_transferred}")
    print(f"  потеряно ссылок (screen):   {report.screens_lost}")
    if report.transferred:
        print(f"  перенесено полей ({len(report.transferred)}):")
        for item in report.transferred:
            print(f"    + {item}")
    else:
        print("  перенесённых полей нет")
    if report.cleared:
        print(f"  явно удалённые ранее ссылки ({len(report.cleared)}) — это НЕ потеря:")
        for item in report.cleared:
            print(f"    · {item}")
    if report.invalid:
        print(f"  НЕВАЛИДНЫЕ ЗНАЧЕНИЯ ({len(report.invalid)}):")
        for item in report.invalid:
            print(f"    ! {item}")
    if report.lost:
        print(f"  ПОТЕРЯННЫЕ РУЧНЫЕ ПОЛЯ ({len(report.lost)}) — проставить заново:")
        for item in report.lost:
            print(f"    ! {item}")
    else:
        print("  потерянных ручных полей нет")


def print_layout_required(process_map: dict, in_pipeline: bool) -> None:
    """
    Импорт — ПЕРВАЯ половина конвейера. Требование прогнать раскладку печатается
    последним блоком (его видно, даже если отчёт-сверку пролистали) и говорит,
    что именно сейчас лежит в файле, а не просто «не забудьте».

    `in_pipeline` — скрипт запущен из scripts/data.ts, раскладка стартует сразу
    после: пугать нечем, но сказать, что файл ещё сырой, всё равно надо.
    """
    nodes = sum(len(stage["nodes"]) for stage in process_map["stages"])
    without_slide = sum(
        1
        for stage in process_map["stages"]
        for node in stage["nodes"]
        if "slidePosition" not in node
    )
    print("\n" + "=" * 78)
    if in_pipeline:
        print("ШАГ 1 ИЗ 2 ГОТОВ — ДАЛЬШЕ РАСКЛАДКА (scripts/layout.ts, запускается сейчас)")
    else:
        print("КОНВЕЙЕР НЕ ЗАВЕРШЁН — ОБЯЗАТЕЛЬНО: npm run layout")
    print("=" * 78)
    print(f"  узлов: {nodes}; в position сейчас СЫРАЯ геометрия слайда — карточки")
    print("  на ней накладываются друг на друга и показывать её нельзя;")
    print("  пригодные координаты считает scripts/layout.ts (dagre).")
    print("  исходная геометрия сохранена в node.slidePosition, раскладка сидируется ею")
    if without_slide:
        print(f"  ВНИМАНИЕ: узлов без slidePosition: {without_slide} — это ошибка импортёра")
    if not in_pipeline:
        # Цепочка — та же, что в usage() и шапке файла: самопроверка — первый
        # шаг npm run data (решение владельца по process-map-ngw). Строка
        # печатается только вне конвейера, поэтому вывод npm run data от её
        # правки не меняется.
        print("\n  одной командой:   npm run data     (самопроверка → import-pptx.py → layout.ts)")
        print("  сторож в тестах:  tests/mapContract.test.ts сверяет координаты,")
        print("                    так что незавершённый конвейер делает npm run check красным")


# --------------------------------------------------------------------------------------
# Запись файлов
# --------------------------------------------------------------------------------------


def write_json(path: Path, payload: object) -> None:
    text = json.dumps(payload, ensure_ascii=False, indent=2) + "\n"
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8", newline="\n")


def check_unique_ids(process_map: dict) -> None:
    node_ids: set[str] = set()
    edge_ids: set[str] = set()
    for stage in process_map["stages"]:
        for node in stage["nodes"]:
            if node["id"] in node_ids:
                raise SystemExit(f"Неуникальный id узла: {node['id']}")
            node_ids.add(node["id"])
        for edge in stage["edges"]:
            if edge["id"] in edge_ids:
                raise SystemExit(f"Неуникальный id ребра: {edge['id']}")
            edge_ids.add(edge["id"])
    for edge in process_map["overviewEdges"]:
        if edge["id"] in edge_ids:
            raise SystemExit(f"Неуникальный id ребра: {edge['id']}")
        edge_ids.add(edge["id"])


def collect_required_node_ids(process_map: dict) -> list[str]:
    """
    SPEC §7: обязательный минимум — id ШАГОВ (step/warning/integration).
    data-узлы получаются дроблением текстбоксов-списков, их состав — эвристика,
    и фиксировать его тестом нельзя.
    """
    ids: list[str] = []
    for stage in process_map["stages"]:
        ids.extend(n["id"] for n in stage["nodes"] if n["type"] != "data")
    return ids


