def run_self_test() -> int:
    """
    Проверки переноса ручных полей и разбора слайда. Презентация не нужна:
    фикстуры (в том числе кусочки XML) собираются в памяти.
    """
    checks = 0

    def check(condition: bool, message: str) -> None:
        nonlocal checks
        checks += 1
        if not condition:
            raise SystemExit(f"САМОПРОВЕРКА ПРОВАЛЕНА: {message}")

    # 1. Контракт с serialize_node: импортёр не создаёт ручных полей.
    produced = serialize_node(NodeDraft(node_id="x", node_type="step", label="L", box=Box(0, 0, 1, 1)))
    check(
        set(produced) <= set(IMPORTER_NODE_FIELDS),
        f"serialize_node отдаёт ключи вне IMPORTER_NODE_FIELDS: {set(produced) - set(IMPORTER_NODE_FIELDS)}",
    )
    check(
        not (set(PRESERVED_NODE_FIELDS) & set(IMPORTER_NODE_FIELDS)),
        "PRESERVED_NODE_FIELDS пересекается с IMPORTER_NODE_FIELDS",
    )

    # 1b. Исходная геометрия слайда сохраняется отдельным полем и совпадает с
    # position В МОМЕНТ ИМПОРТА (дальше position перезапишет npm run layout).
    box = Box(2 * EMU_PER_PX, 3 * EMU_PER_PX, 10 * EMU_PER_PX, 10 * EMU_PER_PX)
    laid = serialize_node(NodeDraft(node_id="y", node_type="step", label="L", box=box))
    check("slidePosition" in laid, "serialize_node не пишет slidePosition")
    check(
        laid["slidePosition"] == {"x": 2, "y": 3},
        f"slidePosition не равен геометрии слайда: {laid['slidePosition']}",
    )
    check(laid["position"] == laid["slidePosition"], "position при импорте ≠ slidePosition")
    # Разные объекты: раскладка меняет position и не должна задеть slidePosition.
    laid["position"]["x"] = 999
    check(laid["slidePosition"]["x"] == 2, "position и slidePosition — один и тот же объект")

    # 1c. direction (задача process-map-24p): поле пишется у data-узлов и
    # только у них, и стоит на своём месте в NODE_KEY_ORDER.
    step_node = serialize_node(NodeDraft(node_id="s", node_type="step", label="L", box=Box(0, 0, 1, 1)))
    check("direction" not in step_node, "direction проставлен не-data узлу")
    for value in ("in", "out"):
        data_node = serialize_node(
            NodeDraft(node_id="d", node_type="data", label="L", box=Box(0, 0, 1, 1), direction=value)
        )
        check(data_node.get("direction") == value, f"direction={value} не записан")
        check(
            list(data_node) == [k for k in NODE_KEY_ORDER if k in data_node],
            f"порядок ключей data-узла нарушен: {list(data_node)}",
        )
    check("direction" in NODE_KEY_ORDER, "direction отсутствует в NODE_KEY_ORDER")
    check("direction" in IMPORTER_NODE_FIELDS, "direction не объявлен полем импортёра")

    # 1d. Рёбра по решению владельца процесса (задача process-map-7bz).
    def _stage_fixture() -> list[dict]:
        return [
            {
                "number": 3,
                "nodes": [{"id": "src"}, {"id": "a"}, {"id": "b"}],
                "edges": [{"id": "e-src--a", "source": "src", "target": "a", "kind": "process"}],
            }
        ]

    # Решение-фикстура передаётся параметром, а не подменой глобали. Подмена во
    # время прогона протекла бы в остальные проверки — в том числе в сверку
    # настоящих таблиц ниже, — стоит забыть её вернуть. А объявить фикстуру
    # вторым литералом верхнего уровня нельзя вовсе: тесты читают таблицы из
    # исходника (tests/helpers/importerSource.ts, без Python), ищут объявление
    # по имени в первой колонке и на двух объявлениях останавливаются — Python
    # взял бы последнее, разбор первое.
    fake_decisions = (
        {
            "task": "self-test",
            "stage": 3,
            "source": "src",
            "targets": ("a", "b"),
            "kind": "process",
            "why": "самопроверка",
        },
    )
    reports = [SlideReport(slide_no=n + 3) for n in range(4)]
    stages = _stage_fixture()
    apply_owner_decision_edges(stages, reports, fake_decisions)
    edge_ids = [e["id"] for e in stages[0]["edges"]]
    check(edge_ids == ["e-src--a", "e-src--b"], f"недостающее ребро не добавлено: {edge_ids}")
    check(len(reports[2].owner_edges) == 2, "в отчёт попали не все концы решения")
    check(
        any("уже есть в презентации" in item for item in reports[2].owner_edges),
        "совпавшее со слайдом ребро не отмечено как пришедшее из презентации",
    )
    check(
        any("ДОБАВЛЕНО" in item for item in reports[2].owner_edges),
        "добавленное ребро не отмечено как решение владельца",
    )

    # Повтор ничего не дублирует: id ребра — функция концов.
    apply_owner_decision_edges(stages, [SlideReport(slide_no=n + 3) for n in range(4)], fake_decisions)
    check(
        [e["id"] for e in stages[0]["edges"]] == edge_ids,
        "повторное применение решения продублировало рёбра",
    )

    # Исчезнувший узел — остановка импорта, а не тихий пропуск.
    broken = _stage_fixture()
    broken[0]["nodes"] = [{"id": "src"}, {"id": "a"}]
    try:
        apply_owner_decision_edges(
            broken, [SlideReport(slide_no=n + 3) for n in range(4)], fake_decisions
        )
    except SystemExit as error:
        check("b" in str(error), "в сообщении нет id пропавшего узла")
    else:
        check(False, "пропавший узел решения не остановил импорт")

    # Объявление верхнего уровня разбирается тем же способом, что и в vitest:
    # у каждого решения есть основание-задача и непустой список концов.
    for decision in OWNER_DECISION_EDGES:
        check(
            decision["task"].startswith("process-map-"),
            f"решение без задачи-основания: {decision['task']}",
        )
        check(bool(decision["targets"]), f"решение {decision['task']} без концов")

    # 1c. Входы со слайда обзора (STAGE_INPUT_ENRICHMENT, process-map-qjl).
    # Сама подстановка формулировок живёт в build_stage и проверяется реальным
    # импортом; здесь — сторожа: они обязаны ронять импорт, а не молчать.
    fake_enrichment = {
        "task": "self-test",
        "stage": 4,
        "sid": 999,
        "source": "самопроверка",
        "add": ("Новая строка",),
        "expand": (("Кратко", "Полностью"),),
        "why": "самопроверка",
    }

    def _input_column() -> list[NodeDraft]:
        return [
            NodeDraft(
                node_id="col-1",
                node_type="data",
                label="Уже есть",
                box=Box(0, 0, 100, 50),
                direction="in",
            )
        ]

    drafts = _input_column()
    enrich_report = SlideReport(slide_no=6)
    apply_input_enrichment(fake_enrichment, 6, drafts, {"Кратко"}, IdFactory({}), enrich_report)
    added = [d for d in drafts if d.label == "Новая строка"]
    check(len(added) == 1, "строка со слайда обзора не добавлена в колонку входов")
    check(added[0].direction == "in", "добавленная строка не помечена входом")
    check(added[0].node_type == "data", "добавленная строка не data-узел")
    check(
        added[0].box.top == drafts[0].box.bottom,
        "добавленная строка встала не под колонкой — раскладка сидируется slidePosition",
    )
    check(
        any("ДОБАВЛЕНО" in item for item in enrich_report.owner_inputs),
        "добавленная строка не отмечена в отчёте как пришедшая со слайда обзора",
    )

    # Переформулировка не нашла своей строки — остановка, а не тихий пропуск:
    # иначе правка презентации молча вернула бы короткую подпись.
    try:
        apply_input_enrichment(
            fake_enrichment, 6, _input_column(), set(), IdFactory({}), SlideReport(slide_no=6)
        )
    except SystemExit as error:
        check("Кратко" in str(error), "в сообщении нет ненайденной формулировки")
    else:
        check(False, "ненайденная переформулировка не остановила импорт")

    # Добавляемая строка уже есть в презентации — тоже остановка: обогащение
    # устарело, и дублировать узел нельзя.
    already = _input_column()
    already[0].label = "Новая строка"
    try:
        apply_input_enrichment(
            fake_enrichment, 6, already, {"Кратко"}, IdFactory({}), SlideReport(slide_no=6)
        )
    except SystemExit as error:
        check("Новая строка" in str(error), "в сообщении нет уже существующей строки")
    else:
        check(False, "дублирующая строка не остановила импорт")

    for entry in STAGE_INPUT_ENRICHMENT:
        check(
            entry["task"].startswith("process-map-"),
            f"обогащение без задачи-основания: {entry['task']}",
        )
        check(
            bool(entry["add"]) or bool(entry["expand"]),
            f"обогащение {entry['task']} ничего не меняет",
        )

    # 1e. Отбор решений владельца по карте (decisions_for, process-map-9mn.13) и
    #     объявление чтения по профилям (PROFILE_READS, process-map-9mn.25,
    #     9mn.14.1). Фикстуры — параметром tables, по той же причине, что у
    #     рёбер выше.
    fake_table = (
        {"map": "snp", "task": "self-test", "stage": 1, "why": "своя карта"},
        {"map": "mrp", "task": "self-test", "stage": 1, "why": "чужая карта"},
    )
    fake_tables = {"OWNER_DECISION_EDGES": fake_table}
    picked = decisions_for(MAPS["snp"], "OWNER_DECISION_EDGES", fake_tables)
    check(len(picked) == 1, f"decisions_for отдал {len(picked)} записей вместо одной")
    check(picked[0]["map"] == "snp", "decisions_for применил решение чужой карты")
    # СТОРОЖ ОБЪЯВЛЕНИЯ. До process-map-9mn.14.1 этот же вызов был ПОЛОЖИТЕЛЬНЫМ
    # случаем: decisions_for отдавала карте mrp её запись, хотя построитель
    # профиля single-slide таблиц не читает вовсе. Теперь чтение необъявленной
    # таблицы — остановка: код и PROFILE_READS не имеют права расходиться.
    try:
        leaked = decisions_for(MAPS["mrp"], "OWNER_DECISION_EDGES", fake_tables)
    except SystemExit as error:
        check(
            "single-slide" in str(error) and "OWNER_DECISION_EDGES" in str(error),
            f"в сообщении сторожа нет профиля или таблицы: {error}",
        )
    else:
        check(
            False,
            f"профиль single-slide прочитал необъявленную таблицу — decisions_for отдала "
            f"{len(leaked)} записей вместо остановки",
        )
    # three-tier объявил одну таблицу: её читает, соседнюю — нет.
    three_tier_spec = replace(MAPS["snp"], profile="three-tier")
    check(
        decisions_for(three_tier_spec, "OWNER_DECISION_EXTERNAL_IO", {"OWNER_DECISION_EXTERNAL_IO": fake_table})
        == (fake_table[0],),
        "профиль three-tier не прочитал объявленную таблицу OWNER_DECISION_EXTERNAL_IO",
    )
    try:
        decisions_for(three_tier_spec, "OWNER_DECISION_EDGES", fake_tables)
    except SystemExit as error:
        check("three-tier" in str(error), f"в сообщении сторожа нет профиля: {error}")
    else:
        check(False, "профиль three-tier прочитал необъявленную таблицу OWNER_DECISION_EDGES")
    # Опечатка в имени таблицы — остановка, а не пустой отбор.
    try:
        decisions_for(MAPS["snp"], "OWNER_DECISION_EDGE", fake_tables)
    except SystemExit as error:
        check("OWNER_DECISION_EDGE" in str(error), "в сообщении нет неизвестного имени таблицы")
    else:
        check(False, "неизвестное имя таблицы не остановило импорт")
    # Запись без ключа — остановка, а не тихое «применить везде».
    try:
        decisions_for(
            MAPS["snp"], "OWNER_DECISION_EDGES", {"OWNER_DECISION_EDGES": ({"task": "self-test", "stage": 1},)}
        )
    except SystemExit as error:
        check("map" in str(error), "в сообщении не назван пропущенный ключ map")
    else:
        check(False, "решение без ключа map не остановило импорт")
    # Опечатка в имени карты — тоже остановка: иначе решение не применится
    # никогда и ни к чему, а это самый тихий способ его потерять.
    try:
        decisions_for(
            MAPS["snp"],
            "OWNER_DECISION_EDGES",
            {"OWNER_DECISION_EDGES": ({"map": "snp-2", "task": "self-test", "stage": 1},)},
        )
    except SystemExit as error:
        check("snp-2" in str(error), "в сообщении нет неизвестного имени карты")
    else:
        check(False, "неизвестная карта в решении не остановила импорт")

    # unread_decisions на фикстуре: запись для карты, чей профиль таблицу не
    # читает, находится — и только она; прочитанная соседка списка не пачкает.
    stray_tables = {
        "OWNER_DECISION_EDGES": ({"map": "mrp", "task": "self-test-stray", "stage": 1},),
        "OWNER_DECISION_EXTERNAL_IO": ({"map": "snp", "task": "self-test-read", "stage": 1},),
    }
    stray = unread_decisions(stray_tables, MAPS, PROFILE_READS)
    check(
        len(stray) == 1 and "self-test-stray" in stray[0] and "single-slide" in stray[0],
        f"unread_decisions не нашла запись для профиля, который таблицу не читает: {stray}",
    )

    # Реестры. DECISION_TABLES под каждым именем держит ОДНОИМЁННУЮ константу:
    # перепутанная пара отдала бы построителю чужие решения под верным именем.
    for name, table in DECISION_TABLES.items():
        check(table is globals().get(name), f"DECISION_TABLES[{name!r}] — не константа {name}")
    # PROFILE_READS называет только существующие таблицы: опечатка в имени
    # означала бы «профиль ничего не читает» без единого сообщения.
    for profile, reads in PROFILE_READS.items():
        check(
            reads <= set(DECISION_TABLES),
            f"PROFILE_READS[{profile!r}] называет несуществующие таблицы: "
            f"{sorted(reads - set(DECISION_TABLES))}",
        )
    # Решение владельца (process-map-9mn.31, вариант (а) задачи 9mn.25) — дословно.
    # Четыре имени перечислены явно, а не через set(DECISION_TABLES), — по той же
    # причине, что и в самом PROFILE_READS: пятая таблица (скажем, только для
    # three-tier) не должна заставлять объявлять её прочитанной профилем, чей
    # код её не открывает. Сравнение со всем реестром требовало бы именно этой лжи.
    check(
        PROFILE_READS["overview+details"]
        == {
            "OWNER_DECISION_EDGES",
            "STAGE_INPUT_ENRICHMENT",
            "OWNER_DECISION_EXTERNAL_IO",
            "STAGE_GROUP_SPLIT",
        },
        "профиль overview+details обязан читать ровно четыре таблицы решений 9mn.31",
    )
    check(PROFILE_READS["single-slide"] == frozenset(), "профиль single-slide таблиц не читает")
    check(
        PROFILE_READS["three-tier"] == {"OWNER_DECISION_EXTERNAL_IO"},
        "профиль three-tier читает ровно OWNER_DECISION_EXTERNAL_IO",
    )

    # Настоящие таблицы. У каждой записи есть map, он из реестра MAPS и стоит
    # первым; проверка именно здесь, потому что сборка одной карты чужих записей
    # не читает и опечатку в них не заметит.
    for name, table in DECISION_TABLES.items():
        check(bool(table), f"таблица решений {name} пуста")
        for entry in table:
            check(entry.get("map") in MAPS, f"{name} ({entry.get('task')}): map не из MAPS")
            # map ПЕРВЫМ — правило, которое держит и разбор таблиц для тестов
            # (tests/helpers/importerSource.ts::toRecord): по первому ключу видно,
            # к какой карте относится решение, не дочитывая запись. Порядок
            # остальных ключей разбору безразличен.
            check(
                next(iter(entry)) == "map",
                f"{name} ({entry.get('task')}): ключ map обязан быть ПЕРВЫМ полем записи",
            )
    # И ни одна запись не объявлена для карты, чей профиль её таблицу не читает.
    # main() делает ту же проверку перед каждой сборкой; здесь — чтобы
    # самопроверка в CI краснела и без запуска импорта.
    unread_real = unread_decisions(DECISION_TABLES, MAPS, PROFILE_READS)
    check(not unread_real, f"решения владельца, которые никто не прочтёт: {unread_real}")

    # 1f. Заливка с модификаторами (read_fill_key, process-map-9mn.13).
    xml_ns = (
        'xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" '
        'xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main"'
    )

    def _sp(fill_xml: str):
        return etree.fromstring(f"<p:sp {xml_ns}><p:spPr>{fill_xml}</p:spPr></p:sp>")

    tx2_mods = _sp(
        '<a:solidFill><a:schemeClr val="tx2">'
        '<a:lumMod val="65000"/><a:lumOff val="35000"/><a:alpha val="76000"/>'
        "</a:schemeClr></a:solidFill>"
    )
    tx2_plain = _sp('<a:solidFill><a:schemeClr val="tx2"/></a:solidFill>')
    check(
        read_fill_key(tx2_mods) == "scheme:tx2|alpha76000+lumMod65000+lumOff35000",
        f"модификаторы не вошли в ключ заливки: {read_fill_key(tx2_mods)}",
    )
    check(read_fill_key(tx2_plain) == "scheme:tx2", "заливка без модификаторов изменилась")
    # Порядок модификаторов в XML — дело PowerPoint, ключ от него зависеть не может.
    shuffled = _sp(
        '<a:solidFill><a:schemeClr val="tx2">'
        '<a:alpha val="76000"/><a:lumOff val="35000"/><a:lumMod val="65000"/>'
        "</a:schemeClr></a:solidFill>"
    )
    check(
        read_fill_key(shuffled) == read_fill_key(tx2_mods),
        "порядок модификаторов в XML изменил ключ заливки",
    )
    # И ради чего всё затевалось: read_fill обе заливки отдаёт одинаковыми.
    check(
        read_fill(tx2_mods) == read_fill(tx2_plain) == "scheme:tx2",
        "read_fill перестал схлопывать модификаторы — соседняя функция потеряла смысл",
    )
    check(
        read_fill_key(_sp('<a:solidFill><a:srgbClr val="a6a6a6"/></a:solidFill>')) == "srgb:A6A6A6",
        "srgb-заливка в ключе не приведена к верхнему регистру",
    )
    check(read_fill_key(_sp("<a:noFill/>")) == "noFill", "noFill потерян в ключе заливки")

    # 1g. Преобразование координат группы (group_transform, process-map-9mn.13).
    def _grp(off, ext, ch_off, ch_ext, extra: str = "") -> etree._Element:
        return etree.fromstring(
            f"<p:grpSp {xml_ns}><p:grpSpPr><a:xfrm {extra}>"
            f'<a:off x="{off[0]}" y="{off[1]}"/><a:ext cx="{ext[0]}" cy="{ext[1]}"/>'
            f'<a:chOff x="{ch_off[0]}" y="{ch_off[1]}"/>'
            f'<a:chExt cx="{ch_ext[0]}" cy="{ch_ext[1]}"/>'
            f"</a:xfrm></p:grpSpPr></p:grpSp>"
        )

    # Тождество: так устроены все три группы слайда 9 колоды L2.
    identity = group_transform(_grp((100, 200), (1000, 500), (100, 200), (1000, 500)))
    check(identity == IDENTITY_TRANSFORM, f"тождественная группа дала {identity}")
    # Сдвиг и масштаб: так устроены группы слайда 3 той же колоды.
    moved = group_transform(_grp((1000, 2000), (2000, 1000), (500, 100), (1000, 500)))
    check(moved == (0.0, 1800.0, 2.0, 2.0), f"сдвиг+масштаб дал {moved}")
    check(
        transformed_box(moved, 500, 100, 1000, 500) == Box(1000, 2000, 2000, 1000),
        "рамка ребёнка не легла в рамку группы",
    )
    # Вложенность: преобразования перемножаются, а не заменяют друг друга.
    nested = compose_transform(moved, group_transform(_grp((0, 0), (200, 200), (0, 0), (100, 100))))
    check(nested == (0.0, 1800.0, 4.0, 4.0), f"вложенная группа дала {nested}")
    check(
        transformed_box(nested, 10, 10, 5, 5) == Box(40, 1840, 20, 20),
        "рамка из вложенной группы посчитана не по обоим преобразованиям",
    )
    # Тождественное преобразование не гоняет целые координаты через float.
    check(
        transformed_box(IDENTITY_TRANSFORM, 9114155, 4675271, 1566850, 784830)
        == Box(9114155, 4675271, 1566850, 784830),
        "координаты фигуры вне групп изменились — карты пересоберутся иначе",
    )
    # Поворот группы — остановка, а не тихий заход не туда.
    try:
        group_transform(_grp((0, 0), (100, 100), (0, 0), (100, 100), 'rot="2700000"'))
    except SystemExit as error:
        check("45" in str(error), f"в сообщении нет угла поворота: {error}")
    else:
        check(False, "повёрнутая группа не остановила импорт")
    # Полный оборот поворотом не является.
    check(
        group_transform(_grp((0, 0), (100, 100), (0, 0), (100, 100), 'rot="21600000"'))
        == IDENTITY_TRANSFORM,
        "поворот на 360° принят за поворот",
    )
    # Отражение — та же беда, что и поворот: зеркалить рамку ребёнка нечем.
    try:
        group_transform(_grp((0, 0), (100, 100), (0, 0), (100, 100), 'flipH="1"'))
    except SystemExit as error:
        check("flip" in str(error), f"в сообщении не назван flip: {error}")
    else:
        check(False, "отражённая группа не остановила импорт")

    # 1g². Заход внутрь групп (read_shapes, process-map-9mn.13).
    #
    #      ЗАЧЕМ ЗДЕСЬ, А НЕ ПРОГОНОМ ПРЕЗЕНТАЦИИ. Сторож остальной работы —
    #      побайтовое совпадение пересобранных карт, но именно ЭТО изменение он
    #      не проверяет и не может: групп нет ни в презентации SNP, ни на слайде
    #      8 презентации MRP, так что «заходить в группы» и «не заходить» дают
    #      для обеих карт один и тот же файл. Презентация, где группы есть, в
    #      реестре MAPS пока не объявлена. Без этой проверки заход не сторожит
    #      ничто, а стоит он девяти шагов из двенадцати на слайде 9 колоды L2.
    class _FakeShape:
        """Минимум API python-pptx, которым пользуется read_shapes."""

        def __init__(self, shape_id, shape_type, left, top, width, height, element, children=()):
            self.shape_id = shape_id
            self.shape_type = shape_type
            self.left, self.top, self.width, self.height = left, top, width, height
            self._element = element
            self.shapes = children
            self.has_text_frame = False

    leaf_element = _sp('<a:solidFill><a:schemeClr val="accent1"/></a:solidFill>')

    def _leaf(sid: int, left: int, top: int) -> _FakeShape:
        return _FakeShape(sid, MSO_SHAPE_TYPE.AUTO_SHAPE, left, top, 100, 50, leaf_element)

    # Группа со сдвигом и масштабом ×2 (устройство групп слайда 3 колоды L2),
    # внутри неё — вложенная группа-тождество (устройство групп слайда 9).
    inner = _FakeShape(
        200,
        MSO_SHAPE_TYPE.GROUP,
        0,
        0,
        0,
        0,
        _grp((500, 100), (1000, 500), (500, 100), (1000, 500)),
        [_leaf(3, 700, 300)],
    )
    outer = _FakeShape(
        100,
        MSO_SHAPE_TYPE.GROUP,
        0,
        0,
        0,
        0,
        _grp((1000, 2000), (2000, 1000), (500, 100), (1000, 500)),
        [_leaf(2, 600, 200), inner],
    )
    nested_shapes = read_shapes([_leaf(1, 10, 20), outer])
    by_sid = {s.sid: s for s in nested_shapes}
    check(
        sorted(by_sid) == [1, 2, 3],
        f"read_shapes отдал не все фигуры: {sorted(by_sid)} (фигуры из групп потеряны?)",
    )
    check(
        by_sid[1].box == Box(10, 20, 100, 50) and by_sid[1].inside_group is None,
        "фигура вне групп изменилась при заходе в группы",
    )
    # Ребёнок группы: (600 - 500)·2 + 1000 = 1200, (200 - 100)·2 + 2000 = 2200.
    check(
        by_sid[2].box == Box(1200, 2200, 200, 100),
        f"координаты фигуры из группы посчитаны неверно: {by_sid[2].box}",
    )
    check(by_sid[2].inside_group == 100, "фигура из группы не помнит своей группы")
    # Вложенная группа тождественна, значит преобразование то же самое.
    check(
        by_sid[3].box == Box(1400, 2400, 200, 100),
        f"координаты фигуры из вложенной группы посчитаны неверно: {by_sid[3].box}",
    )
    check(by_sid[3].inside_group == 200, "фигура помнит внешнюю группу вместо внутренней")
    # Сама группа фигурой не становится: её рамка служебная и попала бы в
    # геометрию контейнеров и подписей.
    check(100 not in by_sid and 200 not in by_sid, "группа попала в разбор отдельной фигурой")
    check(by_sid[2].fill_key == "scheme:accent1", "заливка фигуры из группы не прочитана")

    # 1h. Полоса фаз и ярусы (phase_band / split_tiers, process-map-9mn.13).
    def _tier_shape(sid: int, left: int, top: int, text: str, fill_key: str | None, kind: str = "auto") -> Shape:
        return Shape(
            sid=sid,
            kind=kind,
            box=Box(left, top, 1_000_000, 500_000),
            paragraphs=[text] if text else [],
            fill=None if fill_key is None else fill_key.split("|")[0],
            flip_h=False,
            flip_v=False,
            rot=0.0,
            head_arrow=False,
            tail_arrow=False,
            fill_key=fill_key,
        )

    # Слайд без контейнеров, устройство слайдов 3/5/7/11 колоды L2.
    # Заливки взяты оттуда же: фаза и шаг — tx2 С модификаторами, подробность —
    # тот же tx2 БЕЗ них. Это и есть коллизия, которую read_fill не разводит.
    phase_fill = "scheme:tx2|alpha76000+lumMod65000+lumOff35000"
    detail_fill = "scheme:tx2"
    # ВЕРТИКАЛЬНЫЕ КООРДИНАТЫ ЗДЕСЬ НЕ КРУГЛЫЕ И НЕ СЛУЧАЙНЫЕ: это ровно те два
    # замера с колоды L2, между которыми обязан лежать PHASE_ROW_TOLERANCE.
    #   · разброс внутри полосы = 20426 — максимальный разброс внутри ряда на
    #     слайдах 3/5/7/11 (слайд 7, ряд подробностей [54], [39], [40], [55]).
    #     Порог МЕНЬШЕ него разваливает этот ряд;
    #   · зазор между рядами = 210841 — минимальный зазор между соседними
    #     рядами там же (слайд 5, нижний шаг [38] под рядом подробностей).
    #     Порог НЕ МЕНЬШЕ него слепляет эти два ряда.
    # Фикстура с круглыми числами (разброс 10000, зазор 1000000) держала порог
    # слишком слабо с ОБЕИХ сторон: и 10500, и 600000 проходили самопроверку,
    # ломая при этом настоящую колоду — на слайде 5 полоса теряла фазу, на
    # слайде 11 разрасталась с 4 фигур до 11.
    row_spread = 20_426
    row_gap = 210_841
    band_top = 1_000_000 + row_gap
    top_row = [
        # Верхний ряд из ДВУХ фигур полосой фаз не является: такой ряд даёт
        # случайное совпадение верхов, и правило обязано его пропустить.
        _tier_shape(1, 0, 1_000_000, "шапка", "srgb:FFFFFF"),
        _tier_shape(2, 2_000_000, 1_000_000, "дата", "srgb:FFFFFF"),
        # Полоса фаз: три участника, разброс верхов ровно предельный.
        _tier_shape(3, 0, band_top, "Фаза 1", "srgb:AD27BA"),
        _tier_shape(4, 2_000_000, band_top + row_spread, "Фаза 2", phase_fill),
        _tier_shape(5, 4_000_000, band_top, "Фаза 3", "srgb:9000FF"),
        # Шаги: заливка своей фазы.
        _tier_shape(6, 0, band_top + row_gap, "Шаг 1", "srgb:AD27BA"),
        _tier_shape(7, 2_000_000, band_top + row_gap, "Шаг 2", phase_fill),
        # Подробности: tx2 без модификаторов, нарисованы ТЕКСТБОКСАМИ — так они
        # нарисованы на слайде 11.
        _tier_shape(8, 0, band_top + 2 * row_gap, "Подробность 1", detail_fill, kind="textbox"),
        _tier_shape(9, 2_000_000, band_top + 2 * row_gap, "Подробность 2", detail_fill, kind="textbox"),
        _tier_shape(10, 4_000_000, band_top + 2 * row_gap, "Подробность 3", detail_fill, kind="textbox"),
        # ШАГ НИЖЕ ЯРУСА ПОДРОБНОСТЕЙ — ровно то, на чём ломается правило «по y»
        # (так лежат [38] слайда 5, [38] слайда 7 и [55] слайда 11).
        _tier_shape(11, 0, band_top + 3 * row_gap, "Шаг 3", "srgb:AD27BA"),
        # Плашка легенды: ТА ЖЕ заливка, что у подробностей, но другой тип
        # фигуры. На слайде 11 так и есть — там совпадает noFill, здесь tx2,
        # чтобы обе беды слайда проверялись на одной фикстуре. Слей типы в один
        # ярус — и легенда станет пятой подробностью процесса.
        _tier_shape(12, 0, band_top + 4 * row_gap, "Легенда", detail_fill, kind="auto"),
        _tier_shape(
            13, 2_000_000, band_top + 4 * row_gap, "Подробность 4", detail_fill, kind="textbox"
        ),
        # Без явной заливки яруса нет вовсе: так выглядит номер слайда.
        _tier_shape(14, 6_000_000, band_top + 4 * row_gap, "11", None, kind="textbox"),
    ]
    # Порог зажат фикстурой с двух сторон — говорим это прямо, чтобы при
    # неудачной правке константы сообщение называло причину, а не последствие.
    check(
        row_spread <= PHASE_ROW_TOLERANCE < row_gap,
        f"PHASE_ROW_TOLERANCE={PHASE_ROW_TOLERANCE} вне отрезка "
        f"[{row_spread}, {row_gap}), замеренного по слайдам 3/5/7/11 колоды L2: "
        f"меньше нижней границы — ряд подробностей слайда 7 распадается, "
        f"не меньше верхней — нижний шаг [38] слайда 5 слипается с рядом над ним",
    )
    # group_rows меряет зазор от НАЧАЛА ряда, а не от предыдущей фигуры. Разница
    # не теоретическая: при отсчёте от предыдущей цепочка фигур, каждая из
    # которых близко к соседней, склеивается в ряд ЛЮБОЙ высоты — порог
    # перестаёт что-либо ограничивать, и полосой фаз может стать половина
    # слайда. На сегодняшней колоде обе версии дают одно и то же (ряды там
    # отстоят далеко), поэтому проверка своя, а не через слайды.
    chain = [
        _tier_shape(60, 0, 0, "a", "noFill"),
        _tier_shape(61, 0, PHASE_ROW_TOLERANCE - 1, "b", "noFill"),
        _tier_shape(62, 0, 2 * (PHASE_ROW_TOLERANCE - 1), "c", "noFill"),
    ]
    chained = [[s.sid for s in row] for row in group_rows(chain, PHASE_ROW_TOLERANCE)]
    check(chained == [[60, 61], [62]], f"group_rows склеил цепочку в один ряд: {chained}")

    band_report = SlideReport(slide_no=3)
    band = phase_band(top_row, band_report)
    check(band is not None, "полоса фаз не найдена на слайде без контейнеров")
    assert band is not None
    check(band.rule == "top-row", f"сработала не та ветка: {band.rule}")
    check(band_report.phase_band_rule == "top-row", "ветка не попала в отчёт")
    check(
        [s.sid for s in band.shapes] == [3, 4, 5],
        f"полосой фаз назван не тот ряд: {[s.sid for s in band.shapes]}",
    )
    check(band.labels == ("Фаза 1", "Фаза 2", "Фаза 3"), f"подписи фаз: {band.labels}")

    split = split_tiers(top_row, band)
    check(
        [s.sid for s in split.steps] == [6, 7, 11],
        f"шаги разобраны неверно: {[s.sid for s in split.steps]}",
    )
    check(
        [s.sid for s in split.details] == [8, 9, 10, 13],
        f"подробности разобраны неверно: {[s.sid for s in split.details]}",
    )
    # В «прочее» уходят шапка слайда (ряд из двух фигур над полосой фаз) и
    # плашка легенды. Выбросить их молча нельзя: пропавшая фигура — это ровно
    # тот дефект, ради которого затеян заход в группы.
    check(
        [s.sid for s in split.others] == [1, 2, 12],
        f"в «прочее» попало не то: {[s.sid for s in split.others]}",
    )
    # Фигура без явной заливки не попадает НИ В ОДИН ярус, включая «прочее»:
    # ярус определяется заливкой, а её у такой фигуры нет.
    sorted_out = {s.sid for s in split.steps + split.details + split.others + split.phases}
    check(14 not in sorted_out, "фигура без заливки получила ярус")
    # Та самая коллизия: по read_fill шаг [7] и подробность [8] неразличимы.
    step_seven = next(s for s in split.steps if s.sid == 7)
    detail_eight = next(s for s in split.details if s.sid == 8)
    check(
        step_seven.fill == detail_eight.fill == "scheme:tx2",
        "фикстура не воспроизводит коллизию tx2 — проверять нечего",
    )
    check(
        step_seven.fill_key != detail_eight.fill_key,
        "read_fill_key не развёл шаг и подробность одной базовой заливки",
    )

    # Слайд с контейнерами, устройство слайда 9 колоды L2: фаза это бесфонная
    # рамка, подпись к ней лежит отдельным текстбоксом сверху.
    def _container(sid: int, left: int, top: int) -> Shape:
        shape = _tier_shape(sid, left, top, "", "noFill")
        shape.box = Box(left, top, CONTAINER_MIN_WIDTH + 500_000, 800_000)
        shape.fill = "noFill"
        return shape

    #
    # ЧИСЛЕННОСТЬ ЯРУСОВ ПОВТОРЯЕТ СЛАЙД 9, а не взята удобной: там 12 шагов
    # (scheme:accent1) > 5 плашек-артефактов (scheme:accent3) > 4 подробности
    # (textbox без заливки). Важен именно этот порядок: артефактов меньше, чем
    # шагов, поэтому шаги разбираются верно и без фильтрации, но БОЛЬШЕ, чем
    # подробностей, — и стоит вызывающему забыть про is_artifact_box, как
    # подробности и артефакты меняются местами. Здесь те же неравенства на
    # меньших числах: 6 > 5 > 3.
    artifact_fill = "scheme:accent3"
    with_containers = [
        _container(20, 0, 2_000_000),
        _container(21, 4_000_000, 2_000_000),
        _tier_shape(22, 0, 1_500_000, "Расчет потребности", "noFill", kind="textbox"),
        _tier_shape(23, 4_000_000, 1_500_000, "Обработка ошибок", "noFill", kind="textbox"),
        *[
            _tier_shape(24 + n, 100_000 + n * 600_000, 2_100_000, f"Шаг {n + 1}", "scheme:accent1")
            for n in range(6)
        ],
        *[
            _tier_shape(
                30 + n, 100_000 + n * 600_000, 2_700_000, f"Артефакт {n + 1}", artifact_fill
            )
            for n in range(5)
        ],
        *[
            _tier_shape(
                35 + n,
                100_000 + n * 600_000,
                3_300_000,
                f"Подробность {n + 1}",
                "noFill",
                kind="textbox",
            )
            for n in range(3)
        ],
    ]
    container_report = SlideReport(slide_no=9)
    band2 = phase_band(with_containers, container_report)
    check(band2 is not None, "полоса фаз не найдена на слайде с контейнерами")
    assert band2 is not None
    check(band2.rule == "containers", f"сработала не та ветка: {band2.rule}")
    check(container_report.phase_band_rule == "containers", "ветка не попала в отчёт")
    check(
        band2.labels == ("Расчет потребности", "Обработка ошибок"),
        f"подписи фаз-контейнеров: {band2.labels}",
    )
    # phase_band НИЧЕГО не помечает во входных фигурах: по имени и докстроке она
    # только ищет. Пометка consumed_by пережила бы выход из функции и изменила
    # бы ответ find_title_for_container на следующем проходе по тем же фигурам —
    # а проход этот в профиле три яруса будет.
    check(
        all(s.consumed_by is None for s in with_containers),
        "phase_band пометила входные фигуры — правка чужого поля переживёт выход",
    )

    # Так, как профиль обязан звать split_tiers: плашки-артефакты отсеяны ДО.
    filtered = [s for s in with_containers if s.fill_key != artifact_fill]
    split2 = split_tiers(filtered, band2)
    check(
        [s.sid for s in split2.steps] == [24, 25, 26, 27, 28, 29],
        f"шаги внутри контейнеров разобраны неверно: {[s.sid for s in split2.steps]}",
    )
    check(
        [s.sid for s in split2.details] == [35, 36, 37],
        f"подробности при контейнерах разобраны неверно: {[s.sid for s in split2.details]}",
    )
    check(not split2.others, f"при отсеянных артефактах «прочего» быть не должно: {split2.others}")

    # А так — если вызывающий про is_artifact_box забыл. Проверка закрепляет
    # ИМЕННО ЭТОТ отказ, а не «как-нибудь да разберётся»: артефакты занимают
    # ярус подробностей, а настоящие подробности уезжают в others. Пока такого
    # вызывающего нет, но докстрока split_tiers обещает ровно это поведение, и
    # обещание обязано быть проверено, а не написано.
    unfiltered = split_tiers(with_containers, band2)
    check(
        [s.sid for s in unfiltered.steps] == [24, 25, 26, 27, 28, 29],
        f"шаги сбились от неотсеянных артефактов: {[s.sid for s in unfiltered.steps]}",
    )
    check(
        [s.sid for s in unfiltered.details] == [30, 31, 32, 33, 34],
        f"неотсеянные артефакты обязаны вытеснить подробности: "
        f"{[s.sid for s in unfiltered.details]}",
    )
    check(
        [s.sid for s in unfiltered.others] == [35, 36, 37],
        f"вытесненные подробности обязаны быть видны в others: "
        f"{[s.sid for s in unfiltered.others]}",
    )

    # Контейнер без подписи — остановка: безымянная фаза это дыра в карте.
    try:
        phase_band([_container(99, 0, 2_000_000)])
    except SystemExit as error:
        check("99" in str(error), "в сообщении нет id контейнера без подписи")
    else:
        check(False, "контейнер без подписи не остановил импорт")
    # Один текстбокс не подписывает две фазы: список подписей убывает по ходу
    # разбора. Раньше это держалось на пометке consumed_by — правке чужого поля,
    # которая переживала выход из функции.
    try:
        phase_band(
            [
                _container(50, 0, 2_000_000),
                _container(51, 200_000, 2_000_000),
                _tier_shape(52, 0, 1_500_000, "Единственная подпись", "noFill", kind="textbox"),
            ]
        )
    except SystemExit as error:
        check("51" in str(error), f"вторая фаза забрала чужую подпись: {error}")
    else:
        check(False, "две фазы поделили один текстбокс-подпись")

    # 2. Первый запуск: предыдущего файла нет.
    fresh = _fresh_fixture()
    empty = carry_over_manual_fields(fresh, None)
    check(not empty.had_previous and not empty.transferred and not empty.lost, "пустой перенос")
    check(fresh == _fresh_fixture(), "перенос без предыдущего файла изменил документ")

    # 3. Основной случай.
    fresh = _fresh_fixture()
    report = carry_over_manual_fields(fresh, _previous_fixture())
    nodes = {n["id"]: n for n in fresh["stages"][0]["nodes"]}

    check(
        nodes["kept"].get("screen") == {"title": "Экран плана", "url": "https://inplan.example/plan"},
        "screen не перенесён по совпадающему id",
    )
    check(nodes["kept"].get("owner") == "Планировщик спроса", "owner не перенесён")
    # 1 ссылка узла + 1 ссылка этапа (stage.screen считается тем же счётчиком).
    check(report.screens_transferred == 2, f"screens_transferred={report.screens_transferred}, ожидалось 2")

    # 4. null отличается от отсутствия ключа.
    check("screen" not in nodes["cleared"], "screen: null попал в JSON (схема его не примет)")
    check(len(report.cleared) == 1, f"явных удалений {len(report.cleared)}, ожидалось 1")
    check("cleared" in report.cleared[0], "явное удаление не названо поимённо")
    check(
        all("«never»" not in item for item in report.cleared + report.transferred + report.lost),
        "узел без ключа screen попал в отчёт — «не было» перепутано с «удалили»",
    )
    check("screen" not in nodes["never"], "узлу без ссылки ссылка приписана")

    # 5. Невалидное значение не переносится и не молчит.
    check("screen" not in nodes["bad"], "невалидный screen перенесён в JSON")
    check(len(report.invalid) == 1, f"невалидных {len(report.invalid)}, ожидалось 1")

    # 6. Исчезнувший узел: громкая потеря, url в отчёте, подсказка по подписи.
    check(report.screens_lost == 1, f"screens_lost={report.screens_lost}, ожидалось 1")
    check(len(report.lost) == 1, f"потерь {len(report.lost)}, ожидалось 1")
    check("https://inplan.example/old" in report.lost[0], "url потерянной ссылки не напечатан")
    check("renamed-2-9" in report.lost[0], "подсказка по совпадающей подписи не выдана")

    # 7. Этап.
    check(
        fresh["stages"][0].get("screen") == {"title": "Обзор этапа", "url": "https://inplan.example/stage-1"},
        "stage.screen не перенесён",
    )

    # 8. Порядок ключей — иначе экспорт из приложения перестанет совпадать побайтово.
    check(
        list(nodes["kept"]) == [k for k in NODE_KEY_ORDER if k in nodes["kept"]],
        f"порядок ключей узла нарушен: {list(nodes['kept'])}",
    )
    check(
        list(fresh["stages"][0]) == [k for k in STAGE_KEY_ORDER if k in fresh["stages"][0]],
        f"порядок ключей этапа нарушен: {list(fresh['stages'][0])}",
    )

    # 9. Идемпотентность: перенос из уже перенесённого документа ничего не меняет.
    again = json.loads(json.dumps(fresh, ensure_ascii=False))
    carry_over_manual_fields(again, json.loads(json.dumps(fresh, ensure_ascii=False)))
    check(
        json.dumps(again, ensure_ascii=False, indent=2) == json.dumps(fresh, ensure_ascii=False, indent=2),
        "повторный перенос изменил документ — идемпотентность нарушена",
    )

    # 10. Поворот коннектора (process-map-3wh.18). Геометрию разбора проверяет
    #     только эта самопроверка — vitest питоновского кода не исполняет: без
    #     доворота концы повёрнутой линии вычисляются по чужим координатам, и
    #     разбор выдаёт правдоподобное, но неверное ребро.
    def probe(rot: float, head: bool = False, tail: bool = True) -> Shape:
        return Shape(
            sid=1,
            kind="line",
            box=Box(1000, 2000, 400, 200),  # центр (1200, 2100)
            paragraphs=[],
            fill=None,
            flip_h=False,
            flip_v=False,
            rot=rot,
            head_arrow=head,
            tail_arrow=tail,
        )

    flat_start, flat_end = line_endpoints(probe(0))
    check(
        flat_start == (1000.0, 2000.0) and flat_end == (1400.0, 2200.0),
        f"без поворота концы должны быть углами bbox, получено {flat_start} {flat_end}",
    )

    # 90°: угол (левый верхний) уезжает вправо-вверх относительно центра.
    turned_start, turned_end = line_endpoints(probe(90))
    check(
        all(abs(a - b) < 0.5 for a, b in zip(turned_start, (1300.0, 1900.0))),
        f"поворот 90°: начало ожидалось (1300, 1900), получено {turned_start}",
    )
    check(
        all(abs(a - b) < 0.5 for a, b in zip(turned_end, (1100.0, 2300.0))),
        f"поворот 90°: конец ожидался (1100, 2300), получено {turned_end}",
    )
    check(
        turned_start != flat_start,
        "поворот не влияет на концы — доворот не применяется",
    )

    # Поворот на 360° эквивалентен отсутствию поворота.
    full_start, full_end = line_endpoints(probe(360))
    check(
        all(abs(a - b) < 0.5 for a, b in zip(full_start, flat_start))
        and all(abs(a - b) < 0.5 for a, b in zip(full_end, flat_end)),
        "поворот 360° изменил концы",
    )

    # Стрелка на начале по-прежнему разворачивает пару и после доворота.
    rev_start, rev_end = line_endpoints(probe(90, head=True, tail=False))
    check(
        rev_start == turned_end and rev_end == turned_start,
        "headEnd не разворачивает концы повёрнутой линии",
    )

    # 11. Диспетчер профилей (PROFILE_BUILDERS, process-map-9mn.14.1). Раньше в
    #     main() стояла тернарка, и любой профиль, кроме single-slide, молча
    #     уходил в build_process_map.
    expected_builders = {
        "overview+details": build_process_map,
        "single-slide": build_single_slide_map,
        "three-tier": build_three_tier_map,
    }
    check(
        set(PROFILE_BUILDERS) == set(expected_builders),
        f"профили PROFILE_BUILDERS: {sorted(PROFILE_BUILDERS)}, ожидались {sorted(expected_builders)}",
    )
    for profile, expected in expected_builders.items():
        got = builder_for(replace(MAPS["snp"], profile=profile))
        check(
            got is expected,
            f"профиль {profile} отдан построителю {getattr(got, '__name__', got)}, "
            f"а не {expected.__name__}",
        )
    try:
        builder_for(replace(MAPS["snp"], profile="bogus"))
    except SystemExit as error:
        check(
            "bogus" in str(error) and all(profile in str(error) for profile in PROFILE_BUILDERS),
            f"в сообщении о неизвестном профиле нет его имени или списка известных: {error}",
        )
    else:
        check(False, "неизвестный профиль не остановил импорт — ушёл в чужой построитель")
    # Два реестра профилей — одна и та же пара ключей: построитель без объявления
    # чтения уронил бы decisions_for, объявление без построителя мертво.
    check(
        set(PROFILE_BUILDERS) == set(PROFILE_READS),
        f"профили PROFILE_BUILDERS {sorted(PROFILE_BUILDERS)} и PROFILE_READS "
        f"{sorted(PROFILE_READS)} разошлись",
    )
    for spec in MAPS.values():
        check(
            spec.profile in PROFILE_BUILDERS,
            f"у карты {spec.key} профиль {spec.profile} без построителя",
        )
    # Заглушка three-tier останавливает импорт и называет подзадачу, которая её
    # заменит. Проверка уходит вместе с заглушкой в process-map-9mn.14.6.
    try:
        build_three_tier_map(None, replace(MAPS["snp"], key="inplan", profile="three-tier"))
    except SystemExit as error:
        check("14.6" in str(error), f"заглушка three-tier не называет подзадачу 14.6: {error}")
    else:
        check(False, "заглушка three-tier не остановила импорт")

    # 12. main() целиком: командная строка, сторожа до сборки, --dry-run.
    #
    #     main() гоняется на подставных реестрах (параметры maps/tables/builders
    #     и self_test), потому что проверяется ПОРЯДОК шагов — сторож стоит до
    #     сборки, запись идёт только без --dry-run, справка раньше самопроверки,
    #     — а по отдельным функциям он не виден.
    #     Вместо разбора презентации — построители-зонды: зонд бросает _Reached,
    #     и по нему видно, что main() дошла до сборки, куда не должна была. Зонд
    #     вызывается раньше первой записи файла, так что даже сломанный main()
    #     здесь ничего не пишет.
    class _Reached(Exception):
        """
        Зонд вызван: main() дошла до шага, до которого не должна была. args[0] —
        чей зонд: профиль построителя или "--self-test" (зонд самопроверки).
        """

    def _probe(profile: str) -> Builder:
        def build(collisions: dict[str, int] | None, spec: MapSpec):
            raise _Reached(profile)

        return build

    probes = {profile: _probe(profile) for profile in PROFILE_BUILDERS}

    def _self_test_probe() -> int:
        raise _Reached("--self-test")

    def _fixture_builder(collisions: dict[str, int] | None, spec: MapSpec):
        return _fresh_fixture(), [SlideReport(slide_no=1)], [], Counter()

    fixture_builders = {profile: _fixture_builder for profile in PROFILE_BUILDERS}

    def _run(argv: list[str], **registries) -> tuple[str, object]:
        """stdout прогона и исход: код возврата, SystemExit или _Reached."""
        out = io.StringIO()
        try:
            with redirect_stdout(out):
                code = main(argv, **registries)
        except (SystemExit, _Reached) as stop:
            return out.getvalue(), stop
        return out.getvalue(), code

    # Неизвестный флаг — остановка со списком известных (process-map-5o8). Прямо
    # на parse_args — и через main() с настоящим реестром карт: ровно так
    # `--help` когда-то пересобирал карту по умолчанию. Зонд вместо построителя:
    # сломанный разбор дошёл бы до него и выдал себя, ничего не записав.
    try:
        parse_args(["--bogus"])
    except SystemExit as error:
        check(
            "--bogus" in str(error) and all(arg.split()[0] in str(error) for arg in KNOWN_ARGS),
            f"в сообщении о неизвестном флаге нет его самого или списка известных: {error}",
        )
    else:
        check(False, "parse_args принял неизвестный флаг --bogus")
    _, outcome = _run(["--bogus"], builders=probes)
    check(
        isinstance(outcome, SystemExit) and "--bogus" in str(outcome),
        f"main() с неизвестным флагом не остановилась на разборе, а дошла до: {outcome!r}",
    )
    # Прочие формы той же ошибки. Позиционный аргумент — тоже неизвестный:
    # `import-pptx.py mrp` иначе молча собрал бы snp.
    for argv in (
        ["mrp"],
        ["--dryrun"],
        ["--map"],
        ["--map", "--dry-run"],
        ["--map", "snp", "--map", "mrp"],
        ["--self-test", "--map", "snp"],
        ["--self-test", "--dry-run"],
    ):
        try:
            parse_args(argv)
        except SystemExit:
            check(True, "")
        else:
            check(False, f"parse_args принял {argv}")
    parsed = parse_args(["--in-pipeline", "--map", "mrp", "--dry-run"])
    check(
        parsed == CliArgs(map_key="mrp", in_pipeline=True, dry_run=True),
        f"допустимые флаги разобраны неверно: {parsed}",
    )
    check(parse_args([]) == CliArgs(), "пустая командная строка — не карта по умолчанию")

    # --help печатает справку и ничего не пишет.
    help_out, outcome = _run(["--help"], builders=probes)
    check(outcome == 0, f"--help вернул не 0, а {outcome!r}")
    check(
        all(arg.split()[0] in help_out for arg in KNOWN_ARGS)
        and all(key in help_out for key in MAPS),
        "справка --help не перечисляет флаги или карты",
    )

    # --help побеждает ВСЁ, включая запрет смешивать --self-test с --map (см.
    # parse_args): справка ничего не пишет, и отказывать в ней из-за соседнего
    # флага незачем. Сначала — сам разбор...
    try:
        with_help = parse_args(["--self-test", "--map", "snp", "--help"])
    except SystemExit as error:
        check(False, f"--help не победил сочетание --self-test с --map: {error}")
    else:
        check(with_help.help, f"--help потерян в сочетании с --self-test и --map: {with_help}")
    # ...потом порядок в main(): при --self-test --help печатается справка, а
    # самопроверка не запускается. Вместо неё — зонд: настоящая run_self_test
    # при сломанном порядке вызвала бы здесь саму себя (см. main()).
    help_out, outcome = _run(["--self-test", "--help"], self_test=_self_test_probe)
    check(
        outcome == 0 and "Использование:" in help_out,
        f"--self-test --help не напечатал справку, а дошёл до: {outcome!r}",
    )
    # Контроль зонда: без --help main() отдаёт --self-test именно самопроверке.
    # Без него проверка выше была бы зелёной и при main(), которая
    # самопроверку не зовёт вовсе.
    _, outcome = _run(["--self-test"], self_test=_self_test_probe)
    check(
        isinstance(outcome, _Reached) and outcome.args == ("--self-test",),
        f"main() с --self-test не запустила самопроверку: {outcome!r}",
    )

    with tempfile.TemporaryDirectory() as tmp:
        # Карта-фикстура целиком во временном каталоге: презентации нет, файлы
        # карты и фикстуры пишутся (или не пишутся) туда же.
        tmp_root = Path(tmp)
        probe_spec = replace(
            MAPS["snp"],
            key="probe",
            pptx=tmp_root / "нет-такой.pptx",
            json=tmp_root / "probe" / "process.json",
            required_nodes=tmp_root / "probe" / "required-nodes.json",
        )
        probe_maps = {"probe": probe_spec}
        written = (probe_spec.json, probe_spec.required_nodes)

        # --help побеждает прочие флаги и не пишет, даже когда построитель
        # собрал бы документ без единой ошибки.
        _, outcome = _run(
            ["--map", "probe", "--help"], maps=probe_maps, tables={}, builders=fixture_builders
        )
        check(outcome == 0, f"--help вместе с --map вернул не 0, а {outcome!r}")
        check(not any(path.exists() for path in written), "--help записал файлы карты")

        # Неизвестный профиль — остановка со списком известных. Тернарка отдала
        # бы его разбору SNP, и тот упал бы уже на отсутствующей презентации —
        # с сообщением, в котором профиля нет.
        _, outcome = _run(
            ["--dry-run", "--map", "probe"],
            maps={"probe": replace(probe_spec, profile="bogus")},
            tables={},
            builders=PROFILE_BUILDERS,
        )
        check(
            isinstance(outcome, SystemExit)
            and "bogus" in str(outcome)
            and all(profile in str(outcome) for profile in PROFILE_BUILDERS),
            f"main() с неизвестным профилем не остановилась диспетчером: {outcome!r}",
        )

        # Каждый профиль main() отдаёт СВОЕМУ построителю — через builder_for, а
        # не тернаркой: подставные зонды видны только диспетчеру по реестру.
        for profile in PROFILE_BUILDERS:
            _, outcome = _run(
                ["--dry-run", "--map", "probe"],
                maps={"probe": replace(probe_spec, profile=profile)},
                tables={},
                builders=probes,
            )
            check(
                isinstance(outcome, _Reached) and outcome.args == (profile,),
                f"main() отдала профиль {profile} не его построителю: {outcome!r}",
            )

        # Непрочитанное решение останавливает main() ДО сборки (9mn.25): профиль
        # single-slide таблицу OWNER_DECISION_EDGES не читает, и зонд не должен
        # быть достигнут. Пропусти main() сторож — зонд выдаст её.
        _, outcome = _run(
            ["--dry-run", "--map", "probe"],
            maps={"probe": replace(probe_spec, profile="single-slide")},
            tables={
                "OWNER_DECISION_EDGES": (
                    {"map": "probe", "task": "self-test-unread", "stage": 1},
                )
            },
            builders=probes,
        )
        # Сообщение сверяется и по имени записи, и по словам ИМЕННО этого сторожа:
        # decision_map тоже бросает SystemExit с именем задачи (например, на
        # карте, которой нет в реестре), и проверка «имя записи в сообщении»
        # приняла бы чужую остановку за эту.
        def _unread_stop(outcome: object, task: str) -> bool:
            return (
                isinstance(outcome, SystemExit)
                and task in str(outcome)
                and "PROFILE_READS" in str(outcome)
                and "не применятся никогда" in str(outcome)
            )

        check(
            _unread_stop(outcome, "self-test-unread"),
            f"main() не остановилась на непрочитанном решении до сборки: {outcome!r}",
        )

        # Проверяются ВСЕ карты реестра, а не только собираемая (unread_decisions):
        # собирается probe (overview+details, таблицу читает), а непрочитанная
        # запись принадлежит соседней probe-other (single-slide). main(), сверяющая
        # только собираемую карту, дошла бы до зонда probe.
        _, outcome = _run(
            ["--dry-run", "--map", "probe"],
            maps={
                "probe": probe_spec,
                "probe-other": replace(probe_spec, key="probe-other", profile="single-slide"),
            },
            tables={
                "OWNER_DECISION_EDGES": (
                    {"map": "probe-other", "task": "self-test-unread-other", "stage": 1},
                )
            },
            builders=probes,
        )
        check(
            _unread_stop(outcome, "self-test-unread-other"),
            f"main() не заметила непрочитанное решение соседней карты: {outcome!r}",
        )

        # --dry-run: собирает и печатает отчёт, но не пишет ни карты, ни фикстуры.
        dry_out, outcome = _run(
            ["--dry-run", "--map", "probe"], maps=probe_maps, tables={}, builders=fixture_builders
        )
        check(outcome == 0, f"--dry-run вернул не 0, а {outcome!r}")
        check(not any(path.exists() for path in written), "--dry-run записал файлы карты")
        check("ОТЧЁТ-СВЕРКА" in dry_out, "--dry-run не напечатал отчёт")
        check("НИЧЕГО НЕ ЗАПИСАНО" in dry_out, "--dry-run не сказал, что ничего не записал")
        check("записано:" not in dry_out, "--dry-run отчитался о записи файлов")

        # Контроль: тот же прогон без --dry-run пишет оба файла. Без него проверка
        # выше была бы зелёной и при пути, по которому main() не пишет никогда.
        alone_out, outcome = _run(
            ["--map", "probe"], maps=probe_maps, tables={}, builders=fixture_builders
        )
        check(outcome == 0, f"обычный прогон на фикстуре вернул не 0, а {outcome!r}")
        check(all(path.exists() for path in written), "обычный прогон не записал файлы карты")
        check(
            json.loads(probe_spec.required_nodes.read_text(encoding="utf-8"))
            == collect_required_node_ids(_fresh_fixture()),
            "обычный прогон записал не ту фикстуру required-nodes",
        )

        # --in-pipeline доходит до финального блока (print_layout_required): вне
        # конвейера — требование прогнать раскладку, из scripts/data.ts — «шаг 1
        # из 2». Флаг ни на что больше не влияет, поэтому потерять его по дороге
        # от разбора до печати можно незаметно для всех прочих проверок: данные
        # те же, меняется только текст, который человек читает.
        check(
            "КОНВЕЙЕР НЕ ЗАВЕРШЁН" in alone_out and "ШАГ 1 ИЗ 2" not in alone_out,
            "прогон без --in-pipeline не потребовал раскладку",
        )
        pipeline_out, outcome = _run(
            ["--in-pipeline", "--map", "probe"], maps=probe_maps, tables={}, builders=fixture_builders
        )
        check(outcome == 0, f"прогон с --in-pipeline вернул не 0, а {outcome!r}")
        check(
            "ШАГ 1 ИЗ 2" in pipeline_out and "КОНВЕЙЕР НЕ ЗАВЕРШЁН" not in pipeline_out,
            "main() не донесла --in-pipeline до финального блока — конвейер пугает раскладкой, "
            "которую сам запускает следом",
        )

        # --dry-run не трогает и уже существующий файл: содержимое-маркер,
        # которого сборка не произвела бы, обязано пережить прогон побайтово.
        marker = b'{"stages": []}\n'
        probe_spec.json.write_bytes(marker)
        _run(["--dry-run", "--map", "probe"], maps=probe_maps, tables={}, builders=fixture_builders)
        check(probe_spec.json.read_bytes() == marker, "--dry-run перезаписал существующий файл карты")

    # 13. Роль слайда в отчёте (SlideReport.role, process-map-9mn.14.1): шапку
    #     обзора печатает роль, а не номер слайда 2.
    def _report_text(report: SlideReport) -> str:
        out = io.StringIO()
        with redirect_stdout(out):
            print_report(_fresh_fixture(), [report], [], MAPS["snp"])
        return out.getvalue()

    overview_text = _report_text(SlideReport(slide_no=5, role="overview"))
    check(
        "этапов (контейнеров)" in overview_text and "пропущенных фигур с текстом" not in overview_text,
        "слайд с ролью overview (не второй) напечатан как слайд детализации",
    )
    detail_text = _report_text(SlideReport(slide_no=2))
    check(
        "этапов (контейнеров)" not in detail_text and "пропущенных фигур с текстом: нет" in detail_text,
        "второй слайд с ролью detail напечатан как обзор — отчёт смотрит на номер, а не на роль",
    )
    try:
        SlideReport(slide_no=1, role="обзор")
    except ValueError:
        check(True, "")
    else:
        check(False, "SlideReport принял неизвестную роль слайда")

    # 14. Реестр модулей с навигационных слайдов (read_module_index,
    #     process-map-9mn.14.2). Презентация не нужна: слайды собраны из фигур.
    #
    #     Фикстура повторяет колоду L2 там, где на этом держится правило:
    #       · навигационные слайды 2/4/6/8/10 идут в порядке колоды DP, MEIO,
    #         SNP, MRP, PS — НЕ в порядке кнопок DP, MEIO, SNP, PS, MRP. Совпади
    #         порядки, нумерация по колоде была бы неотличима от нумерации по
    #         кнопкам;
    #       · кнопки стоят на замеренных абсциссах колоды, их текст — русское
    #         название модуля без кода;
    #       · заливка активной кнопки своя на каждом слайде и у разных модулей
    #         повторяется (DP и MRP — accent1), как в колоде: правило, опознающее
    #         модуль по заливке, на этой фикстуре ошибётся.
    #     И отступает от колоды там, где та слишком удобна:
    #       · фигуры перечислены НЕ слева направо, а кнопка MRP поднята на
    #         30000 EMU над соседями: порядок по Shape.sort_key (сперва верх)
    #         поставил бы её первой;
    #       · у русских названий в заголовках хвостовые \x0b и пробел, а у
    #         кнопки MEIO — мягкий перенос \x0b ПОСЕРЕДИНЕ, как бывает на узкой
    #         кнопке. В колоде всё это схлопывает ещё read_paragraphs, здесь —
    #         обязан сам разбор, иначе заголовки MEIO и PS не найдут своих
    #         кнопок. Перенос именно посередине: хвостовой у кнопки срезал бы
    #         уже Shape.text (strip), и нормализация кнопок осталась бы
    #         непроверенной;
    #       · на каждом навигационном слайде лежит автофигура БЕЗ текста —
    #         декоративная полоса под заголовком. В колоде L2 таких нет (зонд по
    #         слайдам 2/4/6/8/10), но в презентациях они обычны. Кнопка — это
    #         автофигура С ТЕКСТОМ: без фильтра has_text полоса стала бы кнопкой
    #         «» (или, как здесь, выше ряда, разорвала бы его), и исправная
    #         колода остановила бы импорт.
    inch = 914_400
    nav_top = 5 * inch

    def _nav_shape(
        sid: int, kind: str, left: int, top: int, paragraphs: Sequence[str], fill_key: str | None = None
    ) -> Shape:
        return Shape(
            sid=sid,
            kind=kind,
            box=Box(left, top, 2 * inch, 400_000),
            paragraphs=list(paragraphs),
            fill=None if fill_key is None else fill_key.split("|")[0],
            flip_h=False,
            flip_v=False,
            rot=0.0,
            head_arrow=False,
            tail_arrow=False,
            fill_key=fill_key,
        )

    # Ряд кнопок колоды: текст и левая кромка в дюймах, слева направо.
    button_row: tuple[tuple[str, float], ...] = (
        ("Планирование спроса ", 0.55),
        ("Мультиэшелонная\x0bоптимизация запасов", 2.66),
        ("Планирование сети поставок", 4.80),
        ("Производственное планирование и графикование", 6.84),
        ("Планирование потребности в материалах", 8.99),
    )
    # Слайд (0-based) → абзацы заголовка и заливка активной кнопки. Пустой
    # абзац между русским и английским названием — как на слайдах 2/4/6/8
    # колоды; пустой ХВОСТОВОЙ у SNP — чтобы код искался в последнем НЕПУСТОМ
    # абзаце, а не в последнем по счёту.
    nav_titles: dict[int, tuple[tuple[str, ...], str]] = {
        1: (("Планирование спроса", "", "Demand Planning (DP)"), "scheme:accent1"),
        3: (
            ("Мультиэшелонная оптимизация запасов\x0b", "Multi-Echelon Inventory Optimization (MEIO)"),
            "scheme:accent2",
        ),
        5: (("Планирование сети поставок", "Supply Network Planning (SNP)", " "), "scheme:accent3"),
        7: (
            ("Планирование потребности в материалах", "Material Requirement Planning (MRP)"),
            "scheme:accent1",
        ),
        9: (
            ("Производственное планирование и графикование ", "Production Scheduling (PS)"),
            "scheme:accent4",
        ),
    }

    def _nav_deck(
        titles: Mapping[int, tuple[tuple[str, ...], str]] | None = None,
        rows: Mapping[int, tuple[tuple[str, float], ...]] | None = None,
        extra: Mapping[int, Sequence[Shape]] | None = None,
    ) -> list[list[Shape]]:
        """Колода из 11 слайдов; titles/rows/extra подменяют отдельные навигационные слайды."""
        deck: list[list[Shape]] = [[] for _ in range(11)]
        deck[0] = [_nav_shape(2, "placeholder", 0, 0, ["Типовой процесс интегрированного планирования"])]
        for index, (paragraphs, active_fill) in {**nav_titles, **(titles or {})}.items():
            row = (rows or {}).get(index, button_row)
            buttons = [
                _nav_shape(
                    10 + position,
                    "auto",
                    round(left * inch),
                    # Кнопка MRP чуть выше соседей — см. шапку пункта.
                    nav_top - 30_000 if "материалах" in text else nav_top,
                    [text],
                    active_fill
                    if normalize_text(text) == normalize_text(paragraphs[0])
                    else "srgb:7F7F7F",
                )
                for position, (text, left) in enumerate(row)
            ]
            # Как в XML колоды: первая слева кнопка перечислена предпоследней.
            listed = buttons[1:4] + buttons[:1] + buttons[4:]
            title = _nav_shape(8, "textbox", round(0.49 * inch), round(3.09 * inch), paragraphs, "noFill")
            # Декоративная полоса без текста — см. шапку пункта.
            strip = _nav_shape(9, "auto", round(0.49 * inch), round(3.6 * inch), [], "scheme:accent1")
            deck[index] = [title, strip, *listed, *(extra or {}).get(index, ())]
        # Слайды детализации остаются пустыми списками: read_module_index их не
        # читает, а «за навигационным слайдом нет детализации» решает длина
        # колоды, а не пустота списка.
        return deck

    nav_spec = replace(
        MAPS["snp"], key="inplan-probe", profile="three-tier", slides=11, nav_slides=(1, 3, 5, 7, 9)
    )

    def _module_stop(slides: Sequence[Sequence[Shape]], spec: MapSpec = nav_spec) -> str | None:
        """Сообщение остановки read_module_index или None, если она не остановилась."""
        try:
            read_module_index(slides, spec, SlideReport(slide_no=2))
        except SystemExit as error:
            return str(error)
        return None

    nav_report = SlideReport(slide_no=2)
    try:
        modules = read_module_index(_nav_deck(), nav_spec, nav_report)
    except SystemExit as error:
        check(False, f"реестр модулей не прочитан с исправной колоды: {error}")
        raise  # недостижимо: check(False, …) уже остановил самопроверку
    # Порядок и номер — ПО КНОПКАМ (решение владельца 9mn.31, п. 2). Порядок
    # колоды дал бы здесь MRP четвёртым, а PS пятым.
    check(
        [module.code for module in modules] == ["DP", "MEIO", "SNP", "PS", "MRP"],
        f"реестр модулей не в порядке кнопок навигации: {[module.code for module in modules]}",
    )
    check(
        [(module.code, module.number) for module in modules]
        == [("DP", 1), ("MEIO", 2), ("SNP", 3), ("PS", 4), ("MRP", 5)],
        f"номер модуля — не место его кнопки в ряду: "
        f"{[(module.code, module.number) for module in modules]}",
    )
    check(
        [module.id for module in modules] == ["dp", "meio", "snp", "ps", "mrp"],
        f"id модулей: {[module.id for module in modules]}",
    )
    # id виден сериализации: реестр пойдёт в JSON (14.6), и модуль без id там
    # был бы потерей молча. Свойство asdict пропустил бы — см. ModuleRef.
    check(
        asdict(modules[0]).get("id") == "dp",
        f"asdict(ModuleRef) без id модуля: {asdict(modules[0])}",
    )
    # Название — ПЕРВЫЙ абзац заголовка, русский, и без хвостов \x0b и пробела.
    check(
        [module.title for module in modules]
        == [
            "Планирование спроса",
            "Мультиэшелонная оптимизация запасов",
            "Планирование сети поставок",
            "Производственное планирование и графикование",
            "Планирование потребности в материалах",
        ],
        f"названия модулей: {[module.title for module in modules]}",
    )
    check(
        [(module.nav_slide, module.detail_slide) for module in modules]
        == [(1, 2), (3, 4), (5, 6), (9, 10), (7, 8)],
        f"слайды модулей (навигация, детализация): "
        f"{[(module.nav_slide, module.detail_slide) for module in modules]}",
    )
    # Отчёт: порядок кнопок рядом с порядком колоды — и на печати тоже.
    check(
        "порядок кнопок навигации: DP, MEIO, SNP, PS, MRP" in nav_report.module_index
        and any(
            "DP, MEIO, SNP, MRP, PS — РАСХОДИТСЯ" in line for line in nav_report.module_index
        ),
        f"отчёт не показывает порядок колоды рядом с порядком кнопок: {nav_report.module_index}",
    )
    modules_text = _report_text(nav_report)
    check(
        "НОМЕР ПО КНОПКАМ НАВИГАЦИИ" in modules_text
        and all(line in modules_text for line in nav_report.module_index),
        "print_report не напечатал реестр модулей",
    )
    check(
        "НОМЕР ПО КНОПКАМ НАВИГАЦИИ" not in _report_text(SlideReport(slide_no=2)),
        "блок реестра модулей напечатан в отчёте, где навигацию не читали",
    )
    # nav_slides в MapSpec перечислены вразнобой — реестр и отчёт те же. Порядок
    # колоды — порядок слайдов в презентации, а не в записи MapSpec; без
    # сортировки эталоном рядов стал бы слайд 10, а в отчёт ушёл бы «порядок
    # колоды» PS, MRP, SNP, MEIO, DP, которого в колоде нет.
    unsorted_report = SlideReport(slide_no=2)
    unsorted_modules = read_module_index(
        _nav_deck(), replace(nav_spec, nav_slides=(9, 7, 5, 3, 1)), unsorted_report
    )
    check(
        unsorted_modules == modules and unsorted_report.module_index == nav_report.module_index,
        f"nav_slides не по порядку дали другой реестр или отчёт: {unsorted_report.module_index}",
    )

    # Кнопки разошлись между навигационными слайдами — остановка. Оба случая
    # другими сторожами НЕ ловятся: эталон — кнопки слайда 2, и с ним заголовки
    # сходятся один к одному. Без сверки рядов номер модуля тихо зависел бы от
    # того, какой слайд взят эталоном.
    #   · тот же набор, другой порядок: на слайде 4 PS и MRP поменялись местами;
    #   · другой текст: на слайде 10 кнопка SNP подписана, как на титуле колоды.
    swapped = (*button_row[:3], (button_row[4][0], 6.84), (button_row[3][0], 8.99))
    renamed = (
        *button_row[:2],
        ("Планирование сети поставок и производства", 4.80),
        *button_row[3:],
    )
    for rows, slide_no in (({3: swapped}, 4), ({9: renamed}, 10)):
        stop = _module_stop(_nav_deck(rows=rows))
        check(
            stop is not None and f"кнопки навигации на слайде {slide_no} не такие, как на слайде 2" in stop,
            f"кнопки слайда {slide_no} разошлись с кнопками слайда 2, а импорт не остановлен: {stop}",
        )

    # Заголовки и кнопки не взаимно однозначны — четыре формы одной беды,
    # по одной на каждую строку списка problems в read_module_index.
    #   · у заголовка нет кнопки (SNP назван, как на титуле колоды);
    stop = _module_stop(
        _nav_deck(
            titles={
                5: (
                    ("Планирование сети поставок и производства", "Supply Network Planning (SNP)"),
                    "scheme:accent3",
                )
            }
        )
    )
    check(
        stop is not None
        and "не взаимно однозначны" in stop
        and "«Планирование сети поставок и производства» (слайд 6) — кнопки с таким текстом нет"
        in stop,
        f"заголовок без кнопки не остановил импорт: {stop}",
    )
    #   · у кнопки нет навигационного слайда (модуль PS потерян из nav_slides);
    stop = _module_stop(_nav_deck(), replace(nav_spec, nav_slides=(1, 3, 5, 7)))
    check(
        stop is not None
        and "«Производственное планирование и графикование» — навигационного слайда" in stop,
        f"кнопка без навигационного слайда не остановила импорт: {stop}",
    )
    #   · двум слайдам одна кнопка (слайд MRP подписан, как PS, код свой).
    stop = _module_stop(
        _nav_deck(
            titles={
                7: (
                    ("Производственное планирование и графикование", "Material Requirement Planning (MRP)"),
                    "scheme:accent1",
                )
            }
        )
    )
    check(
        stop is not None
        and "«Производственное планирование и графикование» на 2 слайдах" in stop,
        f"одна кнопка на два навигационных слайда не остановила импорт: {stop}",
    )
    #   · одна кнопка дважды в ряду. Оба случая ловит ТОЛЬКО эта строка
    #     problems: у каждого заголовка кнопка есть, у каждой кнопки есть
    #     слайд, заголовки не повторяются, ряды на всех слайдах одинаковы.
    #     Промолчи она — номера поехали бы молча, ведь номер — это
    #     reference.index, то есть ПЕРВОЕ вхождение текста в ряду:
    #       - лишняя кнопка MRP вторым номером (ряд из шести): MRP стал бы 2-м,
    #         а MEIO, SNP, PS съехали бы на 3, 4, 5;
    #       - кнопка MEIO подписана, как DP, и MEIO нет в nav_slides: реестр
    #         вышел бы с дырой — DP 1, SNP 3, PS 4, MRP 5.
    extra_mrp = (button_row[0], (button_row[4][0], 1.6), *button_row[1:])
    meio_as_dp = (button_row[0], (button_row[0][0], 2.66), *button_row[2:])
    for rows, spec, button in (
        ({i: extra_mrp for i in nav_titles}, nav_spec, "Планирование потребности в материалах"),
        (
            {i: meio_as_dp for i in nav_titles},
            replace(nav_spec, nav_slides=(1, 5, 7, 9)),
            "Планирование спроса",
        ),
    ):
        stop = _module_stop(_nav_deck(rows=rows), spec)
        check(
            stop is not None and "не взаимно однозначны" in stop and f"«{button}» в ряду 2 раза" in stop,
            f"кнопка «{button}» дважды в ряду не остановила импорт: {stop}",
        )

    # Код повторяется, а заголовки и кнопки при этом сходятся: два модуля с
    # одним id.
    stop = _module_stop(
        _nav_deck(
            titles={3: (("Мультиэшелонная оптимизация запасов", "Demand Planning (DP)"), "scheme:accent2")}
        )
    )
    check(
        stop is not None and "код модуля повторяется: DP — слайды 2, 4" in stop,
        f"повтор кода модуля не остановил импорт: {stop}",
    )

    # Заголовок без кода, с не-кодом в скобках, с кодом не в конце абзаца; без
    # русского абзаца; два заголовка с кодом.
    #   · «(FP&A)» и «(Dp)» — скобки есть, но код модуля — только [A-Z][A-Z0-9]*:
    #     из него получается id, и «fp&a» идентификатором не годится;
    #   · «(DP) — обзор», «(DP) v2» — код не в КОНЦЕ последнего абзаца. Правило
    #     замера — абзац кончается кодом; скобки посреди фразы — это пояснение,
    #     а не подпись модуля, и принять их значило бы угадывать.
    for titles, extra, expected, what in (
        (
            {1: (("Планирование спроса", "Demand Planning"), "scheme:accent1")},
            {},
            "слайд 2: нет текстбокса",
            "заголовок без кода в скобках",
        ),
        *(
            (
                {1: (("Планирование спроса", last), "scheme:accent1")},
                {},
                "слайд 2: нет текстбокса",
                f"заголовок с последним абзацем «{last}»",
            )
            for last in (
                "Demand Planning (FP&A)",
                "Demand Planning (Dp)",
                "Demand Planning (DP) — обзор",
                "Demand Planning (DP) v2",
            )
        ),
        (
            {1: (("Demand Planning (DP)",), "scheme:accent1")},
            {},
            "слайд 2: у заголовка модуля [8]",
            "заголовок из одного абзаца с кодом",
        ),
        (
            {},
            {1: [_nav_shape(40, "textbox", 0, 0, ["Сноска", "см. Demand Planning (DP)"])]},
            "слайд 2: несколько текстбоксов с кодом",
            "второй текстбокс с кодом",
        ),
    ):
        stop = _module_stop(_nav_deck(titles=titles, extra=extra))
        check(stop is not None and expected in stop, f"{what} не остановил импорт: {stop}")

    # Лишняя автофигура с текстом выше ряда — не шестая кнопка, а остановка.
    stop = _module_stop(_nav_deck(extra={5: [_nav_shape(41, "auto", 0, inch, ["Шапка"])]}))
    check(
        stop is not None and "слайд 6: кнопки навигации не лежат одним рядом" in stop,
        f"автофигура вне ряда кнопок не остановила импорт: {stop}",
    )

    # Кнопок нет вовсе (на слайде 6 остались заголовок и полоса без текста) —
    # остановка с объяснением, а не ValueError из max() по пустому ряду.
    stop = _module_stop(_nav_deck(rows={5: ()}))
    check(
        stop is not None and "слайд 6: кнопок навигации нет" in stop,
        f"навигационный слайд без кнопок не остановил импорт: {stop}",
    )

    # Устройство nav_slides: пусто; слайд повторён; за последним слайдом колоды
    # детализации нет; слайд детализации сам навигационный.
    for nav_slides, expected in (
        ((), "nav_slides пуст"),
        ((1, 1, 3, 5, 7, 9), "в MapSpec.nav_slides повторяются слайды"),
        ((1, 3, 5, 7, 10), "за навигационным слайдом 11 нет слайда детализации"),
        ((1, 2, 5, 7, 9), "слайд детализации 3 модуля со слайда 2 сам объявлен навигационным"),
    ):
        stop = _module_stop(_nav_deck(), replace(nav_spec, nav_slides=nav_slides))
        check(
            stop is not None and expected in stop,
            f"nav_slides={nav_slides} не остановил импорт: {stop}",
        )

    # 15. Слайд 1 трёхуровневой карты (read_modules_slide и соседи,
    #     process-map-9mn.14.3). Фигуры — слайд 1 колоды L2 с ЗАМЕРЕННЫМИ
    #     координатами в EMU, а не круглыми: на них держатся и допуск ряда
    #     (разброс верхов 66751, до ряда DRP/TLB 520222), и перекрытия плашек с
    #     колонками (не меньше 437320 EMU внутри, не меньше 1026606 до чужой).
    #     Реестр — тот, что read_module_index прочитал в пункте 14 с
    #     навигационной фикстуры: названия с навигационных слайдов, а не со
    #     слайда 1, и потому SNP опознаётся только по префиксу.
    #
    #     Отступления от колоды — там, где она слишком удобна:
    #       · значок цикла [46] (автофигура без текста) поставлен ровно на верх
    #         ряда. В колоде он на 171429 EMU ниже и в ряд не попал бы и так;
    #         здесь без фильтра has_text он стал бы колонкой между TPM и DP;
    #       · списки действий укорочены: сверке нужны совпадение, расхождение,
    #         регистр и ё/е, а не все 33 строки колоды.
    def _s1(
        sid: int,
        kind: str,
        box: tuple[int, int, int, int],
        paragraphs: Sequence[str] = (),
        fill_key: str | None = None,
        *,
        tail: bool = False,
        head: bool = False,
        flip_h: bool = False,
    ) -> Shape:
        return Shape(
            sid=sid,
            kind=kind,
            box=Box(*box),
            paragraphs=list(paragraphs),
            fill=None if fill_key is None else fill_key.split("|")[0],
            flip_h=flip_h,
            flip_v=False,
            rot=0.0,
            head_arrow=head,
            tail_arrow=tail,
            fill_key=fill_key,
        )

    row_top = 1_589_441
    plate_fill = "scheme:tx1"

    def _slide1(
        replaced: Mapping[int, Shape] | None = None, extra: Sequence[Shape] = ()
    ) -> list[Shape]:
        """Слайд 1 колоды L2; replaced подменяет фигуры по sid, extra добавляет свои."""
        shapes = [
            _s1(2, "placeholder", (263_524, 269_812, 11_668_215, 350_298), ["Типовой процесс"]),
            # Плашки-передачи над рядом: текстбоксы с заливкой scheme:tx1.
            _s1(
                42, "textbox", (135_699, 977_218, 1_451_441, 261_610), ["История промо"], plate_fill
            ),
            _s1(
                37,
                "textbox",
                (1_753_814, 884_886, 1_451_441, 430_887),
                ["История продаж и план промо"],
                plate_fill,
            ),
            _s1(
                21,
                "textbox",
                (3_916_680, 848_469, 1_451_442, 577_081),
                ["Итоговый неограниченный прогноз"],
                plate_fill,
            ),
            _s1(
                22,
                "textbox",
                (6_052_691, 925_127, 1_451_442, 430_887),
                ["Страховые и целевые запасы"],
                plate_fill,
            ),
            _s1(
                36,
                "textbox",
                (8_214_221, 885_700, 1_400_893, 577_081),
                ["Итоговый ограниченный прогноз"],
                plate_fill,
            ),
            _s1(
                32,
                "textbox",
                (10_435_079, 918_185, 1_325_252, 430_887),
                ["Детальный план операций"],
                plate_fill,
            ),
            # Линии между плашками: горизонтальные, стрелка на конце, без привязок.
            _s1(43, "line", (1_417_945, 1_115_718, 386_184, 0), tail=True),
            _s1(25, "line", (3_296_920, 1_115_718, 619_760, 0), tail=True),
            _s1(27, "line", (5_368_122, 1_137_009, 682_158, 0), tail=True),
            _s1(29, "line", (7_081_971, 1_115_718, 1_232_775, 0), tail=True),
            _s1(31, "line", (9_483_628, 1_137_009, 1_038_068, 0), tail=True),
            # Ряд шевронов. У DP заливки нет, как в колоде (цвет из темы), а
            # абзацы с хвостовыми пробелами — нормализовать обязан сам разбор.
            _s1(
                41,
                "auto",
                (368_409, row_top, 2_330_154, 1_080_000),
                ["Планирование промо", "Trade Promotion Management", "(TPM)"],
                "scheme:accent4",
            ),
            _s1(
                33,
                "auto",
                (2_613_746, row_top, 2_282_804, 1_080_000),
                ["Планирование спроса ", "Demand Planning ", "(DP)"],
            ),
            _s1(
                23,
                "auto",
                (4_811_733, row_top, 2_319_892, 1_080_000),
                [
                    "Мультиэшелонная оптимизация запасов",
                    "Multi-Echelon Inventory Optimization",
                    "(MEIO)",
                ],
                "scheme:accent2",
            ),
            _s1(
                24,
                "auto",
                (7_046_808, row_top, 2_215_803, 1_080_000),
                ["Планирование сети поставок и производства", "Supply Network Planning", "(SNP)"],
                "scheme:accent3",
            ),
            _s1(
                34,
                "auto",
                (9_177_794, row_top, 2_260_671, 1_080_000),
                ["Производственное планирование и графикование", "Production Scheduling", "(PS)"],
                "scheme:accent4",
            ),
            _s1(
                35, "auto", (11_322_686, row_top + 66_751, 796_162, 343_390), ["MRP"], "srgb:0070C0"
            ),
            # Значок цикла — см. шапку пункта.
            _s1(46, "auto", (2_412_418, row_top, 623_246, 761_545), [], "scheme:accent4"),
            # DRP/TLB — шеврон с текстом прямо под MRP, следующим рядом.
            _s1(
                38,
                "auto",
                (11_322_687, row_top + 520_222, 796_162, 511_192),
                ["DRP", "TLB"],
                "srgb:0070C0",
            ),
            # Списки действий под рядом: текстбоксы без заливки.
            _s1(
                40,
                "textbox",
                (283_592, 2_808_658, 2_330_154, 2_554_545),
                ["Формирование промо-планов по клиенту"],
                "noFill",
            ),
            _s1(
                19,
                "textbox",
                (2_559_989, 2_808_658, 2_064_262, 2_092_881),
                ["Ведение новинки", "Сегментация", "Передача неограниченного прогноза"],
                "noFill",
            ),
            _s1(
                39,
                "textbox",
                (4_631_515, 2_808_658, 2_064_262, 2_400_657),
                ["Расчёт рекомендаций по уровням запасов"],
                "noFill",
            ),
            _s1(
                28,
                "textbox",
                (6_861_178, 2_808_658, 2_401_433, 3_508_653),
                ["Supply Review Meeting"],
                "noFill",
            ),
            _s1(
                30,
                "textbox",
                (9_141_509, 2_808_658, 2_401_433, 2_331_407),
                ["Разузлование потребности"],
                "noFill",
            ),
            # Полоса FP&A во всю ширину.
            _s1(
                44,
                "auto",
                (1_040_022, 6_067_093, 10_527_527, 500_435),
                ["Финансовое планирование и анализ", "Financial Planning and Analysis (FP&A)"],
                "srgb:00B050",
            ),
            _s1(26, "placeholder", (11_438_465, 6_419_690, 493_275, 177_960), ["1"]),
        ]
        shapes = [(replaced or {}).get(s.sid, s) for s in shapes] + list(extra)
        return sorted(shapes, key=Shape.sort_key)

    def _slide1_stop(
        shapes: Sequence[Shape], registry: Sequence[ModuleRef] = modules
    ) -> str | None:
        """Сообщение остановки read_modules_slide или None, если она не остановилась."""
        try:
            read_modules_slide(shapes, registry, SlideReport(slide_no=1))
        except SystemExit as error:
            return str(error)
        return None

    # Допуск ряда зажат и замерами слайда 1: MRP [35] ниже соседей на 66751,
    # DRP/TLB [38] — на 520222. Сообщение называет причину, а не последствие.
    check(
        66_751 <= PHASE_ROW_TOLERANCE < 520_222,
        f"PHASE_ROW_TOLERANCE={PHASE_ROW_TOLERANCE} вне отрезка [66751, 520222), замеренного "
        f"на слайде 1 колоды L2: меньше нижней границы — MRP [35] выпадает из ряда модулей, "
        f"не меньше верхней — DRP/TLB [38] слипается с рядом и становится колонкой",
    )
    dp_fixture = next(s for s in _slide1() if s.sid == 33)
    check(
        dp_fixture.fill is None and dp_fixture.fill_key is None,
        "фикстура: у DP [33] не должно быть заливки, как в колоде — иначе проверять нечего",
    )

    s1_report = SlideReport(slide_no=1)
    # Фигуры — в переменной, а не прямо в вызове: ниже проверяется, что
    # передачи и полосы держат КОПИИ их коробок, а не сами коробки.
    slide1_shapes = _slide1()
    try:
        slide1 = read_modules_slide(slide1_shapes, modules, s1_report)
    except SystemExit as error:
        check(False, f"слайд 1 не прочитан с исправной фикстуры: {error}")
        raise  # недостижимо: check(False, …) уже остановил самопроверку

    # Колонки: TPM — колонка вне реестра; DP без заливки опознан; SNP — ТОЛЬКО
    # по префиксу (с кодом «(SNP)» в коробке, как в колоде: без префиксного
    # правила он прошёл бы по коду, и здесь это видно по имени правила); MRP —
    # по коду; DRP/TLB и значок цикла колонками не стали.
    check(
        [(c.sid, c.name, c.module, c.rule) for c in slide1.row.columns]
        == [
            (41, "TPM", None, None),
            (33, "DP", "dp", "exact"),
            (23, "MEIO", "meio", "exact"),
            (24, "SNP", "snp", "prefix"),
            (34, "PS", "ps", "exact"),
            (35, "MRP", "mrp", "code"),
        ],
        f"колонки ряда модулей: {[(c.sid, c.name, c.module, c.rule) for c in slide1.row.columns]}",
    )
    check(
        slide1.row.module_ranges()
        == {
            "dp": (2_613_746, 4_896_550),
            "meio": (4_811_733, 7_131_625),
            "snp": (7_046_808, 9_262_611),
            "ps": (9_177_794, 11_438_465),
            "mrp": (11_322_686, 12_118_848),
        },
        f"полосы модулей по x: {slide1.row.module_ranges()}",
    )
    # Границы ряда по вертикали — то, по чему построитель и сам разбор отделяют
    # «над рядом» (плашки) от «под рядом» (списки, полосы). Верх — САМЫЙ ВЫСОКИЙ
    # верх в ряду (MRP [35] ниже соседей на 66751 — верх ряда не его), низ —
    # САМЫЙ НИЗКИЙ низ (MRP короче соседей — низ ряда тоже не его). На колоде
    # перепутанные min/max колонок, передач и полос не меняют, поэтому границы
    # проверяются сами, и в отчёте тоже: человек сверяет их в PowerPoint.
    check(
        (slide1.row.top, slide1.row.bottom) == (row_top, row_top + 1_080_000),
        f"границы ряда модулей по y: {slide1.row.top}–{slide1.row.bottom}, ждали "
        f"{row_top}–{row_top + 1_080_000}",
    )
    check(
        any(
            "верх 1.74in — коробок 6, опознано модулей 5 — РЯД МОДУЛЕЙ" in line
            for line in s1_report.module_columns
        ),
        f"отчёт о ряде модулей не называет его верх 1.74in: {s1_report.module_columns}",
    )
    # Передачи: источник — левая колонка. [37] над TPM и DP — ТОЛЬКО вход DP;
    # [32] над PS и MRP, хотя под MRP ниже лежит DRP/TLB; [42] над одним TPM не
    # импортируется.
    check(
        [(t.sid, t.source, t.target, t.label) for t in slide1.transfers]
        == [
            (37, None, "dp", "История продаж и план промо"),
            (21, "dp", "meio", "Итоговый неограниченный прогноз"),
            (22, "meio", "snp", "Страховые и целевые запасы"),
            (36, "snp", "ps", "Итоговый ограниченный прогноз"),
            (32, "ps", "mrp", "Детальный план операций"),
        ],
        f"передачи слайда 1: {[(t.sid, t.source, t.target, t.label) for t in slide1.transfers]}",
    )
    check(
        slide1.transfers[0].box == Box(1_753_814, 884_886, 1_451_441, 430_887),
        f"коробка передачи — не коробка плашки на слайде 1: {slide1.transfers[0].box}",
    )
    # Коробки передач и полос — копии: у фигуры и у результата не один Box на
    # двоих. И результат хешируется — frozen-классы обязаны, а Box сам по себе
    # не хешируется (см. ModuleTransfer.box). hash(ModulesSlide) задевает всё
    # сразу: ряд, передачи, полосы.
    shape_boxes = {id(s.box) for s in slide1_shapes}
    check(
        not any(id(t.box) in shape_boxes for t in slide1.transfers)
        and not any(id(lane.box) in shape_boxes for lane in slide1.lanes),
        "передача или полоса держит коробку фигуры, а не её копию",
    )
    try:
        hash(slide1)
    except TypeError as error:
        check(False, f"результат слайда 1 не хешируется: {error}")
    check(
        "слайд 1: [42] «История промо» — над одной колонкой TPM: передачи между двумя модулями "
        "нет, не импортируется" in s1_report.module_transfers,
        f"пропуск [42] не попал в отчёт: {s1_report.module_transfers}",
    )
    check(
        any(
            "[37] «История продаж и план промо»: TPM → DP — TPM вне реестра: только вход DP" in line
            for line in s1_report.module_transfers
        ),
        f"вход DP от колонки вне реестра не описан в отчёте: {s1_report.module_transfers}",
    )
    check(
        any(
            "линий со стрелкой 5, все ведут слева направо" in line
            for line in s1_report.module_transfers
        ),
        f"сторож стрелок не отчитался: {s1_report.module_transfers}",
    )
    check(
        [(lane.id, lane.title, lane.code, lane.sid) for lane in slide1.lanes]
        == [("fpa", "FP&A · Финансовое планирование и анализ", "FP&A", 44)],
        f"полосы слайда 1: {[(lane.id, lane.title, lane.sid) for lane in slide1.lanes]}",
    )
    # Неопознанное — ровно DRP/TLB, и оно на виду. Плейсхолдеры (заголовок,
    # номер страницы) и списки действий пропуском не считаются.
    check(
        len(s1_report.text_skipped) == 1 and "[38] «DRP TLB»" in s1_report.text_skipped[0],
        f"пропущенные фигуры слайда 1: {s1_report.text_skipped}",
    )
    columns_text = "\n".join(s1_report.module_columns)
    check(
        "модуль snp по правилу 'prefix'" in columns_text
        and "опознано модулей 5 — РЯД МОДУЛЕЙ" in columns_text
        and "совпадает с номерами модулей" in columns_text,
        f"отчёт о колонках не называет правило, ряд или порядок: {s1_report.module_columns}",
    )
    # Ряд модулей — тот, где опознано больше всего, а не верхний; плашка — с
    # заливкой, а не любой текстбокс над рядом, и ЦЕЛИКОМ ВЫШЕ ряда, а не любой
    # текстбокс с заливкой. На колоде эти правила совпадают с более простыми
    # (верхний ряд автофигур с текстом и есть ряд модулей, текстбоксов без
    # заливки над рядом нет, текстбоксов с заливкой в ряду и под ним — тоже),
    # поэтому различие видно только на добавленных фигурах:
    #   · [95] шапка-автофигура над рядом;
    #   · [96] подпись без заливки над рядом;
    #   · [97] текстбокс С ЗАЛИВКОЙ под рядом над DP и MEIO — без условия «выше
    #     ряда» он стал бы передачей DP → MEIO, выдуманной из подписи внизу;
    #   · [98] текстбокс с заливкой, залезающий на ряд (верх выше верха ряда,
    #     низ ниже) над MEIO и SNP — «целиком выше» значит по НИЖНЕЙ кромке, а
    #     не по верхней: плашка, наползшая на шевроны, передачей не считается.
    header = _s1(95, "auto", (0, 400_000, 3 * inch, 300_000), ["Шапка слайда"], "scheme:accent1")
    caption = _s1(96, "textbox", (4_500_000, 1_300_000, 600_000, 200_000), ["Подпись"], "noFill")
    filled_below = _s1(
        97, "textbox", (4 * inch, 6 * inch, int(2.5 * inch), 300_000), ["Сноска внизу"], plate_fill
    )
    straddling = _s1(
        98,
        "textbox",
        (int(6.5 * inch), row_top - 200_000, 2 * inch, 400_000),
        ["На ряду"],
        plate_fill,
    )
    extras_report = SlideReport(slide_no=1)
    try:
        with_extras = read_modules_slide(
            _slide1(extra=[header, caption, filled_below, straddling]), modules, extras_report
        )
    except SystemExit as error:
        check(False, f"фигуры вне правил плашки и ряда сломали разбор слайда 1: {error}")
        raise  # недостижимо
    check(
        [c.sid for c in with_extras.row.columns] == [41, 33, 23, 24, 34, 35]
        and [t.sid for t in with_extras.transfers] == [37, 21, 22, 36, 32],
        f"шапка, подпись, плашка под рядом или на ряду изменили колонки или передачи: "
        f"{[c.sid for c in with_extras.row.columns]}, {[t.sid for t in with_extras.transfers]}",
    )
    check(
        sorted(line.split("]")[0] for line in extras_report.text_skipped)
        == ["слайд 1: [38", "слайд 1: [95", "слайд 1: [96", "слайд 1: [97", "слайд 1: [98"],
        f"шапка, подпись, плашки под рядом и на ряду не попали в пропущенные фигуры: "
        f"{extras_report.text_skipped}",
    )

    # Списков действий у результата нет — ни одного поля, за которое их можно
    # было бы взять данными.
    check(
        set(ModulesSlide.__dataclass_fields__) == {"row", "transfers", "lanes"},
        f"у ModulesSlide появились поля: {set(ModulesSlide.__dataclass_fields__)}",
    )

    # match_module_box поодиночке. SNP БЕЗ абзаца с кодом: опознать его может
    # только префикс. Граница слова: «Планирование спросами» — не DP.
    def _box(*paragraphs: str) -> Shape:
        return _s1(99, "auto", (0, 0, inch, inch), paragraphs)

    by_prefix = match_module_box(_box("Планирование сети поставок и производства"), modules, 1)
    check(
        by_prefix is not None and (by_prefix[0].code, by_prefix[1]) == ("SNP", "prefix"),
        f"SNP без кода не опознан по префиксу: {by_prefix}",
    )
    check(
        match_module_box(_box("Планирование спросами клиентов"), modules, 1) is None,
        "префикс опознан без границы слова: «Планирование спросами» принято за DP",
    )
    for text in ("MRP", "(MRP)", "Material Requirement Planning (MRP)"):
        by_code = match_module_box(_box(text), modules, 1)
        check(
            by_code is not None and (by_code[0].code, by_code[1]) == ("MRP", "code"),
            f"коробка «{text}» не опознана как MRP по коду: {by_code}",
        )
    check(
        match_module_box(_box("Планирование промо", "(TPM)"), modules, 1) is None,
        "TPM опознан модулем реестра",
    )
    # Несколько модулей по одному правилу — остановка, а не «первый попавшийся»:
    # название «Планирование сети» — начало названия SNP.
    def _extra_module(code: str, title: str) -> ModuleRef:
        return ModuleRef(code=code, title=title, number=6, nav_slide=11, detail_slide=12)

    try:
        match_module_box(
            _box("Планирование сети поставок и производства"),
            (*modules, _extra_module("SN", "Планирование сети")),
            1,
        )
    except SystemExit as error:
        check(
            "по правилу 'prefix' подходит сразу к нескольким модулям" in str(error)
            and "SNP" in str(error)
            and "SN «Планирование сети»" in str(error),
            f"неоднозначное опознание остановило импорт не тем сообщением: {error}",
        )
    else:
        check(False, "коробка, подходящая к двум модулям по префиксу, не остановила импорт")

    # Сторож стрелок: любая стрелка, не ведущая слева направо, — остановка.
    # Идёт через read_modules_slide целиком: сторож, которого перестали звать,
    # краснеет здесь так же, как сломанное условие.
    # «Слева направо» — смещение по x строго больше нуля, и только оно: у
    # вертикальной линии оно ноль (остановка — граница «> 0», а не «≥ 0»), а
    # крутая диагональ вниз-вправо проходит (наклон задача не ограничивает).
    line_box = (3_296_920, 1_115_718, 619_760, 0)
    steep_box = (3_296_920, 800_000, 100_000, 619_760)
    vertical_box = (3_296_920, 800_000, 0, 619_760)
    for variant, what in (
        (_s1(25, "line", line_box, tail=True, flip_h=True), "отражённая линия (справа налево)"),
        (_s1(25, "line", line_box, head=True), "стрелка на начале линии (справа налево)"),
        (_s1(25, "line", line_box, head=True, tail=True), "стрелки на обоих концах"),
        (_s1(25, "line", steep_box, tail=True, flip_h=True), "диагональ справа налево (вниз)"),
        (_s1(25, "line", vertical_box, tail=True), "вертикальная линия"),
    ):
        stop = _slide1_stop(_slide1(replaced={25: variant}))
        check(
            stop is not None
            and "линии со стрелкой обязаны вести слева направо" in stop
            and "[25]" in stop,
            f"{what} не остановила импорт: {stop}",
        )
    steep_report = SlideReport(slide_no=1)
    stop = None
    try:
        read_modules_slide(
            _slide1(replaced={25: _s1(25, "line", steep_box, tail=True)}), modules, steep_report
        )
    except SystemExit as error:
        stop = str(error)
    check(
        stop is None
        and any(
            "линий со стрелкой 5, все ведут слева направо" in line
            for line in steep_report.module_transfers
        ),
        f"крутая диагональ вниз-вправо (в сторону +x) остановила импорт или не попала в "
        f"отчёт: {stop or steep_report.module_transfers}",
    )
    # Линий со стрелкой нет вовсе — не остановка, но и не молчание: направление
    # передач рисунком не подтверждено, и отчёт обязан это сказать.
    no_arrows_report = SlideReport(slide_no=1)
    read_modules_slide([s for s in _slide1() if s.kind != "line"], modules, no_arrows_report)
    check(
        "слайд 1: линий со стрелкой нет — направление передач рисунком не подтверждено, "
        "передачи прочитаны только по положению плашек" in no_arrows_report.module_transfers,
        f"слайд без линий со стрелкой не описан в отчёте: {no_arrows_report.module_transfers}",
    )

    # Плашка над тремя колонками (DP, MEIO, SNP) — остановка.
    wide_box = (3_916_680, 848_469, 3_500_000, 577_081)
    wide = _s1(90, "textbox", wide_box, ["Широкая плашка"], plate_fill)
    stop = _slide1_stop(_slide1(extra=[wide]))
    check(
        stop is not None and "[90]" in stop and "перекрывает колонок: 3 (DP, MEIO, SNP)" in stop,
        f"плашка над тремя колонками не остановила импорт: {stop}",
    )
    # Плашка ни над одной колонкой — пропуск с отчётом, не остановка.
    far_report = SlideReport(slide_no=1)
    far = _s1(94, "textbox", (12_150_000, 900_000, 40_000, 400_000), ["Сбоку"], plate_fill)
    read_modules_slide(_slide1(extra=[far]), modules, far_report)
    check(
        any("[94] «Сбоку» — ни над одной колонкой" in line for line in far_report.module_transfers),
        f"плашка вне колонок не попала в отчёт: {far_report.module_transfers}",
    )

    # Несоседние колонки: узкая колонка X между DP и MEIO, которую плашка не
    # задевает. На колоде так не бывает, поэтому ряд собран руками.
    def _column(sid: int, name: str, left: float, right: float, module: str | None) -> ModuleColumn:
        """Колонка по краям в дюймах."""
        return ModuleColumn(
            sid=sid,
            name=name,
            left=round(left * inch),
            right=round(right * inch),
            module=module,
            rule=None if module is None else "exact",
        )

    def _row(*columns: ModuleColumn) -> ChevronRow:
        return ChevronRow(columns=columns, top=inch, bottom=2 * inch)

    def _plate(left: float, right: float) -> Shape:
        """Плашка [91] по краям в дюймах."""
        box = (round(left * inch), 0, round((right - left) * inch), inch // 2)
        return _s1(91, "textbox", box, ["Плашка"], plate_fill)

    gap_row = _row(
        _column(1, "DP", 0, 3, "dp"),
        _column(2, "X", 0.5, 1, None),
        _column(3, "MEIO", 2.5, 6, "meio"),
    )
    try:
        classify_transfer(_plate(2, 4), gap_row, SlideReport(slide_no=1))
    except SystemExit as error:
        check(
            "[91]" in str(error) and "несоседние колонки DP, MEIO — между ними X" in str(error),
            f"несоседние колонки остановили импорт не тем сообщением: {error}",
        )
    else:
        check(False, "плашка над несоседними колонками не остановила импорт")
    # Обе колонки вне реестра — пропуск; вне реестра правая — только выход.
    outside_report = SlideReport(slide_no=1)
    outside_row = _row(
        _column(1, "TPM", 0, 2, None), _column(2, "XYZ", 2, 4, None), _column(3, "DP", 4, 6, "dp")
    )
    check(
        classify_transfer(_plate(1, 3), outside_row, outside_report) is None
        and any(
            "обе колонки вне реестра модулей" in line for line in outside_report.module_transfers
        ),
        f"плашка над двумя колонками вне реестра не пропущена с отчётом: "
        f"{outside_report.module_transfers}",
    )
    output_only = classify_transfer(
        _plate(1, 3),
        _row(_column(1, "DP", 0, 2, "dp"), _column(2, "XYZ", 2, 4, None)),
        SlideReport(slide_no=1),
    )
    check(
        output_only is not None and (output_only.source, output_only.target) == ("dp", None),
        f"плашка над DP и колонкой вне реестра — не только выход DP: {output_only}",
    )
    # Касание кромкой — не перекрытие (columns_under). Фигуры, притянутые в
    # PowerPoint к направляющим, встают кромка в кромку сплошь и рядом: с
    # «≥ 0» плашка над DP и MEIO, коснувшаяся SNP, остановила бы импорт (три
    # колонки), а плашка над одним MEIO, коснувшаяся SNP, стала бы передачей.
    # Колонки DP и MEIO перекрываются, как шевроны на слайде; MEIO и SNP —
    # кромка в кромку.
    touch_row = _row(
        _column(1, "DP", 0, 2, "dp"),
        _column(2, "MEIO", 1.5, 4, "meio"),
        _column(3, "SNP", 4, 6, "snp"),
    )
    try:
        touching = classify_transfer(_plate(1, 4), touch_row, SlideReport(slide_no=1))
    except SystemExit as error:
        touching = None
        check(False, f"плашка, коснувшаяся SNP кромкой, остановила импорт: {error}")
    check(
        touching is not None and (touching.source, touching.target) == ("dp", "meio"),
        f"плашка над DP и MEIO, коснувшаяся SNP кромкой, — не передача DP → MEIO: {touching}",
    )
    touch_report = SlideReport(slide_no=1)
    single = classify_transfer(_plate(2.5, 4), touch_row, touch_report)
    check(
        single is None
        and touch_report.module_transfers
        == [
            "слайд 1: [91] «Плашка» — над одной колонкой MEIO: передачи между двумя модулями "
            "нет, не импортируется"
        ],
        f"плашка над одним MEIO, коснувшаяся SNP кромкой, стала передачей или ушла в отчёт "
        f"не так: {single}, {touch_report.module_transfers}",
    )

    # Ряд модулей не сходится с реестром: модуля нет в ряду; модуль в ряду
    # дважды; не опознано ничего; два ряда поровну.
    stop = _slide1_stop(_slide1(), (*modules, _extra_module("XX", "Нет такого модуля")))
    check(
        stop is not None and "модуль XX «Нет такого модуля» — его коробки в ряду нет" in stop,
        f"модуль реестра без коробки в ряду не остановил импорт: {stop}",
    )
    second_dp = _s1(93, "auto", (12_200_000, row_top, 500_000, 500_000), ["(DP)"])
    stop = _slide1_stop(_slide1(extra=[second_dp]))
    check(
        stop is not None and "модуль DP — коробки [33], [93]" in stop,
        f"две коробки одного модуля не остановили импорт: {stop}",
    )
    stop = _slide1_stop([s for s in _slide1() if s.sid in (41, 38, 44)])
    check(
        stop is not None and "ни одна автофигура с текстом не опознана как модуль реестра" in stop,
        f"слайд без коробок модулей не остановил импорт: {stop}",
    )
    stop = _slide1_stop(
        [
            _s1(1, "auto", (0, row_top, inch, inch), ["(DP)"]),
            _s1(2, "auto", (0, row_top + 2 * inch, inch, inch), ["(MEIO)"]),
        ],
        modules[:2],
    )
    check(
        stop is not None and "рядов с наибольшим числом опознанных модулей (1) несколько" in stop,
        f"два ряда поровну не остановили импорт: {stop}",
    )

    # Полоса: без кода — остановка; над двумя колонками — не полоса, а пропуск
    # с отчётом; id, занятый модулем, — остановка.
    fpa_box = (1_040_022, 6_067_093, 10_527_527, 500_435)

    def _lane(box: tuple[int, int, int, int], *paragraphs: str) -> dict[int, Shape]:
        """Подмена полосы FP&A [44] для _slide1."""
        return {44: _s1(44, "auto", box, paragraphs, "srgb:00B050")}

    # Каждая остановка — своей причиной в сообщении: одна общая фраза «нужны
    # название и код» пропустила бы подмену одного условия другим.
    for lane_paragraphs, reason, what in (
        (
            ("Финансовое планирование и анализ",),
            "в конце последнего абзаца нет кода в скобках",
            "полоса без кода",
        ),
        (
            ("Financial Planning and Analysis (FP&A)",),
            "абзац один — код есть, а названия над ним нет",
            "полоса одним абзацем с кодом",
        ),
        # Английское название первым: подписью стало бы «FP&A · Financial
        # Planning», а подпись — код и РУССКОЕ название (решение 9mn.31, п. 5).
        (
            ("Financial Planning", "Financial Planning and Analysis (FP&A)"),
            "первый абзац «Financial Planning» не русский",
            "полоса с английским первым абзацем",
        ),
        (
            ("Финансовое планирование и анализ", "Financial Planning and Analysis (1&2)"),
            "в коде «1&2» нет латинских букв",
            "полоса с кодом без букв",
        ),
    ):
        stop = _slide1_stop(_slide1(replaced=_lane(fpa_box, *lane_paragraphs)))
        check(
            stop is not None and "полоса [44]" in stop and reason in stop,
            f"{what} не остановила импорт или остановила не той причиной: {stop}",
        )
    narrow_report = SlideReport(slide_no=1)
    narrow = read_modules_slide(
        _slide1(
            replaced=_lane(
                (4_000_000, 6_067_093, 1_500_000, 500_435),
                "Финансовое планирование и анализ",
                "Financial Planning and Analysis (FP&A)",
            )
        ),
        modules,
        narrow_report,
    )
    check(
        not narrow.lanes and any("[44]" in line for line in narrow_report.text_skipped),
        f"автофигура под двумя колонками стала полосой или пропала молча: "
        f"{narrow.lanes}, {narrow_report.text_skipped}",
    )
    stop = _slide1_stop(
        _slide1(replaced=_lane(fpa_box, "Планирование спроса", "Demand Planning (DP)"))
    )
    check(
        stop is not None and "id «dp» уже занят модулем" in stop,
        f"полоса с id модуля не остановила импорт: {stop}",
    )

    # Сверка списков действий — только отчёт. Шаги MEIO записаны через «е», а
    # список — через «ё»; шаги DP — заглавными: ни то, ни другое не расхождение.
    # Шагов PS не передано: сверка обязана сказать это, а не промолчать. Список
    # [92] правее MRP не лежит ни под одной колонкой: его нельзя приписать
    # ближайшей колонке (MRP) — перекрытия с ней нет, есть только расстояние.
    stray_list = _s1(92, "textbox", (12_140_000, 2_808_658, 50_000, 300_000), ["Заметка"], "noFill")
    reconcile_activity_lists(
        _slide1(extra=[stray_list]),
        slide1.row,
        {
            "dp": ["Ведение новинки", "СЕГМЕНТАЦИЯ", "Обогащение прогноза"],
            "meio": ["Расчет рекомендаций по уровням запасов"],
            "snp": ["Первичный анализ спроса и выявление проблем"],
        },
        s1_report,
    )
    found_in_steps = "среди шагов слайда детализации нашлось строк"
    unlisted_steps = "  шагов слайда детализации, которых в списке нет:"
    check(
        s1_report.activity_check
        == [
            "слайд 1: список [40] под колонкой TPM — колонка вне реестра модулей, "
            "не сверяется (строк: 1)",
            f"слайд 1: список [19] под колонкой DP: {found_in_steps} 2 из 3",
            "  = Ведение новинки",
            "  = Сегментация",
            "  ≠ Передача неограниченного прогноза — среди шагов нет",
            f"{unlisted_steps} 1",
            f"слайд 1: список [39] под колонкой MEIO: {found_in_steps} 1 из 1",
            "  = Расчёт рекомендаций по уровням запасов",
            f"{unlisted_steps} 0",
            f"слайд 1: список [28] под колонкой SNP: {found_in_steps} 0 из 1",
            "  ≠ Supply Review Meeting — среди шагов нет",
            f"{unlisted_steps} 1",
            "слайд 1: список [30] под колонкой PS — шаги слайда детализации модуля не "
            "переданы, не сверяется",
            "слайд 1: список [92] «Заметка» не лежит ни под одной колонкой — не сверяется",
            "слайд 1: MRP — списка действий под колонкой нет, сверять нечего",
        ],
        f"сверка списков действий: {s1_report.activity_check}",
    )

    # Печать: четыре блока слайда 1 есть в отчёте, где их заполняли, и нет в
    # отчёте, где слайда модулей не читали (отчёты SNP и MRP — побайтово прежние).
    slide1_headers = (
        "КОРОБКИ МОДУЛЕЙ НА СЛАЙДЕ 1",
        "ПЕРЕДАЧИ МЕЖДУ МОДУЛЯМИ",
        "ПОЛОСЫ УРОВНЯ 1",
        "СПИСКИ ДЕЙСТВИЙ СЛАЙДА 1",
    )
    slide1_text = _report_text(s1_report)
    lines = (
        s1_report.module_columns
        + s1_report.module_transfers
        + s1_report.module_lanes
        + s1_report.activity_check
    )
    check(
        all(header in slide1_text for header in slide1_headers)
        and all(line.strip() in slide1_text for line in lines),
        "print_report не напечатал блоки слайда 1",
    )
    empty_text = _report_text(SlideReport(slide_no=2))
    check(
        not any(header in empty_text for header in slide1_headers),
        "блоки слайда 1 напечатаны в отчёте, где слайда модулей не читали",
    )

    print(f"САМОПРОВЕРКА ПРОЙДЕНА: {checks} проверок")
    return 0


# --------------------------------------------------------------------------------------
# Командная строка (process-map-9mn.14.1, закрывает process-map-5o8)
# --------------------------------------------------------------------------------------

# Флаги без значения. `--map` — единственный флаг со значением, разбирается отдельно.
SWITCHES = ("--self-test", "--in-pipeline", "--dry-run", "--help")

# Для сообщений: всё, что parse_args принимает, в порядке справки.
KNOWN_ARGS = ("--map <ключ>", "--dry-run", "--in-pipeline", "--self-test", "--help")


@dataclass(frozen=True)
class CliArgs:
    """Разобранная командная строка. map_key None — карта по умолчанию (DEFAULT_MAP)."""

    map_key: str | None = None
    self_test: bool = False
    in_pipeline: bool = False
    dry_run: bool = False
    help: bool = False


def usage(maps: Mapping[str, MapSpec] = MAPS) -> str:
    """Текст --help. Список карт — из реестра, чтобы справка не протухала."""
    return (
        "Использование:\n"
        "  python scripts/import-pptx.py [--map <ключ>] [--dry-run] [--in-pipeline]\n"
        "  python scripts/import-pptx.py --self-test\n"
        "  python scripts/import-pptx.py --help\n"
        "\n"
        f"  --map <ключ>     какую карту собирать: {', '.join(sorted(maps))}; "
        f"по умолчанию {DEFAULT_MAP}\n"
        "  --dry-run        собрать карту и напечатать отчёт, НИЧЕГО не записывая\n"
        "  --in-pipeline    ставит scripts/data.ts: раскладка стартует следом\n"
        "  --self-test      самопроверка импортёра, презентация не нужна\n"
        "  --help           эта справка; ничего не пишет\n"
        "\n"
        "Импорт — первая половина конвейера. Обычный путь — весь конвейер сразу:\n"
        "  npm run data -- --map <ключ>     (самопроверка → import-pptx.py → layout.ts)"
    )


def parse_args(argv: Sequence[str]) -> CliArgs:
    """
    Разбор аргументов — СТРОГИЙ: принимаются только KNOWN_ARGS.

    ЗАЧЕМ (process-map-5o8). main() раньше смотрел только на --self-test, --map
    и --in-pipeline, а прочее молча пропускал. `--help` поэтому не печатал
    справку, а ПОЛНОСТЬЮ пересобирал карту по умолчанию и переписывал
    src/data/snp/process.json сырой геометрией слайда — без раскладки, то есть в
    промежуточном состоянии, от которого предостерегает шапка файла. Опечатка
    `--dryrun` сделала бы то же самое с человеком, который как раз хотел ничего
    не писать. Теперь любой неизвестный аргумент — остановка со списком
    известных, тем же приёмом, каким resolve_map_spec отвергает неизвестную
    карту.

    Режимы не смешиваются молча. --help побеждает всё остальное (справка ничего
    не пишет, и сочетание с ней безвредно). --self-test вместе с --map,
    --dry-run или --in-pipeline — остановка: самопроверка карт не собирает, и
    `--self-test --map mrp` обещал бы то, чего не делает, — ровно та тихая
    игнорировка флага, от которой этот разбор и защищает.
    """
    args = list(argv)
    switches: set[str] = set()
    map_key: str | None = None
    unknown: list[str] = []
    index = 0
    while index < len(args):
        token = args[index]
        index += 1
        if token == "--map":
            # Значение, похожее на флаг, — это пропущенное значение, а не имя
            # карты: `--map --dry-run` иначе стал бы «неизвестной картой
            # --dry-run» и потерял бы флаг.
            if index >= len(args) or args[index].startswith("--"):
                raise SystemExit("--map требует значение, например: --map snp")
            if map_key is not None:
                raise SystemExit(
                    f"--map указан дважды («{map_key}» и «{args[index]}») — "
                    f"какую карту собирать, непонятно"
                )
            map_key = args[index]
            index += 1
        elif token in SWITCHES:
            switches.add(token)
        else:
            unknown.append(token)
    if unknown:
        raise SystemExit(
            f"Неизвестные аргументы: {' '.join(unknown)}. "
            f"Известны: {', '.join(KNOWN_ARGS)}.\n"
            f"Ничего не собрано и не записано. Справка: python scripts/import-pptx.py --help"
        )
    cli = CliArgs(
        map_key=map_key,
        self_test="--self-test" in switches,
        in_pipeline="--in-pipeline" in switches,
        dry_run="--dry-run" in switches,
        help="--help" in switches,
    )
    if cli.self_test and not cli.help and (map_key is not None or cli.dry_run or cli.in_pipeline):
        raise SystemExit(
            "--self-test не сочетается с --map, --dry-run и --in-pipeline: самопроверка "
            "карт не собирает и ничего не пишет. Запустите её отдельно."
        )
    return cli


def resolve_map_spec(key: str | None, maps: Mapping[str, MapSpec] = MAPS) -> MapSpec:
    """
    Какую карту собираем: значение `--map`, по умолчанию snp.

    Неизвестный ключ — остановка со списком известных, а не тихий откат на
    карту по умолчанию: молчаливая пересборка не той карты затёрла бы чужой
    файл данных.
    """
    key = DEFAULT_MAP if key is None else key
    spec = maps.get(key)
    if spec is None:
        raise SystemExit(f"Неизвестная карта «{key}». Известны: {', '.join(sorted(maps))}")
    return spec


def shown_path(path: Path) -> str:
    """
    Путь для отчёта: от корня репозитория, если файл в нём (рабочий путь), иначе
    как есть — так пишет самопроверка, чьи файлы лежат во временном каталоге.
    """
    try:
        return path.relative_to(ROOT).as_posix()
    except ValueError:
        return path.as_posix()


def print_dry_run(spec: MapSpec) -> None:
    """Последний блок прогона с --dry-run — вместо «записано» и требования раскладки."""
    print("\n" + "=" * 78)
    print("--dry-run: НИЧЕГО НЕ ЗАПИСАНО")
    print("=" * 78)
    print(f"  {shown_path(spec.json)} и {shown_path(spec.required_nodes)} остались как были.")
    print("  Отчёт выше — то, что записал бы обычный прогон; раскладка не нужна:")
    print("  файл карты не менялся.")


def main(
    argv: Iterable[str],
    *,
    maps: Mapping[str, MapSpec] = MAPS,
    tables: Mapping[str, Sequence[dict]] = DECISION_TABLES,
    builders: Mapping[str, Builder] = PROFILE_BUILDERS,
    self_test: Callable[[], int] = run_self_test,
) -> int:
    """
    Точка входа. Именованные параметры — ТОЛЬКО для самопроверки: она гоняет
    main() целиком на подставных реестрах (карта во временном каталоге,
    построитель-фикстура), чтобы проверить порядок шагов, а не отдельные
    функции, — подмена глобалей в этом файле не практикуется (см. пункт 1d
    самопроверки). Рабочий путь зовёт main(sys.argv[1:]).

    `self_test` подставляется по той же причине: самопроверка проверяет, что
    `--self-test --help` печатает справку, а не запускает самопроверку. Настоящая
    run_self_test на этом месте при сломанном порядке вызвала бы саму себя, и
    вместо названной проверки прогон упал бы переполнением стека.
    """
    # Отчёт содержит кириллицу и стрелки: на консоли с cp866/cp1251 печать иначе
    # падает с UnicodeEncodeError уже после записи файлов.
    for stream in (sys.stdout, sys.stderr):
        if hasattr(stream, "reconfigure"):
            stream.reconfigure(encoding="utf-8", errors="replace")

    cli = parse_args(list(argv))
    # --help — ДО --self-test: справка побеждает всё (см. parse_args), и
    # `--self-test --help` обязан только напечатать её.
    if cli.help:
        print(usage(maps))
        return 0
    if cli.self_test:
        return self_test()

    # Решения владельца, которые не применятся никогда (process-map-9mn.25,
    # вариант (а)). ДО сборки и до чтения чего-либо с диска: такая запись —
    # ошибка объявления, а не данных, и разбирать ради неё презентацию незачем.
    # Проверяются все карты реестра, а не только собираемая, — см.
    # unread_decisions.
    unread = unread_decisions(tables, maps, PROFILE_READS)
    if unread:
        raise SystemExit(
            "Решения владельца объявлены для карт, чей профиль эти таблицы не читает, — "
            "они не применятся никогда (PROFILE_READS, process-map-9mn.25):\n"
            + "\n".join(f"  · {item}" for item in unread)
            + "\nПеренесите решение в таблицу, которую профиль читает, научите построитель "
            "читать таблицу (и объявите это в PROFILE_READS) или удалите запись. "
            "Импорт остановлен до сборки, ничего не записано."
        )

    spec = resolve_map_spec(cli.map_key, maps)
    # Профиль разбора: устройство презентации у карт разное (MapSpec.profile).
    # Неизвестный профиль останавливает импорт здесь, до чтения файлов.
    build = builder_for(spec, builders)

    # --in-pipeline ставит scripts/data.ts (npm run data): раскладка стартует
    # сразу после импорта, и требовать её отдельно уже не надо. На сам импорт
    # флаг не влияет — только на текст финального блока.

    # Ручной слой читаем ДО сборки: если предыдущий файл битый, лучше упасть
    # раньше, чем после разбора презентации.
    previous = load_previous_map(spec.json)

    # Фаза 1 — подсчёт коллизий базовых slug'ов, фаза 2 — стабильные id.
    _, _, _, collisions = build(None, spec)
    process_map, reports, questions, _ = build(dict(collisions), spec)

    carry_over = carry_over_manual_fields(process_map, previous)

    check_unique_ids(process_map)
    # --dry-run: всё то же, кроме записи. Сборка, перенос ручных полей и
    # проверка id идут полностью — иначе отчёт показывал бы не то, что записал бы
    # обычный прогон.
    if not cli.dry_run:
        write_json(spec.json, process_map)
        write_json(spec.required_nodes, collect_required_node_ids(process_map))
    print_report(process_map, reports, questions, spec)
    print_carry_over(carry_over, spec)
    if cli.dry_run:
        print_dry_run(spec)
    else:
        print(f"\nзаписано: {shown_path(spec.json)}")
        print(f"записано: {shown_path(spec.required_nodes)}")
        print_layout_required(process_map, cli.in_pipeline)
    if carry_over.lost:
        # Под --dry-run код тот же: так пробный прогон годится проверкой «не
        # потеряет ли настоящий импорт ссылок», хотя сам ничего не потерял.
        consequence = (
            "Обычный прогон потерял бы их; файл не тронут."
            if cli.dry_run
            else "Список выше — проставьте их заново в редакторе."
        )
        print(
            f"\nВНИМАНИЕ: потеряно ручных полей: {len(carry_over.lost)} "
            f"(из них ссылок на экраны: {carry_over.screens_lost}). "
            f"{consequence} Код возврата {EXIT_LINKS_LOST}."
        )
        return EXIT_LINKS_LOST
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
